/* A = attesté par les sources, le reste est signalé dans la carte */
const EV={
 combo:{sys:1,tag:'',an:'',get t(){return 'Savoir acquis : '+((COMBOS[S.comboN]||{}).n||'')},get b(){const C=COMBOS[S.comboN]||{};return 'Savoir acquis, car vos gens connaissent déjà ce qu’il fallait'+(C.ind?' — '+C.ind.replace(/…$/,'').toLowerCase():'')+'. '+(C.d||'')},v:'Les savoirs mûrissent avec les années et se combinent.',o:[{n:'Transmettre aux enfants',d:'Anciens +2',fx:{anciens:2}}]},
 voieSilat:{sys:1,tag:'Conte',an:'',t:'Le silat des îles',b:'Des marins d’Insulinde se battent comme l’eau qui coule : bas, souples, la lame courbe du kriss à la ceinture. Ils disent que leurs maîtres apprenaient en regardant le tigre et l’oiseau.',v:'Vos chasseurs bougent sans bruit dans la forêt.',h:'Le pencak silat est l’art martial d’Indonésie et du monde malais, inscrit au patrimoine immatériel de l’UNESCO en 2019. Les récits d’origine liés aux animaux font partie de ses traditions. Le lien avec les marrons est une fiction du jeu.',o:[{n:'Apprendre à se fondre',d:'Traque -3, gardiens +2',fx:{traque:-3,gardiens:2}}]},
 voieBirmane:{sys:1,tag:'Conte',an:'',t:'Les boxeurs de Birmanie',b:'Sur la côte de Mergui, des marins birmans se battent poings nus, sans gants, la tête comme une arme. Avant le combat, ils dansent pour saluer leurs maîtres.',v:'Vos équipages ne reculent plus à l’abordage.',h:'Le lethwei est la boxe traditionnelle birmane, à mains nues, où les coups de tête sont permis. Le lien avec les marrons est une fiction du jeu.',o:[{n:'Endurcir les équipages',d:'Gardiens +3',fx:{gardiens:3}}]},
 voieTamoule:{sys:1,tag:'Conte',an:'',t:'La voie des points vitaux',b:'Un maître venu de la côte tamoule montre aux vôtres cent huit points du corps : ceux qui tuent, ceux qui guérissent. Le même geste peut abattre un chasseur ou remettre debout un blessé. Il dit que le souffle passe par ces points comme l’eau dans les ravines.',v:'Un mystique guerrier et guérisseur naît dans vos camps : mystique +1.',h:'Le varmam et le varma kalai sont l’art tamoul des points vitaux, lié à la médecine siddha. La tradition en attribue l’origine à Shiva et au sage Agastya. Le silambam est l’art tamoul du bâton. Le lien avec les marrons de Bourbon est une fiction du jeu.',o:[{n:'Former des guérisseurs-guerriers',d:'Santé +3, gardiens +3',fx:{sante:3,gardiens:3}}]},
 voieKhmer:{sys:1,tag:'Conte',an:'',t:'Les combattants du Mékong',b:'Des marins khmers montrent leurs prises : coudes, genoux, saisies. Ils disent que leurs ancêtres combattaient déjà ainsi sous les temples d’Angkor, et que la sirène Suvannamaccha protège ceux qui se battent sur l’eau.',v:'Un mystique naval : vos abordages deviennent redoutables.',h:'Le bokator est un art martial khmer ; ses pratiquants le rattachent aux bas-reliefs d’Angkor. Les boxes siamoise (muay thai) et khmère partagent coudes et genoux, et les arts de combat d’Asie du Sud-Est ont échangé avec ceux de l’Inde et de la Chine. Le lien avec les marrons est une fiction du jeu.',o:[{n:'Entraîner les équipages',d:'Gardiens +4, mystique +1',fx:{gardiens:4,myst:1}}]},
 ep_comores1:{sys:1,tag:'Archive',an:'',t:'Anjouan, l’escale des pirates',b:'Dans la rade d’Anjouan, les navires font de l’eau et achètent des vivres. On y croise des boutres arabes, des pirates anglais et des marchands swahilis. Le sultan regarde tout le monde passer.',v:'Un lien qui nourrit et qui renseigne sur les routes.',h:'Anjouan (Ndzuani) était une escale très fréquentée par les navires de l’océan Indien à la fin du XVIIe siècle, pirates compris. Les Comores étaient divisées en sultanats de culture swahilie et arabo-shirazie.',o:[{n:'Échanger des vivres',d:'Vivres +6, savoir +1',fx:{vivres:6,savoir:1}}]},
 ep_comores2:{y:1700,si:()=>S.out&&S.out.comores,tag:'Conte',an:'',t:'Les esprits qui parlent par la bouche',b:'Une nuit de tambours, une femme d’Anjouan entre en transe. Ce n’est plus elle qui parle, c’est un esprit venu de la mer. Il réclame du parfum, du tabac, une étoffe rouge.',v:'Vos gens apprennent qu’on peut négocier avec les esprits.',h:'Aux Comores et à Mayotte, les cultes de possession par des esprits (trumba, patrosi) existent encore aujourd’hui.',o:[{n:'Offrir ce que l’esprit demande',d:'Mystique +2',fx:{myst:2}}]},
 ep_comores3:{y:1715,si:()=>S.out&&S.out.comores,tag:'Imaginaire',an:'',t:'Le Karthala répond au Piton',b:'Quand la Fournaise gronde, le Karthala de la Grande Comore gronde aussi, disent les marins. Les deux feux se parlent sous la mer.',v:'Un récit qui relie vos montagnes aux îles du nord.',h:'Le Karthala est un volcan actif de la Grande Comore. Le dialogue des deux volcans est une fiction du jeu.',o:[{n:'Garder ce récit',d:'Anciens +2, mystique +1',fx:{anciens:2,myst:1}}]},
 ep_seych1:{sys:1,tag:'Archive',an:'',t:'Des îles sans personne',b:'Des îles de granit au milieu de la mer, des plages vides, des tortues partout. Les pirates y cachent leurs navires entre deux prises.',v:'Un refuge pour vos marins, loin des colonies.',h:'Les Seychelles n’avaient pas d’habitants permanents avant la première installation française, en 1770, sur l’île Sainte-Anne.',o:[{n:'Y cacher un dépôt de vivres',d:'Vivres +5',fx:{vivres:5}}]},
 ep_seych2:{y:1731,si:()=>S.out&&S.out.seych,tag:'Conte',an:'',t:'Le trésor de La Buse',b:'On raconte que le pirate La Buse, avant d’être pendu, a jeté un cryptogramme à la foule : celui qui saura le lire trouvera son trésor. Certains disent qu’il dort à Bel Ombre, sur Mahé.',v:'Chercher coûte du temps. Trouver, c’est autre chose.',h:'Olivier Levasseur, dit La Buse, a été pendu à Saint-Paul de Bourbon en 1730. La légende de son trésor, parfois placé à Bel Ombre (Mahé), fait chercher depuis le XXe siècle. Rien n’a été trouvé.',o:[{n:'Chercher le trésor',d:'Une chance sur quatre : fusils +2 et bois +4',fx:{},f:()=>{if(Math.random()<.25){S.fu=(S.fu||0)+2;S.res.bois+=4;log('Dans une grotte de Mahé : des caisses pourries, deux fusils encore bons.')}else log('Le trésor de La Buse reste introuvable.')}},{n:'Laisser la légende tranquille',d:'Rien',fx:{}}]},
 ep_seych3:{y:1740,si:()=>S.out&&S.out.seych,tag:'Conte',an:'',t:'Le coco de mer',b:'Dans une vallée humide pousse un palmier unique au monde. Ses noix ont une forme qui fait rire les marins. Les anciens disent que, les nuits de tempête, les palmiers mâles et femelles se rejoignent, et que celui qui les voit meurt.',v:'Un lieu sacré, à respecter.',h:'Le coco de mer ne pousse naturellement qu’aux Seychelles, notamment dans la Vallée de Mai (Praslin). La croyance des palmiers qui s’unissent les nuits d’orage fait partie du folklore seychellois.',o:[{n:'Respecter la vallée',d:'Mystique +2',fx:{myst:2}}]},
 ep_rodr1:{sys:1,tag:'Archive',an:'',t:'Les huguenots de Leguat',b:'Sur cette petite île, des Français protestants ont vécu deux ans au milieu de tortues si nombreuses qu’on marchait sur leurs dos. Ils décrivaient un grand oiseau solitaire, fidèle à sa compagne.',v:'Un savoir sur les bêtes des îles.',h:'François Leguat et ses compagnons huguenots ont vécu sur Rodrigues de 1691 à 1693. Leur récit décrit les tortues géantes et le solitaire de Rodrigues.',o:[{n:'Retenir leurs observations',d:'Savoir +2',fx:{savoir:2}}]},
 ep_rodr2:{y:1750,si:()=>S.out&&S.out.rodr,tag:'Archive',an:'',t:'Le dernier solitaire de Rodrigues',b:'Les marins chargent les tortues par centaines dans les cales. Le grand oiseau de Leguat ne se montre plus.',v:'Une mémoire à garder, comme celle de vos propres oiseaux.',h:'Le solitaire de Rodrigues a disparu au XVIIIe siècle ; les tortues géantes de l’île ont été exterminées par les prélèvements des navires.',o:[{n:'Garder leur mémoire',d:'Anciens +3',fx:{anciens:3}}]},
 trom1:{y:1761,si:()=>S.out&&(S.out.mada||S.out.maurice),tag:'Archive',an:'1761',t:'Les oubliés de l’île de Sable',b:'Le navire négrier L’Utile s’échoue sur un îlot de sable perdu dans la mer. L’équipage français construit un bateau et repart. Il laisse sur place environ 80 Malgaches, avec la promesse de revenir.',v:'Une mémoire de l’esclavage à ne pas oublier.',h:'Naufrage de L’Utile en 1761 sur l’île de Sable, aujourd’hui Tromelin. Les esclaves malgaches abandonnés y survivent quinze ans.',o:[{n:'Se souvenir',d:'Anciens +3, marronnage +3',fx:{anciens:3},vo:{m:3}}]},
 trom2:{y:1776,si:()=>S.done.trom1,tag:'Archive',an:'1776',t:'Quinze ans après',b:'Un navire commandé par le chevalier de Tromelin aborde enfin l’îlot. Il trouve sept femmes et un bébé de huit mois. Ils ont survécu quinze ans en gardant le feu allumé.',v:'Le feu gardé : un symbole pour tous les camps.',h:'Le 29 novembre 1776, le chevalier de Tromelin récupère sept femmes et un enfant. L’îlot porte depuis son nom. Des fouilles archéologiques y ont été menées à partir de 2006.',o:[{n:'Honorer les survivantes',d:'Cohésion +5, mystique +2',fx:{coh:5,myst:2}}]},
 libCharte:{sys:1,tag:'Mythe',nat:'Libertalia est un mythe. Le jeu en fait une république pirate à part, contre les royautés esclavagistes.',an:'',t:'La charte de Libertalia',b:'Au nord de Madagascar, face aux Comores, des pirates de toutes les mers ont fondé une république. Ils ont jeté leurs pavillons et pris un drapeau blanc : ni roi, ni esclave. Chaque négrier pris devient une flotte d’hommes libres. Marins malgaches, comoriens, swahilis, et des fuyards venus d’Asie y parlent toutes les langues.',v:'Tant que Libertalia est forte, elle libère des captifs et vous envoie des bras. Les royautés européennes la pourchassent.',h:'Libertalia apparaît dans « A General History of the Pyrates » (1724), attribué au capitaine Charles Johnson, avec le capitaine Misson et Thomas Tew. Les historiens pensent que la colonie a été inventée. Les pirates ont pourtant vraiment fréquenté Madagascar (l’île Sainte-Marie) et les Comores (Anjouan) entre les années 1690 et 1720.',o:[{n:'Envoyer un messager aux frères',d:'Libertalia +10, mystique +1',fx:{myst:1},f:()=>{S.lib=(S.lib||50)+10}},{n:'Garder ses distances',d:'Traque -2',fx:{traque:-2}}]},
 libTombe:{sys:1,tag:'Mythe',an:'',t:'Libertalia est tombée',b:'Les frégates des rois ont brûlé la baie. Les derniers frères se dispersent. Certains prennent une lettre de marque et deviennent corsaires, d’autres montent rejoindre les camps des Hauts.',v:'Plus de raids libérateurs. La colonisation de Madagascar commence.',h:'La fin de Libertalia appartient au mythe. La piraterie de l’océan Indien recule réellement dans les années 1720, sous la pression des marines européennes et des amnisties.',o:[{n:'Accueillir les rescapés',d:'+3 personnes, traque +4',fx:{gens:3,traque:4}},{n:'Les laisser devenir corsaires',d:'Colonial +6',fx:{},vo:{c:6}}]},
 voile:{sys:1,tag:'Imaginaire',an:'',get t(){const v=S.voile||{};return 'Une voile '+(v.nat==='pirate'?'sans pavillon, pirate':v.nat==='francais'?'française':v.nat==='anglais'?'anglaise':v.nat==='hollandais'?'hollandaise':'portugaise')+' à l’horizon'},
  get b(){const v=S.voile||{};return {marchand:'Un navire marchand lourd de riz, de toiles et de fusils remonte vers les comptoirs.',negrier:'Un navire négrier : on entend les chaînes jusque sur l’eau. Il emporte '+v.cap+' captifs vers les plantations.',fregate:'Une frégate de guerre, ses sabords ouverts, patrouille le long des côtes.'}[v.type]+' Vos pirogues et le sloop de vos alliés pirates sont prêts.'},
  v:'Attaquer ouvre un combat naval. Les Anglais et les Français se souviendront de qui vous attaquez : ennemis des uns, amis des autres.',
  h:'Les comptoirs marrons reliés au réseau pirate sont une fiction du jeu. Mais l’océan Indien a bien connu un âge d’or de la piraterie, des années 1690 aux années 1720, puis les guerres franco-anglaises de 1744-1748 et 1756-1763.',
  get o(){const v=S.voile||{},n=S.nav||{},ami=(v.nat==='francais'&&n.francais>=20)||(v.nat==='anglais'&&n.anglais>=20);const L=[{n:'Attaquer',d:'Ouvre le combat naval.',f:()=>{setTimeout(navOuvrir,50)}},{n:'Laisser passer',d:'Rien ne se passe.',fx:{}}];if(ami)L.push({n:'Saluer et échanger',d:'Ami : vivres +6, savoir +1',fx:{vivres:6,savoir:1}});return L}},
 marqueFr:{sys:1,tag:'Imaginaire',an:'',t:'Une lettre de marque française',b:'Un officier de Bourbon vient en secret : vos prises sur les Anglais servent le roi. Il vous offre une lettre de marque. Vos pirates deviennent corsaires.',v:'Les frégates françaises vous laissent passer, et la colonie lâche un peu la traque.',h:'Les corsaires français opéraient avec une lettre de marque du roi, comme ceux de La Bourdonnais en 1746. Des marrons corsaires sont une fiction du jeu.',o:[{n:'Accepter',d:'Traque -10, colonial +4',fx:{traque:-10},vo:{c:4}},{n:'Refuser, rester libres',d:'Marronnage +4',fx:{},vo:{m:4}}]},
 marqueEn:{sys:1,tag:'Imaginaire',an:'',t:'Les Anglais tendent la main',b:'Une frégate anglaise mouille au large. Son capitaine veut des pilotes qui connaissent la côte de Bourbon. En échange : fusils et poudre.',v:'Amis des Anglais, ennemis de Bourbon : la colonie vous hait davantage.',h:'Les Anglais ont convoité les Mascareignes et pris Bourbon en 1810. Leur alliance avec des marrons est une fiction du jeu.',o:[{n:'Accepter',d:'Fusils +3, traque +8',fx:{traque:8},f:()=>{S.fu=(S.fu||0)+3}},{n:'Refuser',d:'Rien',fx:{}}]},
 chasseFr:{sys:1,tag:'Imaginaire',an:'',t:'La marine française vous traque',b:'Trop de navires français pillés : Bourbon arme deux frégates pour détruire vos comptoirs.',v:'Un comptoir est perdu pour plusieurs saisons.',o:[{n:'Se replier',d:'Traque +10',fx:{traque:10},f:()=>{const k=Object.keys(S.out||{})[0];if(k){delete S.out[k];log('Le comptoir '+OUT[k].n+' est détruit par la marine française.')}}}]},
 election:{sys:1,tag:'Archive',an:'',t:'L’élection du grand roi',b:'Les chefs de chaque camp se réunissent au plus haut des pitons. Selon les récits, les rois de chaque partie de l’île élisent un grand roi pour tout l’intérieur. Chaque chef garde son territoire, avec ses capitaines, ses lieutenants et sa reine.',v:'Un roi des archives oriente votre royaume vers l’histoire vraie. Un roi de la tradition l’oriente vers le conte et la mystique.',h:'Organisation décrite dans « Le marronnage à Bourbon » (portail de l’esclavage) : un grand roi élu par les rois locaux, des chefferies, des capitaines et des lieutenants, des reines, un tombeau de pierre sèche pour le roi mort.',
  get o(){return Object.keys(ROIS).filter(k=>!S.done['mort_'+k]).map(k=>({n:k==='vous'?'Vous faire élire grand roi (conte)':ROIS[k].n+(ROIS[k].v?' (archives)':' (tradition)'),d:ROIS[k].d,f:()=>{S.roi=k;S.dir=ROIS[k].v?'vrai':'fictif';log('Les chefs élisent '+ROIS[k].n+' grand roi de l’intérieur.')}}))}},
 mortRoi:{sys:1,tag:'Archive',an:'',get t(){return 'La mort de '+(roi()||{n:'roi'}).n},get b(){return S.roi==='mafate'?'Le chef de détachement Mussard surprend Mafate dans son cirque. Le vieux guérisseur ne revient pas.':'Les détachements prennent les camps de l’îlette. Laverdure, roi de tous les marrons, tombe avec eux.'},v:'Le roi mort est porté dans un tombeau de pierre sèche. Les chefs devront élire un nouveau roi.',get h(){return (roi()||{}).h||''},o:[{n:'L’ensevelir selon les rites',d:'Anciens +5, mystique +2',fx:{anciens:5,myst:2},f:()=>{S.roi=null}}]},
 e1729p:{y:1729,tag:'Archive',an:'1729',t:'Une prime sur chaque marron',b:'La colonie promet 30 livres pour chaque marron tué ou pris. Des colons pauvres se font chasseurs pour l’argent.',v:'La traque devient un métier.',h:'Prime de 30 livres par esclave tué ou pris en 1729. Milice créée dès le 14 septembre 1697 par le commandant Bastide.',o:[{n:'Se faire plus discrets',d:'Traque -4, cohésion -2',fx:{traque:-4,coh:-2}}]},
 e1743d:{y:1743,tag:'Archive',an:'1743',t:'Le capitaine Dimitile',b:'On parle d’un capitaine marron à la tête de vingt-quatre hommes. Son influence s’étend des hauts de Saint-Paul à ceux de Saint-Pierre.',v:'Les bandes du Sud et de l’Ouest se connaissent.',o:[{n:'Envoyer un messager',d:'Gardiens +4',fx:{gardiens:4},vo:{m:3}}]},
 allMaur:{y:1722,si:()=>(S.out&&S.out.maurice)||S.maur,tag:'Mythe',an:'vers 1722',hist:1,nat:'Le marronnage de l’île de France (Maurice) est historique, au Morne notamment. L’alliance entre les marrons des deux îles est une fiction du jeu.',t:'Les marrons de l’île sœur',b:'Des passeurs reviennent de l’île de France. Là-bas aussi, des fuyards tiennent la montagne, jusqu’au Morne. Le soir, ils jouent de la ravanne et chantent en se répondant : le séga. Ils proposent une alliance entre les deux îles.',v:'Le séga tipik de Maurice, inscrit à l’UNESCO en 2014, est né chez les esclaves et leurs descendants, comme le maloya de La Réunion, inscrit en 2009.',o:[{n:'Sceller l’alliance des deux îles',d:'Ouvre le savoir Séga tipik. Cohésion +5, mystique +2, traque +3. Ouvre une uchronie.',fx:{coh:5,myst:2,traque:3},vo:{m:3},f:()=>{(S.br=S.br||{}).maur=1;log('Uchronie : les marrons des deux îles sœurs sont alliés.')}},{n:'Garder ses distances',d:'Comme dans l’histoire réelle.',fx:{}}]},
 anglB:{y:1748,si:()=>(S.out&&Object.keys(S.out).some(k=>S.out[k]))||S.pir,tag:'Mythe',an:'1748',hist:1,nat:'L’attaque anglaise de l’amiral Boscawen contre l’île de France en 1748 est historique. L’offre faite aux marrons est une fiction du jeu.',t:'L’offre des Anglais',b:'Une flotte anglaise rôde autour des Mascareignes. Un officier fait passer un message aux camps : des fusils et la liberté sous pavillon anglais, si les marrons aident à chasser les Français.',v:'Les Anglais prendront vraiment l’île en 1810 et la rendront à la France en 1815.',o:[{n:'Accepter la protection anglaise',d:'+2 fusils, traque +6, les Français vous haïssent. Ouvre une uchronie.',fx:{traque:6},vo:{m:2},f:()=>{(S.br=S.br||{}).angl=1;S.fu=(S.fu||0)+2;S.nav=S.nav||{};S.nav.anglais=(S.nav.anglais||0)+20;log('Uchronie : les camps passent alliance avec l’Angleterre.')}},{n:'Refuser',d:'Comme dans l’histoire réelle.',fx:{}}]},
 nomIle:{y:1751,tag:'Archive',an:'1751',hist:0,t:'Quel nom pour l’île ?',b:'Les anciens se réunissent : le nom que porte une île dit à qui elle appartient. Les colons disent Bourbon. Vous pouvez en choisir un autre.',v:'L’île a souvent changé de nom : Bourbon (1649), La Réunion (1793), Bonaparte (1806), Bourbon sous les Anglais (1810-1815), puis La Réunion (1848).',get o(){const L=[{n:'Bourbon',d:'Le nom des colons, comme dans l’histoire réelle.',f:()=>{S.nom='Bourbon'}},{n:'Dina Morgabin',d:'Le nom arabe d’al-Idrisi, « l’île de l’Ouest ». Mystique +2.',fx:{myst:2},f:()=>{S.nom='Dina Morgabin'}},{n:'Mafate',d:'Le nom d’un chef marron devient celui de l’île. Cohésion +3.',fx:{coh:3},vo:{m:2},f:()=>{S.nom='Mafate'}}];if(S&&S.br&&S.br.maur)L.push({n:'Les Îles Sœurs',d:'Un seul nom pour les deux îles marronnes.',fx:{coh:2},f:()=>{S.nom='les Îles Sœurs'}});if(S&&S.br&&S.br.angl)L.push({n:'Bourbon Island',d:'Le nom anglais.',fx:{ami:-5},f:()=>{S.nom='Bourbon Island'}});return L}},
 e1732:{y:1732,tag:'Archive',an:'1730-1732',t:'Le chemin Dumas',b:'La Compagnie trace un chemin pour les charrettes à bœufs entre Saint-Denis et La Possession, par la Montagne. Les colons et leurs détachements passeront plus vite d’un quartier à l’autre.',v:'Pavé de basalte de 1767 à 1775 sous Honoré de Crémont, il deviendra le « chemin des Anglais » : en juillet 1810, plus de 3 000 soldats anglais l’empruntent après avoir débarqué à la Grande Chaloupe.',o:[{n:'Surveiller le chemin',d:'Traque +3, mais vos guetteurs savent où passent les colons. Gardiens +2.',fx:{traque:3,gardiens:2}}]},
 e1810r:{y:1810,tag:'Archive',an:'juillet 1810',t:'La bataille de La Redoute',b:'Les Anglais débarqués à la Grande Chaloupe montent par le chemin pavé et gagnent la bataille décisive du plateau de La Redoute, au-dessus de Saint-Denis. L’île devient anglaise.',v:'Dès la fin de 1810, les Britanniques élèvent un mausolée de style antique pour l’officier John Graham Munro et leurs soldats tombés. Il fait face au monument français construit plus tard. C’est l’un des rares vrais vestiges anglais de l’île, qui revient à la France en 1815.',o:[{n:'Profiter du désordre',d:'La colonie a d’autres soucis : traque −6.',fx:{traque:-6}}]},
 puitsA:{y:1810,tag:'Conte',an:'',t:'Le puits des Anglais',b:'Au Baril, à Saint-Philippe, un puits est creusé dans le basalte du rivage pour trouver de l’eau douce tout près de la mer.',v:'La tradition dit qu’il a été creusé par des marins anglais qui cherchaient de l’eau sur la côte du Sud sauvage, d’où son nom.',o:[{n:'Garder le secret du puits',d:'Une source sûre sur la côte sauvage. Santé +3.',fx:{sante:3}}]},
e1767:{y:1767,tag:'Archive',an:'1767',t:'Pierre Poivre et les épices',b:'L’intendant Pierre Poivre fait passer girofle, muscade et plantes rares par les Mascareignes. À Saint-Denis naît le Jardin du Roi.',v:'Le Jardin du Roi deviendra le Jardin de l’État. Le girofle fera la fortune de quelques planteurs de l’Est.',hist:1,o:[{n:'Voler des plants pour vos jardins',d:'Jardin +4, traque +3.',fx:{jardin:4,traque:3}},{n:'Rester loin de Saint-Denis',d:'Comme les marrons d’alors, épuisés.',fx:{}}]},
 e1793:{y:1793,tag:'Archive',an:'19 mars 1793',t:'Bourbon devient La Réunion',b:'La Révolution efface le nom du roi : l’île s’appellera La Réunion. Mais en 1794, quand Paris abolit l’esclavage, les colons de l’île refusent d’appliquer la loi.',v:'L’abolition de 1794 ne sera jamais appliquée dans les Mascareignes, et Napoléon rétablit l’esclavage en 1802.',get o(){return [{n:'Espérer la liberté venue de Paris',d:'Cohésion +4. La colonie la refusera.',fx:{coh:4},vo:{e:-2}},{n:'Ne compter que sur soi',d:'Gardiens +4.',fx:{gardiens:4}}]}},
 e1806:{y:1806,tag:'Archive',an:'1806',t:'L’île Bonaparte',b:'L’île change encore de nom : île Bonaparte. Les cyclones de 1806 et 1807 ravagent les cultures, la famine suit.',v:'Ces noms disent qui gouverne l’île, pas qui y vit.',o:[{n:'Partager les vivres',d:'Vivres −6, cohésion +5.',fx:{vivres:-6,coh:5}}]},
 e1811:{y:1811,tag:'Archive',an:'novembre 1811',t:'La révolte de Saint-Leu',b:'Sous l’occupation anglaise, des esclaves de Saint-Leu se soulèvent, menés notamment par Élie. La révolte est écrasée, les meneurs exécutés.',v:'C’est la plus grande révolte d’esclaves de l’histoire de l’île.',hist:1,o:[{n:'Cacher les survivants dans les Hauts',d:'+3 personnes, traque +8.',fx:{gens:3,traque:8},vo:{m:3}},{n:'Pleurer les morts',d:'Anciens +3.',fx:{anciens:3}}]},
 e1815:{y:1815,tag:'Archive',an:'1815',t:'Les Anglais rendent l’île',b:'Le traité de Paris rend Bourbon à la France. Maurice, Rodrigues et les Seychelles restent anglaises. Le sucre commence son règne.',v:'Les sucreries à vapeur couvrent bientôt les pentes, et la traite illégale continue.',get o(){const L=[{n:'Voir partir les Anglais',d:'Comme dans l’histoire réelle.',fx:{}}];if(S&&S.br&&S.br.angl)L.push({n:'Garder l’île anglaise',d:'Uchronie : l’île ne revient pas à la France.',fx:{traque:-8},f:()=>{S.br.anglR=1;log('Uchronie : l’île reste anglaise.')}});return L}},
 e1848:{y:1848,tag:'Archive',an:'20 décembre 1848',t:'L’abolition',b:'Le commissaire Sarda Garriga proclame l’abolition de l’esclavage. Environ 62 000 personnes deviennent libres. La chasse aux marrons s’arrête.',v:'Le 20 décembre est aujourd’hui un jour férié à La Réunion : le Fèt Kaf.',o:[{n:'Descendre des Hauts, libres',d:'Cohésion +10, mystique +4. Les détachements cessent.',fx:{coh:10,myst:4,traque:-40},f:()=>{voie();S.vo.c+=S.vo.e*.8;S.vo.e*=.2;S.det=[]}}]},
 e1849:{y:1852,tag:'Archive',an:'après 1848',t:'Les engagés',b:'Pour remplacer les esclaves libérés, les planteurs font venir des engagés : Indiens du Sud surtout, mais aussi Africains, Malgaches et Chinois. Les contrats sont durs.',v:'L’engagisme a façonné la société réunionnaise : temples tamouls, fêtes, langues et cuisines.',o:[{n:'Accueillir les engagés en fuite',d:'+3 personnes, mystique +2.',fx:{gens:3,myst:2}},{n:'Rester entre soi',d:'Cohésion +2.',fx:{coh:2}}]},
 e1870:{y:1870,tag:'Archive',an:'années 1860-1870',t:'La crise sucrière',b:'Maladies de la canne, concurrence du sucre de betterave, ouverture du canal de Suez qui éloigne les routes : beaucoup de sucreries ferment.',v:'Des familles ruinées montent vivre dans les Hauts : les « petits Blancs des Hauts ».',o:[{n:'Faire place aux nouveaux venus des Hauts',d:'+2 personnes, vivres −4.',fx:{gens:2,vivres:-4}}]},
 e1882:{y:1882,tag:'Archive',an:'1882',t:'Le chemin de fer',b:'Le train relie Saint-Benoît à Saint-Pierre par la côte. Le tunnel de la Montagne passe sous la falaise.',v:'Le train roulera jusqu’en 1963, remplacé par la route.',o:[{n:'Vendre vos récoltes en ville',d:'Vivres +6.',fx:{vivres:6},vo:{c:2}}]},
 e1886:{y:1886,tag:'Archive',an:'1886',t:'Le port de la Pointe des Galets',b:'Après des siècles de rades dangereuses, l’île a enfin un vrai port, creusé dans les galets. La ville du Port naît autour.',v:'C’est encore le port principal de l’île.',o:[{n:'Voir partir les bateaux',d:'Outre-mer plus facile.',fx:{ami:5}}]},
 e1946:{y:1946,tag:'Archive',an:'19 mars 1946',t:'L’île devient un département',b:'La loi de départementalisation, portée par Raymond Vergès et Léon de Lépervanche, fait de La Réunion un département français.',v:'Routes, écoles, hôpitaux arrivent, mais aussi de fortes inégalités et des politiques contestées.',o:[{n:'Envoyer les enfants à l’école',d:'Savoir +3.',fx:{savoir:3},vo:{c:4}}]},
 e1963:{y:1963,tag:'Archive',an:'1962-1984',t:'Les enfants de la Creuse',b:'Plus de 2 000 enfants réunionnais sont envoyés dans des départements ruraux de métropole, souvent loin de leur famille et sans retour.',v:'L’Assemblée nationale a reconnu en 2014 la responsabilité morale de l’État.',o:[{n:'Garder la mémoire',d:'Anciens +5, cohésion +3.',fx:{anciens:5,coh:3}}]},
 e1981:{y:1982,tag:'Archive',an:'années 1970-1980',t:'Le maloya sort du silence',b:'Longtemps mal vu, joué en cachette, le maloya revient sur les scènes et les radios libres, avec Firmin Viry, Danyèl Waro et bien d’autres.',v:'Le maloya est inscrit au patrimoine culturel immatériel de l’UNESCO en 2009.',o:[{n:'Faire résonner le kayamb',d:'Mystique +4, cohésion +4.',fx:{myst:4,coh:4}}]},
 e2010:{y:2010,tag:'Archive',an:'2010',t:'Pitons, cirques et remparts',b:'Les cœurs sauvages de l’île, ceux où les marrons avaient trouvé refuge, sont inscrits au patrimoine mondial de l’UNESCO.',v:'Mafate, Cilaos, Salazie et le Piton de la Fournaise sont protégés.',o:[{n:'Les Hauts gardent vos noms',d:'Mystique +5.',fx:{myst:5}}]},
 e2026:{sys:1,y:2026,tag:'Archive',an:'2026',t:'Aujourd’hui',b:'Plus de 870 000 habitants vivent sur l’île. Les noms des marrons sont restés sur les sommets : Dimitile, Cimendef, Mafate, Anchaing.',v:'Votre histoire s’arrête ici, face à l’histoire réelle.',o:[{n:'Voir ce qu’est devenue votre île',d:'Fin de la partie',f:()=>fin('2026')}]},
e1804h:{y:1804,tag:'Archive',an:'1ᵉʳ janvier 1804',t:'Haïti, la république des anciens esclaves',b:'À Saint-Domingue, la plus riche colonie française, les esclaves révoltés ont vaincu les armées de Napoléon. Ils fondent Haïti, premier État né d’une révolte d’esclaves.',v:'Dans les Mascareignes, les colons redoutent la contagion et durcissent la surveillance.',o:[{n:'Faire courir la nouvelle dans les camps',d:'Cohésion +5, mystique +2, traque +3. Ouvre une destination lointaine.',fx:{coh:5,myst:2,traque:3}}]},
 e1827o:{y:1827,tag:'Archive',an:'1827',t:'Des Osages à Paris',b:'Six Osages, une nation amérindienne de l’ancienne Louisiane française, traversent l’Atlantique et sont reçus à Paris par le roi Charles X. On les exhibe comme une curiosité.',v:'Leur voyage finit dans la misère. La venue d’Amérindiens dans l’océan Indien serait une fiction du jeu.',o:[{n:'Écouter le récit des marins',d:'Pistage +2. Ouvre une destination lointaine.',f:()=>{S.pist=(S.pist||0)+2}}]},
 e1830a:{y:1830,tag:'Archive',an:'1830',t:'La prise d’Alger',b:'La France débarque en Algérie. Commence une conquête longue et violente, qui fera de l’Afrique du Nord le cœur de son empire.',v:'L’empire colonial français s’étend désormais de l’Afrique à l’Asie et au Pacifique.',o:[{n:'Suivre les nouvelles de l’empire',d:'Ouvre une destination lointaine.',fx:{}}]},
 e1846c:{y:1846,tag:'Archive',an:'à partir des années 1840',t:'Les Chinois arrivent',b:'Des engagés chinois arrivent d’abord. Puis, après les guerres et la grande révolte des Taiping qui ravagent la Chine des Qing, des Cantonais et des Hakkas viennent librement et ouvrent des boutiques.',v:'La « boutik sinwa » fait encore partie de la vie des quartiers réunionnais.',o:[{n:'Commercer avec eux',d:'Vivres +4. Ouvre une destination lointaine.',fx:{vivres:4}}]},
 e1850p:{y:1850,tag:'Archive',an:'XIXᵉ siècle',t:'Les pirates des détroits',b:'Dans les détroits de Malacca et entre les îles de l’Insulinde, des flottes de pirates attaquent les navires de commerce. Anglais et Hollandais lancent des expéditions pour les réduire.',v:'La piraterie de l’océan Indien survit ici bien après la fin des pirates de Madagascar.',o:[{n:'Garder le contact avec les marins de l’est',d:'Mystique +1.',fx:{myst:1}}]},
 e1835m:{y:1835,tag:'Archive',an:'1835',t:'L’empreinte anglaise à Maurice',b:'À Maurice, devenue anglaise, l’esclavage est aboli dès 1835. Les planteurs font venir des centaines de milliers d’engagés indiens.',v:'L’Aapravasi Ghat de Port-Louis, où débarquaient les engagés, est inscrit à l’UNESCO.',o:[{n:'Regarder l’île sœur se transformer',d:'Savoir +1.',fx:{savoir:1}}]},
 e1897r:{y:1897,tag:'Archive',an:'1897',t:'La reine Ranavalona en exil',b:'Après la conquête de Madagascar, la France exile la reine Ranavalona III à La Réunion, puis en Algérie, où elle mourra.',v:'L’empire déplace les souverains vaincus d’une colonie à l’autre.',o:[{n:'Saluer la reine de la Grande Île',d:'Anciens +3.',fx:{anciens:3}}]},
 e1898n:{y:1898,tag:'Archive',an:'vers 1890-1900',t:'La conquête du Sahel',b:'Des colonnes françaises s’enfoncent jusqu’au Niger. Des royaumes résistent, et des milliers d’Africains deviendront tirailleurs.',v:'Des tirailleurs de toute l’Afrique combattront dans les guerres de la France.',o:[{n:'Suivre les routes du désert',d:'Ouvre une destination lointaine.',fx:{}}]},
 e1926k:{y:1926,tag:'Archive',an:'1926-1947',t:'Abd el-Krim, exilé à La Réunion',b:'Le chef de la guerre du Rif, vaincu par l’Espagne et la France, est exilé à La Réunion avec sa famille. Il y vit plus de vingt ans.',v:'En 1947, transféré vers la France, il s’échappe lors d’une escale en Égypte.',o:[{n:'Rencontrer l’exilé',d:'Savoir +2.',fx:{savoir:2}}]},
 e1980z:{y:1980,tag:'Archive',an:'18 avril 1980',t:'Le Zimbabwe libre',b:'L’ancienne Rhodésie devient le Zimbabwe. Bob Marley chante à Harare pour l’indépendance. Le reggae et le rastafarisme traversent l’océan.',v:'À Maurice naît le seggae de Kaya, à La Réunion le maloggae : maloya et reggae se rencontrent.',o:[{n:'Mêler kayamb et reggae',d:'Cohésion +4. Ouvre une destination lointaine.',fx:{coh:4}}]},
 ep_antilles1:{si:()=>S.out&&S.out.antilles,tag:'Mythe',an:'',nat:'Les liens entre Haïti et les marrons de La Réunion sont une fiction du jeu.',t:'Le chant de la révolte',b:'Un marin revenu des Antilles apprend aux camps un chant créole venu d’Haïti. On y reconnaît des mots, des rythmes, une même colère.',v:'Les créoles de l’océan Indien et des Antilles sont nés de situations comparables, sans se connaître.',o:[{n:'Apprendre le chant',d:'Cohésion +6, savoir +2.',fx:{coh:6,savoir:2}}]},
 ep_amerique1:{si:()=>S.out&&S.out.amerique,tag:'Mythe',an:'',nat:'Fiction du jeu : aucun Amérindien n’est attesté dans les Hauts de La Réunion.',t:'Le pisteur venu de l’autre océan',b:'Un pisteur amérindien, venu d’une nation alliée de l’ancienne Nouvelle-France, débarque d’un navire. Dans les Hauts, il lit les traces comme un livre.',v:'Les nations amérindiennes ont été déplacées et dépossédées tout au long du XIXᵉ siècle.',o:[{n:'Partager vos savoirs de la forêt',d:'Pistage +4.',f:()=>{S.pist=(S.pist||0)+4}}]},
 ep_chine1:{si:()=>S.out&&S.out.chine,tag:'Conte',an:'',t:'La première boutique',b:'Une famille venue de Canton ouvre une boutique au bord d’un chemin des Hauts : riz, sel, pétrole, crédit noté dans un cahier.',v:'Les boutiques chinoises ont longtemps été le seul commerce des écarts et des îlets.',o:[{n:'Ouvrir un compte',d:'Vivres +8, cohésion +2.',fx:{vivres:8,coh:2}}]},
 ep_alger1:{si:()=>S.out&&S.out.alger,tag:'Conte',an:'',t:'Les nouvelles d’Alger',b:'Des soldats réunionnais reviennent d’Afrique du Nord. Ils racontent les villes blanches, les montagnes de Kabylie et la dureté de la conquête.',v:'Des Réunionnais ont servi dans l’armée coloniale, d’autres ont dénoncé la colonisation.',o:[{n:'Écouter et retenir',d:'Savoir +2, anciens +2.',fx:{savoir:2,anciens:2}}]},
 ep_niger1:{si:()=>S.out&&S.out.niger,tag:'Conte',an:'',t:'Le sel du désert',b:'Un tirailleur raconte les caravanes de sel, les puits, et les royaumes qui ont tenu tête aux colonnes françaises.',v:'Le Sahel a connu des résistances longues, comme celle de Samory Touré.',o:[{n:'Garder ses récits',d:'Gardiens +3.',fx:{gardiens:3}}]},
 ep_zimb1:{si:()=>S.out&&S.out.zimb,tag:'Mythe',an:'',nat:'Fiction du jeu, inspirée du maloggae et du seggae bien réels.',t:'Kayamb et reggae',b:'Dans les îlets, des jeunes mêlent le maloya des anciens marrons au reggae venu d’Afrique australe et de Jamaïque.',v:'Le rastafarisme a marqué la jeunesse de Maurice et de La Réunion depuis les années 1980.',o:[{n:'Laisser la musique monter',d:'Cohésion +6, mystique +3.',fx:{coh:6,myst:3}}]},
e1895m:{y:1895,tag:'Archive',an:'1883-1896',t:'La conquête de Madagascar',b:'À La Réunion, des notables et des élus, comme le député François de Mahy, poussent la France à conquérir la Grande Île. En 1895, l’expédition prend Tananarive. Madagascar devient colonie l’année suivante.',v:'Des colons réunionnais s’installent ensuite à Madagascar, et de nombreux Réunionnais servent dans l’administration coloniale.',hist:1,o:[{n:'Refuser de prêter vos bras à la conquête',d:'Cohésion +3, colonie fâchée.',fx:{coh:3,ami:-5},vo:{m:2}},{n:'Laisser faire',d:'Comme dans l’histoire réelle.',fx:{},vo:{c:2}}]},
 e1947m:{y:1947,tag:'Archive',an:'29 mars 1947',t:'L’insurrection malgache',b:'À Madagascar, une insurrection éclate contre le pouvoir colonial. La répression de l’armée française dure près de deux ans et fait des dizaines de milliers de morts.',v:'Le nombre exact des victimes reste débattu par les historiens. Des colons réunionnais vivaient dans les régions touchées, et certains ont pris part à la répression.',o:[{n:'Garder la mémoire des deux rives',d:'Anciens +4, cohésion +2.',fx:{anciens:4,coh:2}}]},
 e1960m:{y:1960,tag:'Archive',an:'26 juin 1960',t:'Madagascar indépendante',b:'La Grande Île retrouve son indépendance. Les liens familiaux, commerciaux et culturels avec La Réunion restent forts.',v:'Au même moment, la France installe des familles réunionnaises sur le plateau de la Sakay, à Madagascar.',o:[{n:'Garder le lien avec la Grande Île',d:'Mystique +2.',fx:{myst:2}}]},
 e1975c:{y:1975,tag:'Archive',an:'6 juillet 1975',t:'Les Comores indépendantes, Mayotte à part',b:'Les Comores proclament leur indépendance. Mais Mayotte, qui a voté autrement, reste française. L’archipel est coupé en deux.',v:'Les Comores n’ont jamais reconnu la séparation de Mayotte. Des coups d’État, souvent liés au mercenaire Bob Denard, secouent ensuite le pays.',o:[{n:'Penser aux familles séparées',d:'Cohésion +2.',fx:{coh:2}}]},
 e2011y:{y:2011,tag:'Archive',an:'31 mars 2011',t:'Mayotte, cent-unième département',b:'Mayotte devient un département français, le plus pauvre de France. Les traversées en kwassa-kwassa depuis Anjouan, souvent mortelles, continuent.',v:'La question de Mayotte divise encore la France et les Comores.',o:[{n:'Regarder l’archipel avec lucidité',d:'Savoir +1.',fx:{savoir:1}}]},
arabB:{y:1720,si:()=>S.out&&(S.out.comores||S.out.mada),tag:'Archive',an:'XVIIIᵉ siècle',hist:2,t:'Les boutres arabes',b:'Des boutres venus d’Oman, de Zanzibar et des Comores longent Madagascar. Ils vendent des étoffes, de l’argent et des armes, et achètent du riz, des bœufs… et des captifs.',v:'La traite arabo-swahilie est bien plus ancienne que la traite européenne dans l’océan Indien.',o:[{n:'Commercer avec eux',d:'Vivres +6, fusils +1. Des marchands arabes pourraient un jour s’installer chez vous.',fx:{vivres:6},f:()=>{(S.br=S.br||{}).arab='com';S.fu=(S.fu||0)+1;log('Uchronie : les camps commercent avec les boutres arabes.')}},{n:'Les attaquer en pirates',d:'Vivres +10, fusils +2, mais traque +6 et cohésion −3. Les marchands éviteront l’île.',fx:{vivres:10,traque:6,coh:-3},f:()=>{(S.br=S.br||{}).arab='pir';S.fu=(S.fu||0)+2;log('Uchronie : vos pirogues attaquent les boutres arabes.')}},{n:'Les laisser passer',d:'Comme dans l’histoire réelle.',fx:{}}]},
 e1841v:{y:1841,tag:'Archive',an:'1841',t:'Edmond Albius et la vanille',b:'À Sainte-Suzanne, un garçon esclave de douze ans, Edmond Albius, invente le geste qui féconde la fleur de vanille à la main. La vanille, venue du Mexique, peut enfin donner des gousses hors de son pays.',v:'Son geste fait la fortune de La Réunion, de Madagascar et des Comores. Lui mourra pauvre, en 1880.',o:[{n:'Retenir le geste',d:'Ouvre le savoir Fécondation de la vanille.',fx:{savoir:2}}]},
 e1870z:{y:1870,tag:'Archive',an:'à partir des années 1870',get t(){return S&&S.br&&S.br.arab==='pir'?'Les Zarabes arrivent malgré tout':'Les Zarabes'},get b(){return 'Des commerçants musulmans venus du Gujarat, en Inde, s’installent dans les villes : tissus, épices, boutiques. On les appelle les « Zarabes ».'+(S&&S.br&&S.br.arab==='com'?' Vos anciens liens avec les boutres leur ouvrent les Hauts.':S&&S.br&&S.br.arab==='pir'?' Mais le souvenir de vos pirogues les rend méfiants.':'')},v:'En 1905, ils élèvent à Saint-Denis la mosquée Noor-e-Islam, la première de France.',get o(){const a=S&&S.br&&S.br.arab;return [{n:'Commercer avec eux',d:a==='com'?'Vivres +10, cohésion +3.':a==='pir'?'Vivres +2.':'Vivres +5.',fx:a==='com'?{vivres:10,coh:3}:a==='pir'?{vivres:2}:{vivres:5}}]}},
 e1880c:{y:1880,si:()=>S.done.e1846c,tag:'Archive',an:'fin du XIXᵉ siècle',t:'Guan Di et la fête du Printemps',b:'Les familles chinoises se regroupent en associations, cantonaises d’un côté, hakkas de l’autre. Elles honorent Guan Di, dieu de la loyauté, fêtent le Nouvel An au son des pétards et soignent avec leurs propres plantes.',v:'Le Nouvel An chinois et la danse du lion font partie des fêtes de l’île.',o:[{n:'Fêter avec eux le Nouvel An',d:'Mystique +2, cohésion +2.',fx:{myst:2,coh:2}}]},
e1764l:{y:1764,tag:'Archive',an:'1764',t:'Le premier letchi',b:'Un administrateur de la Compagnie, Charpentier de Cossigny, fait venir de Chine les premiers pieds de letchi. Mangues, jacques, fruits à pain et bien d’autres arbres suivront, au gré des navires.',v:'La plupart des fruits et des légumes que l’on croit « péi » sont arrivés avec la colonisation : brèdes, chouchou, manioc, maïs, letchi, mangue…',o:[{n:'Planter les noyaux près des camps',d:'Ouvre le savoir Vergers créoles.',fx:{jardin:2}}]},
 e1860g:{y:1860,tag:'Archive',an:'XIXᵉ siècle',t:'Les plantes qui envahissent la forêt',b:'Le goyavier, venu d’Amérique, gagne les forêts des Hauts. Ses fruits tombent en abondance, et l’on va « aux goyaviers » chaque année. Mais avec lui arrivent le longose, la vigne marronne, le raisin marron : ils étouffent la forêt indigène.',v:'Ces plantes envahissantes sont aujourd’hui l’une des grandes menaces pour la forêt primaire de l’île.',o:[{n:'Cueillir les goyaviers',d:'Vivres +5. Les envahissantes avancent chaque saison, avec des fruits à la saison des pluies.',fx:{vivres:5}}]},
 e1890t:{y:1890,tag:'Archive',an:'fin du XIXᵉ siècle',t:'La tôle, le fer et les fumées',b:'La tôle ondulée remplace peu à peu la paille et le vacoa sur les cases. Le fer, la fonte et le cuivre des usines, le charbon du train et des machines changent l’air et les ravines.',v:'La case en tôle est devenue un symbole de l’île. La pollution, elle, grandit avec les usines, puis les voitures.',o:[{n:'Couvrir les cases de tôle',d:'Santé +3 contre la pluie, mais la pollution commence à compter.',fx:{sante:3}}]},
 e1865z:{y:1865,tag:'Archive',an:'XIXᵉ - XXᵉ siècles',t:'Le zamal',b:'Le chanvre, que l’on appelle ici zamal, arrive avec les navires des colons. Plus tard, les engagés indiens, qui le connaissent sous le nom de ganja, le répandent un peu. Il pousse caché en forêt, non loin des lieux de travail mais jamais à côté. On lui prête des vertus de rite, de remède, ou une force qui laisse épuisé ensuite. Des variétés locales portent des noms de couleur.',v:'Interdit, il est traqué dans les Hauts : des campagnes d’arrachage, dans les années 1990 et 2000, vont jusqu’au fond de Mafate. Sa culture reste illégale en France.',o:[{n:'Le réserver aux rites et aux remèdes',d:'Mystique +2, santé −1.',fx:{myst:2,sante:-1}},{n:'Le tenir loin des camps',d:'Cohésion +1, gardiens +1.',fx:{coh:1,gardiens:1}}]},
e1860za:{y:1862,tag:'Conte',an:'XIXᵉ siècle',hist:1,t:'Le zamal des jardins cachés',b:'Le chanvre, que l’île appelle zamal, est venu par les navires des colons ; les engagés indiens, qui le connaissaient sous le nom de ganja, l’ont ensuite un peu répandu. On le plante en lisière, dans des coins de forêt cachés, ni trop près ni trop loin des champs. Les anciens parlent de variétés rouges, blanches, orangées, et lui prêtent des vertus : soigner, donner de la force au travail… avant la fatigue.',v:'Le zamal a été cultivé et consommé à La Réunion bien avant d’être interdit. Il ne tue pas, mais en abuser rend las et sans force pour le travail. Il est illégal en France. Dans les cirques, il pousse haut, mais reste une plante annuelle : ce n’est pas un arbre.',o:[{n:'Le planter dans un coin caché',d:'Mystique +2, vivres +3 par l’échange. Il ne tue pas, mais trop en consommer rend las : certaines saisons, un bras de moins. Après 1970, les arrachages menacent.',fx:{myst:2,vivres:3},f:()=>{(S.br=S.br||{}).zamal=1}},{n:'Ne pas en planter',d:'Rien ne change.',fx:{}}]},
 e1990za:{y:1990,si:()=>S.br&&S.br.zamal,tag:'Archive',an:'années 1980-2000',t:'Les arrachages dans les cirques',b:'Gendarmes et hélicoptères mènent des opérations répétées contre les plantations de zamal, jusque dans les îlets de Mafate. Des familles perdent une ressource cachée depuis des générations.',v:'La lutte contre le cannabis reste une priorité des autorités. Son usage ne s’est vraiment répandu que tard, à la fin du XXᵉ siècle, avec le rastafarisme et l’influence de Bob Marley dans l’océan Indien — à Maurice, Kaya, le créateur du seggae, a pris son nom d’un album de Marley.',o:[{n:'Abandonner les plantations',d:'Mystique −2, cohésion −2.',fx:{myst:-2,coh:-2},f:()=>{S.br.zamal=0}}]},
e1740am:{y:1740,tag:'Archive',an:'XVIIIᵉ siècle',hist:0,t:'Les plantes venues d’Amérique',b:'Par les navires arrivent des plantes que les peuples amérindiens cultivaient depuis des millénaires : le maïs, le manioc, le piment, le tabac, et plus tard la vanille. Avec elles, le datura, aux grandes fleurs en trompette, que l’on dit magique.',v:'Le datura est un poison violent : il peut tuer, et ses usages rituels, en Amérique comme ailleurs, ont fait de nombreuses victimes. Le maïs et le manioc, eux, sont devenus des nourritures de base des Hauts.',o:[{n:'Cultiver maïs et manioc, laisser le datura',d:'Vivres +4, jardin +2.',fx:{vivres:4,jardin:2}},{n:'Garder le datura pour les rites',d:'Mystique +3. Ouvre une voie mystique des savoirs anciens d’Afrique, au prix du danger : le datura rend fou, puis tue à forte dose.',fx:{myst:3,sante:-3},f:()=>{(S.br=S.br||{}).datura=1;log('Les anciens gardent le datura pour les rites.')}}]},
koush:{si:()=>S.sv.anciens,tag:'Mythe',an:'',nat:'Les pharaons noirs de la XXVᵉ dynastie, venus du royaume de Koush (Soudan actuel), sont historiques. Leur lien avec le datura et avec les marrons de La Réunion est une fiction du jeu ; le datura lui-même est sans doute arrivé dans l’île par les navires des colons.',t:'La mémoire des pharaons noirs',b:'Dans la fumée des rites, une vieille femme raconte un royaume au bord du Nil, Koush, dont les rois noirs ont régné sur l’Égypte. Elle dit que des savoirs de ce temps ont voyagé de bouche en bouche jusqu’aux Hauts.',v:'Vers 750 avant notre ère, les rois de Koush, comme Piânkhy et Taharqa, ont gouverné toute l’Égypte.',o:[{n:'Écouter sans boire',d:'Mystique +3, Anciens +3.',fx:{myst:3,anciens:3}},{n:'Boire la tisane de datura',d:'Mystique +6, mais un initié perd la raison, et la santé chute.',fx:{myst:6,sante:-8,gens:-1}}]},
e1700p:{y:1700,tag:'Archive',an:'vers 1690-1720',hist:1,t:'Les pirates posent leurs coffres',b:'Des flibustiers de l’océan Indien, las de la course, obtiennent le pardon du roi et s’installent à Bourbon. Ils épousent des femmes de l’île, achètent des terres et des esclaves. Avant eux, les premiers venus étaient surtout des soldats et des aventuriers.',v:'Plusieurs familles anciennes de l’île descendent de ces pirates amnistiés.',o:[{n:'Leur vendre des vivres contre des armes',d:'Fusils +1, vivres −4.',fx:{vivres:-4},f:()=>{S.fu=(S.fu||0)+1}},{n:'Les éviter',d:'Ils deviennent colons comme les autres.',fx:{},vo:{c:1}}]},
 e1722c:{y:1722,tag:'Archive',an:'années 1720',t:'Les marchands de la Compagnie',b:'La Compagnie des Indes fait de Bourbon une île à café. Arrivent des commis, des marchands, des capitaines de navire, qui comptent en balles de café et en têtes d’esclaves.',v:'L’île vit au rythme des navires de la Compagnie et de ses magasins.',o:[{n:'Observer leurs routes de commerce',d:'Savoir +1.',fx:{savoir:1}}]},
 e1742b:{y:1742,tag:'Archive',an:'1735-1746',t:'Les bâtisseurs',b:'Avec La Bourdonnais arrivent ingénieurs, maçons, charpentiers et forgerons. Ils tracent des routes, élèvent des magasins, des batteries de canons, des moulins.',v:'Artisans et petits marchands forment peu à peu une classe moyenne blanche dans les quartiers.',o:[{n:'Voler des outils de fer',d:'Jardin +2, traque +3.',fx:{jardin:2,traque:3}}]},
 e1767r:{y:1768,tag:'Archive',an:'1767',t:'L’île du Roi',b:'La Compagnie en faillite rend l’île au roi. Officiers, administrateurs et familles de petite noblesse s’installent. Dans les Bas, de grandes familles de planteurs se forment autour des domaines, alliées entre elles par les mariages.',v:'Ces familles des Bas ont dominé la terre, la politique et le sucre pendant plus d’un siècle.',o:[{n:'Rester loin des Bas',d:'Gardiens +2.',fx:{gardiens:2}}]},
 e1820i:{y:1820,tag:'Archive',an:'XIXᵉ siècle',t:'Ingénieurs, industriels et petits Blancs',b:'Le sucre attire des ingénieurs, des mécaniciens, des industriels. Les grandes familles s’enrichissent, tandis que des descendants de colons pauvres, les petits Blancs, montent cultiver les Hauts.',v:'La société coloniale se partage entre les Bas du sucre et les Hauts des petits planteurs.',o:[{n:'Partager les Hauts avec les petits Blancs',d:'+2 personnes, cohésion −2.',fx:{gens:2,coh:-2}},{n:'Défendre vos îlets',d:'Gardiens +3.',fx:{gardiens:3}}]},
e1745ch:{y:1745,tag:'Mythe',an:'vers 1745',hist:0,nat:'L’usage de chiens dressés contre les marrons est attesté aux Antilles. Leur venue des Caraïbes jusqu’à Bourbon est une hypothèse du jeu.',t:'Les chiens des Caraïbes',b:'Des colons venus des Antilles racontent comment, là-bas, on dresse des chiens à suivre la trace des fuyards. Les détachements commencent à monter avec des meutes.',v:'Aux Antilles, puis à la Jamaïque en 1795, des chiens ont été achetés à Cuba pour traquer les marrons.',o:[{n:'Brouiller les pistes',d:'Traque +4. Avec le savoir Fausses pistes, les chiens se perdent : traque −4 à la place.',f:()=>{fx({traque:S.sv.leurres?-4:4})}},{n:'Apprivoiser des chiens à votre tour',d:'+1 chien, traque +2.',fx:{traque:2},f:()=>{S.chiens=(S.chiens||0)+1}}]},
 e1798s:{y:1798,tag:'Archive',an:'1793-1810',t:'Le temps des corsaires',b:'Pendant les guerres contre l’Angleterre, des corsaires partent des Mascareignes attaquer les navires anglais des Indes. Le plus célèbre, Robert Surcouf, opère depuis l’île de France. Officiers, aventuriers et parfois cadets de petite noblesse s’embarquent avec eux.',v:'Les prises des corsaires enrichissent quelques familles et remplissent les magasins de l’île. En 1810, les Anglais mettent fin à la course en prenant les deux îles.',o:[{n:'Racheter des armes saisies',d:'Fusils +2, vivres −5. Vos passeurs leur apprennent vos sentiers…',fx:{vivres:-5},f:()=>{S.fu=(S.fu||0)+2;(S.br=S.br||{}).cors=1}},{n:'Rester à l’écart',d:'Rien ne change.',fx:{}}]},
 e1830sa:{y:1830,tag:'Archive',an:'1810-1848',t:'On s’installe à Salazie',b:'Le cirque, refuge des marrons depuis le XVIIᵉ siècle, accueille ses premiers colons : un certain Louvet vers 1810, puis des planteurs de la côte au Vent après les cyclones de 1825 et 1829, et des petits Blancs sans terre. Les sources thermales font naître Hell-Bourg.',v:'Les Hauts de Salazie passent de 36 habitants en 1834 à 2 500 en 1848. Vers 1840, Sully Brunet y introduit le chouchou, venu du Mexique.',o:[{n:'Céder les îlets du bas',d:'+2 personnes venues de la côte, cohésion −2.',fx:{gens:2,coh:-2}},{n:'Monter plus haut',d:'Gardiens +2.',fx:{gardiens:2}}]},
e1690pa:{y:1690,tag:'Archive',an:'1689',t:'Augustin Panon, charpentier',b:'Augustin Panon, charpentier venu de Toulon, débarque à Bourbon. Il reçoit des terres, fonde une famille et s’enrichit. Une rivière de l’Est, puis toute une commune, portera son nom : Bras-Panon.',v:'Ses descendants, les Panon-Desbassayns, deviendront l’une des plus puissantes familles de planteurs et d’esclavagistes de l’île, de Saint-Paul à Saint-Denis.',o:[{n:'Retenir ce nom',d:'Anciens +1.',fx:{anciens:1}}]},
 e1809sp:{y:1809,tag:'Archive',an:'21 septembre 1809',t:'Les Anglais prennent Saint-Paul',b:'Une escadre anglaise débarque à Saint-Paul, détruit les batteries et s’empare des navires dans la rade. Quelques jours plus tard, elle se retire : c’est un coup de main, avant la conquête de 1810.',v:'Ce n’est pas une libération des esclaves : sous les Anglais, l’esclavage continue jusqu’en 1848 à Bourbon.',o:[{n:'Profiter du désordre sur la côte',d:'Traque −4, fusils +1.',fx:{traque:-4},f:()=>{S.fu=(S.fu||0)+1}}]},
 e1817ch:{y:1817,tag:'Archive',an:'vers 1817',t:'La vapeur au Chaudron',b:'Près de Saint-Denis, au Chaudron, Charles Desbassayns fait tourner l’une des premières machines à vapeur de l’île pour broyer la canne. Les domaines de la famille, de Saint-Paul à Saint-Denis, s’agrandissent avec le sucre et le travail des esclaves.',v:'La famille Desbassayns a marqué l’histoire de l’esclavage à La Réunion. Le domaine de Villèle est aujourd’hui un musée qui en garde la mémoire.',o:[{n:'Voir la fumée monter',d:'Traque +2.',fx:{traque:2}}]},
avn1:{si:()=>S.done.kumari||S.sv.anciens||S.leg||S.mythSout,tag:'Mythe',an:'',nat:'Mythe de pure fiction, créé pour le jeu.',t:'Avant le Nil',b:'Les anciens disent qu’avant les pharaons, avant même l’Égypte, un peuple vivait sur un continent aujourd’hui englouti, qui allait des Mascareignes à l’Australie et aux terres noyées près de la Nouvelle-Zélande. Le monde n’avait pas sa forme d’aujourd’hui : l’Amérique du Nord touchait la Sibérie, le Groenland était plus au nord, l’Arabie flottait loin de l’Asie. La carte de ce monde est dans la Chronologie. Ses sages bâtissaient des pyramides de pierre noire, alignées d’un bout à l’autre du monde.',v:'Ce récit rejoint, dans le jeu, Kumari Kandam et les pyramides de l’île sœur.',o:[{n:'Chercher les pierres alignées',d:'Mystique +2. La suite du mythe se révèle peu à peu.',fx:{myst:2}}]},
 avn2:{si:()=>S.done.avn1&&(S.myst||0)>=8,tag:'Mythe',an:'',nat:'Mythe de pure fiction, créé pour le jeu.',t:'Les pyramides qui se répondent',b:'De Maurice au Nil, des Andes aux îles d’Asie, les pyramides auraient formé un seul réseau. Aux équinoxes, disent les conteurs, la lumière passait de l’une à l’autre comme un feu de signal, et les sommets des îles servaient de relais.',v:'Les pyramides d’Égypte, d’Amérique et d’ailleurs ont été bâties à des époques et par des peuples sans lien entre eux.',o:[{n:'Allumer un feu sur le Piton des Neiges à l’équinoxe',d:'Mystique +3, traque +3.',fx:{myst:3,traque:3}}]},
 avn3:{si:()=>S.done.avn2,tag:'Mythe',an:'',nat:'Mythe de pure fiction, créé pour le jeu.',t:'Les tribus aux visages d’animaux',b:'Les dieux anciens de l’Égypte n’auraient d’abord été que des tribus de ce peuple englouti : la tribu du chacal, celle du faucon, celle de l’ibis, celle du chat, chacune portant le masque et l’esprit de son animal. Quand la mer a tout recouvert, les survivants sont devenus des dieux dans la mémoire des hommes. Et l’ibis des Hauts, dit-on, est le dernier messager de la tribu de l’ibis.',v:'Dans l’Égypte réelle, Thot, dieu du savoir, a une tête d’ibis, et Anubis une tête de chacal.',o:[{n:'Recevoir le regard de l’ibis',d:'Ouvre le pouvoir « Le regard de l’ibis ». Mystique +3.',fx:{myst:3},f:()=>{S.ibis=1;log('Le mythe d’avant le Nil est complet : le regard de l’ibis vous est donné.')}},{n:'Garder le mythe pour les veillées',d:'Cohésion +4.',fx:{coh:4}}]},
avn4:{si:()=>S.done.avn3&&(S.done.e1846c||(S.out&&S.out.chine)),tag:'Mythe',an:'',nat:'Mythe de pure fiction, créé pour le jeu. Il ne vient pas des mythologies chinoises, qui parlent plutôt de Pangu et de Nüwa.',t:'Le peuple d’en dessous',b:'Un vieux boutiquier de Canton écoute le mythe d’avant le Nil et sourit : dans son village, dit-il, on racontait que les ancêtres vivaient sous la terre d’un continent du grand nord, dans des cités creusées sous la glace. Un jour la glace s’est fendue, et ils sont sortis à la lumière pour descendre vers les grands fleuves.',v:'Dans les vraies mythologies de Chine, Pangu sépare le ciel et la terre, et Nüwa façonne les humains avec de l’argile.',o:[{n:'Échanger vos mythes',d:'Mystique +3, cohésion +2.',fx:{myst:3,coh:2}}]},
avn5:{si:()=>S.done.avn2,tag:'Mythe',an:'',nat:'Mythe de pure fiction, créé pour le jeu, inspiré du récit de l’Atlantide de Platon.',t:'L’Atlantide verte',b:'Un ancien du réseau pirate raconte : jadis, une terre immense s’étendait de l’Amérique centrale jusqu’à l’Afrique de l’Ouest. Une civilisation y gardait les savoirs d’avant le Nil. Le Sahara était vert, plein de lacs et de troupeaux. Quand les grandes pyramides furent levées, le ciel changea : l’Atlantide sombra, et le désert avala la savane.',v:'Le « Sahara vert » est réel : il y a 11 000 à 5 000 ans, lacs et savanes couvraient le désert actuel.',o:[{n:'Chercher les savoirs de l’Atlantide',d:'Savoir +3, mystique +2.',fx:{savoir:3,myst:2}}]},
e1794a:{y:1794,tag:'Archive',an:'4 février 1794',t:'Paris abolit l’esclavage',b:'La Convention abolit l’esclavage dans toutes les colonies. Le décret est appliqué en Guadeloupe et à Saint-Domingue, où les esclaves révoltés l’ont arraché. Mais à l’île de France et à Bourbon, les colons refusent de le publier.',v:'Dans l’histoire réelle, l’abolition de 1794 n’a jamais été appliquée dans les Mascareignes.',get o(){const L=[{n:S&&S.voieC?'Refuser avec l’Assemblée coloniale, comme dans l’histoire réelle':'Attendre, comme dans l’histoire réelle',d:'Rien ne change.',fx:{}}];const B=()=>{S.br=S.br||{};const i=S.evq.indexOf('e1796b');if(i>=0&&!S.done.e1795d&&!S.evq.includes('e1795d'))S.evq.splice(i,0,'e1795d');return S.br};if(S&&!S.voieC)L.push({n:'Porter la nouvelle dans les habitations',d:'Uchronie : vos gens descendent la nuit annoncer le décret aux esclaves. Personnes +2, traque +12. Il faudra encore de la force en 1795.',fx:{gens:2,traque:12},f:()=>{B().abolT=(B().abolT||0)+1;log('Vous portez la nouvelle de l’abolition dans les habitations.')}});if(S&&S.voieC)L.push({n:'Publier le décret dans vos quartiers',d:'Uchronie : vous faites lire le décret. Colonie −12, cohésion −4. Il faudra encore des appuis en 1795.',fx:{ami:-12,coh:-4},f:()=>{B().abolT=(B().abolT||0)+1;log('Vous faites publier le décret d’abolition dans vos quartiers.')}});if(S&&S.voieC&&S.gouv)L.push({n:'Imposer le décret en gouverneur',d:'Uchronie : vous forcez l’Assemblée. Colonie −20, cohésion −6, mais l’abolition a de vraies chances.',fx:{ami:-20,coh:-6},f:()=>{B().abolT=(B().abolT||0)+2;log('Gouverneur, vous imposez le décret d’abolition.')}});if(S&&(S.pir||S.lib)&&S.out&&(S.out.antilles||S.out.mada||S.out.comores))L.push({n:'Faire appliquer le décret avec vos alliés',d:'Uchronie : vos alliés pirates et le lien avec les révoltés des Caraïbes portent le décret jusqu’aux Hauts. Traque +10, la suite se joue en 1796.',fx:{traque:10},f:()=>{(S.br=S.br||{}).abolT=(S.br.abolT||0)+2;log('Uchronie : vous tentez d’imposer l’abolition de 1794.')}});return L}},
 e1796b:{y:1796,si:()=>!(S&&S.br&&S.br.abolT)||S.done.e1795d,tag:'Archive',an:'juin 1796',get t(){return S&&S.br&&S.br.abolT>=2?'Les agents de Paris ne repartent pas':'Les agents de Paris chassés'},get b(){return S&&S.br&&S.br.abolT>=2?'Deux agents du Directoire, Baco et Burnel, arrivent pour appliquer l’abolition. Les colons veulent les rembarquer de force, mais cette fois vos camps, les pirates et des esclaves soulevés descendent sur la côte. Les agents restent. L’abolition est proclamée à Bourbon.':'Deux agents du Directoire, Baco et Burnel, arrivent à l’île de France pour appliquer l’abolition. Les colons les rembarquent de force quelques jours plus tard. L’esclavage continue.'},v:'Dans l’histoire réelle, Baco et Burnel ont bien été expulsés en juin 1796, et l’esclavage a duré jusqu’en 1848 à La Réunion.',get o(){if(S&&S.br&&S.br.abolT===1)return [{n:'Les agents sont rembarqués malgré vous',d:'Trop peu d’appuis : la colonie se venge. '+(S.voieC?'Colonie −8.':'Traque +10.'),fx:S.voieC?{ami:-8}:{traque:10}}];return S&&S.br&&S.br.abolT>=2?[{n:'Proclamer la liberté',d:'Uchronie : fin de l’esclavage en 1796. Les chasses aux marrons cessent. Cohésion +10, mystique +5.',fx:{coh:10,myst:5,traque:-30},f:()=>{S.br.abol=1;voie();S.vo.m+=S.vo.e*.5;S.vo.c+=S.vo.e*.3;S.vo.e*=.2;S.det=[];log('Uchronie : l’esclavage est aboli à Bourbon en 1796.')}}]:[S&&S.voieC?{n:'Laisser l’Assemblée les rembarquer',d:'Comme dans l’histoire réelle.',fx:{}}:{n:'Continuer à se cacher',d:'Comme dans l’histoire réelle.',fx:{}}]}},
 e1802r:{y:1802,tag:'Archive',an:'20 mai 1802',get t(){return 'Napoléon rétablit l’esclavage'},get b(){const a=S&&S.br&&S.br.abol,c=S&&S.br&&S.br.cors;return 'Le Premier consul rétablit l’esclavage là où il n’a pas été aboli, et envoie des armées le rétablir ailleurs.'+(a?' Une escadre fait route vers Bourbon pour revenir sur votre abolition.':'')+(c?' Pire : les corsaires que vous avez armés connaissent vos sentiers. Leurs savoirs servent maintenant les expéditions de Napoléon.':'')},v:'En Guadeloupe, la résistance de Delgrès et d’Ignace est écrasée en 1802. À Saint-Domingue, l’armée de Leclerc échoue : Haïti naît en 1804.',get o(){const a=S&&S.br&&S.br.abol,c=S&&S.br&&S.br.cors;return a?[{n:'Tenir les Hauts',d:'L’abolition tient. Traque +'+(c?30:18)+', santé −8.',fx:{traque:c?30:18,sante:-8}},{n:'Céder',d:'L’esclavage revient, comme dans l’histoire réelle. Cohésion −10.',fx:{coh:-10},f:()=>{S.br.abol=0;voie();S.vo.e+=8}}]:[S&&S.voieC?{n:'Appliquer la loi de 1802',d:'Rien ne change à Bourbon, où l’esclavage n’avait jamais cessé.',fx:{}}:{n:'Se cacher plus haut',d:c?'Les corsaires guident les détachements : traque +8.':'Rien ne change ici.',fx:c?{traque:8}:{}}]}},
e1940v:{y:1940,tag:'Archive',an:'1940-1942',hist:0,t:'L’île sous Vichy',b:'Après la défaite de 1940, le gouverneur Pierre Aubert range l’île derrière le régime de Vichy, comme Madagascar. La flotte anglaise impose un blocus : plus de riz, plus de médicaments. La faim revient, et les opposants sont surveillés, arrêtés, internés.',v:'Le blocus a provoqué de graves pénuries. On a vécu de manioc, de songe et de ce que donnaient les Hauts.',get o(){const L=[{n:'Cacher les opposants dans les îlets',d:'+2 personnes, cohésion +3, traque +6.',fx:{gens:2,coh:3,traque:6}},{n:'Nourrir la côte avec les cultures des Hauts',d:'Vivres −8, cohésion +5, la colonie vous doit beaucoup.',fx:{vivres:-8,coh:5,ami:6}}];if(S&&typeof stadeFac==='function'&&stadeFac()===2)L.push({n:'Former un bloc vichyste avec Madagascar',d:'Uchronie : la milice des Hauts traque les réfractaires et les gens des îlets. Les insoumis reculent, cohésion −6, mystique −3.',fx:{coh:-6,myst:-3},f:()=>{(S.br=S.br||{}).vichy=1;S.ins=Math.max(0,(S.ins||40)-30);log('Uchronie : un bloc vichyste Réunion-Madagascar traque les réfractaires.')}});return L}},
 e1942l:{y:1942,tag:'Archive',an:'28 novembre 1942',get t(){return S&&S.br&&S.br.vichy?'Le Léopard face au bloc de Vichy':'Le Léopard libère l’île'},get b(){return 'Le contre-torpilleur Léopard, des Forces françaises libres, arrive devant Saint-Denis. Après de brefs combats, l’île se rallie à la France libre. Quelques mois plus tôt, les Anglais ont pris Madagascar à Vichy.'+(S&&S.br&&S.br.vichy?' Dans votre histoire, la milice des Hauts résiste quelques jours avant de céder.':'')},v:'Le ralliement de 1942 ouvre la voie à la départementalisation de 1946.',o:[{n:'Saluer le ralliement',d:'Cohésion +4.',fx:{coh:4},f:()=>{if(S.br&&S.br.vichy){S.br.vichy=0;fx({ami:-6})}}}]},
debutC:{sys:1,tag:'Archive',an:'novembre 1663',t:'Louis Payen à Saint-Paul',b:'Louis Payen, un colon français, et son compagnon Pierre Pau débarquent à Saint-Paul avec dix Malgaches, dont trois femmes, pour cultiver la terre au service de la Compagnie. Très vite, les Malgaches s’enfuient dans les Hauts. Vous voici colons, et ces fuyards sont vos premiers marrons.',v:'C’est bien ce qui s’est passé : les premiers habitants de l’île ont fui dans la montagne quelques mois après leur arrivée.',o:[{n:'Bâtir la colonie',d:'Vous suivez l’histoire coloniale. Les marrons insoumis tiennent les Hauts.',fx:{}},{n:'Partir les rejoindre',d:'Vous changez de camp dès le début : l’histoire du marronnage.',fx:{coh:5},f:()=>{S.voieC=0;S.vo={m:90,c:10,e:0};log('Vous rejoignez les fuyards dans les Hauts.')}}]},
e1880ex:{y:1885,tag:'Archive',an:'fin du XIXᵉ siècle',t:'Les chapelles rouges de saint Expédit',b:'Au bord des routes, des niches peintes en rouge abritent saint Expédit, le saint des causes urgentes, et des statues de la Vierge. On y dépose des bougies, des fleurs, parfois des vœux de vengeance.',v:'Le culte de saint Expédit est devenu l’un des plus populaires de l’île, mêlé aux croyances venues d’Inde, de Madagascar et d’Afrique.',o:[{n:'Allumer une bougie',d:'Mystique +2, colonie +2.',fx:{myst:2,ami:2}}]},
 e1860km:{y:1860,si:()=>S.done.e1849,tag:'Archive',an:'après 1848',t:'Kali, Madurai Veeran et la marche sur le feu',b:'Les engagés tamouls élèvent de petits temples aux divinités de leurs villages : Kali, Madurai Veeran le gardien, Mariamman. Au temps des fêtes, des fidèles marchent sur un lit de braises.',v:'La marche sur le feu est toujours pratiquée dans les temples de l’île.',o:[{n:'Assister à la marche sur le feu',d:'Mystique +3.',fx:{myst:3}}]},
 syncMV:{sys:1,tag:'Archive',an:'',t:'Saint Expédit et Madurai Veeran',b:'Votre chapelle est voisine d’un temple tamoul. Bientôt, les mêmes fidèles prient dans les deux : saint Expédit, le soldat romain, se confond avec Madurai Veeran, le guerrier gardien. Les offrandes passent de l’un à l’autre.',v:'Ce rapprochement existe réellement à La Réunion : bien des fidèles honorent les deux.',o:[{n:'Laisser les dévotions se mêler',d:'Mystique +1 par saison tant que chapelle et temple sont voisins.',fx:{myst:2}}]},
 syncML:{sys:1,tag:'Mythe',an:'',nat:'Fiction du jeu, inspirée des syncrétismes réels de l’île.',t:'La chapelle qui protège mal',b:'Votre chapelle est voisine d’un lieu sacré malgache ou africain. Les colons y prient saint Expédit… mais la nuit, d’autres mains y déposent d’autres offrandes. Sans que la colonie le sache, la chapelle protège moins ses détachements.',v:'Les dévotions des chapelles de bord de route mêlent souvent plusieurs traditions.',o:[{n:'Ne rien dire',d:'La traque baisse un peu chaque saison, en secret.',fx:{}}]},
 e1911si:{y:1911,tag:'Archive',an:'1909-1911',t:'Sitarane',b:'Dans le Sud, une bande menée par Sitarane, un homme venu du Mozambique, pille et tue en se protégeant, dit-on, par la sorcellerie. Arrêté, il est guillotiné à Saint-Pierre en 1911.',v:'Sa tombe, au cimetière de Saint-Pierre, reçoit encore des offrandes : rhum, cigarettes, bougies rouges, déposés par ceux qui demandent protection, parfois pour de mauvais coups.',o:[{n:'Craindre son ombre',d:'Gardiens +2.',fx:{gardiens:2}},{n:'Garder la légende des voleurs protégés',d:'Mystique +2. Dans le jeu, la vieille tradition des pirates et des marrons qui volaient sous la protection des esprits.',fx:{myst:2},f:()=>{(S.br=S.br||{}).sitarane=1}}]},
e1858in:{y:1858,si:()=>S.done.e1849,tag:'Archive',an:'1848-1882',t:'Qui sont les engagés indiens ?',b:'Ils viennent surtout du Sud de l’Inde, par Pondichéry et Karikal : des paysans et des journaliers, beaucoup de basses castes et d’intouchables, souvent placés comme domestiques ou dans les petits métiers. Quelques interprètes, commandeurs et marchands les accompagnent. Ils apportent la religion des villages tamouls, plus ancienne que l’hindouisme des brahmanes : déesses mères, gardiens, fêtes de feu.',v:'Peu sont arrivés riches : c’est en une ou deux générations que des familles tamoules sont devenues commerçantes ou propriétaires. Les temples de l’île gardent encore ces traditions dravidiennes.',o:[{n:'Partager les terres des Hauts avec eux',d:'+3 personnes, cohésion −1, mystique +2.',fx:{gens:3,coh:-1,myst:2}},{n:'Accueillir leurs dieux près de vos camps',d:'Mystique +3. Ouvre la voie des temples et du syncrétisme.',fx:{myst:3}}]},
e1700pg:{y:1700,si:()=>S.traque>25,tag:'Conte',an:'',t:'Les pièges des chasseurs',b:'Sur les sentiers des Hauts, vos guetteurs trouvent des collets et des fosses couvertes de branches, posés par les chasseurs de marrons.',v:'Les chasseurs de marrons posaient bien des pièges et suivaient les traces des fuyards.',o:[{n:'Défaire les pièges en silence',d:'Traque −4, un bras de moins cette saison.',fx:{traque:-4},f:()=>{if(S.bras>1)S.bras--}},{n:'Les retourner contre eux',d:'Gardiens +3, traque +3.',fx:{gardiens:3,traque:3}}]},
 e1720cp:{y:1720,si:()=>camps().length>=1&&S.year<abolY(),tag:'Archive',an:'XVIIIᵉ siècle',hist:1,t:'Le captif',b:'Une descente de marrons sur une habitation des Bas ramène des vivres, des outils… et une captive : une esclave de l’habitation, enlevée ou consentante, on ne sait pas toujours.',v:'Les archives décrivent des descentes de marrons sur les habitations, pour des vivres, des outils et souvent des femmes.',o:[{n:'Lui laisser le choix de rester',d:'+1 personne, cohésion +2.',fx:{gens:1,coh:2}},{n:'La garder de force',d:'+1 personne, cohésion −3, traque +5.',fx:{gens:1,coh:-3,traque:5}}]},
 e1735am:{y:1735,si:()=>camps().length>=1,tag:'Conte',an:'',t:'L’amour interdit',b:'La fille d’un colon et un esclave de l’habitation s’aiment en secret. Découverts, ils fuient ensemble vers vos camps. Elle attend un enfant.',v:'Des unions entre colons et esclaves, souvent forcées, parfois choisies, ont donné naissance à une population métissée. Le code noir les punissait.',o:[{n:'Les accueillir',d:'+2 personnes, cohésion +3. Mais le père la fera poursuivre : un détachement vous traque pendant plusieurs saisons.',fx:{gens:2,coh:3,traque:8},f:()=>{S.pours=6;log('Un colon fait poursuivre sa fille : un détachement vous traque.')}},{n:'Les cacher dans un autre îlet',d:'+1 personne, traque +3.',fx:{gens:1,traque:3}}]},
 e1745fm:{y:1745,si:()=>camps().length>=1,tag:'Conte',an:'',t:'La femme du colon',b:'Une femme blanche, maltraitée par son mari, s’enfuit avec un esclave de la maison. On la croit enlevée. Elle demande à vivre dans vos camps.',v:'Les sources parlent surtout d’hommes en fuite. La fuite de femmes de colons vers les marrons reste rare et souvent légendaire.',o:[{n:'L’accepter comme l’une des vôtres',d:'+2 personnes, savoir +2. Poursuite longue : on la cherche partout.',fx:{gens:2,savoir:2,traque:10},f:()=>{S.pours=8}},{n:'La renvoyer discrètement',d:'Traque −2.',fx:{traque:-2}}]},
e1750pc:{y:1750,si:()=>camps().length>=1&&S.year<abolY(),tag:'Conte',an:'XVIIIᵉ siècle',t:'La mémoire de la plaine des Cafres',b:'Sur les pentes de la plaine des Cafres, des femmes marronnes capturées par les détachements ont subi la violence des chasseurs. Des enfants sont nés de ces violences, et la mémoire orale relie à cette histoire certaines familles métissées qui vivront plus tard sur la plaine.',v:'Les violences sexuelles contre les femmes esclaves et marronnes sont largement attestées dans les sociétés esclavagistes. Le lien précis avec les familles de la plaine des Cafres relève de la mémoire orale.',o:[{n:'Protéger les femmes des camps',d:'Gardiens +3, deux bras de garde en plus cette saison.',fx:{gardiens:3},f:()=>{S.bras=Math.max(1,S.bras-1)}},{n:'Garder leurs noms dans les chants',d:'Anciens +3, cohésion +2.',fx:{anciens:3,coh:2}}]},
e1770eau:{y:1770,tag:'Archive',an:'',t:'Les rivières sous la pierre',b:'Vos pisteurs découvrent que l’eau de pluie disparaît dans le basalte et ressort plus bas, claire et froide. Près du volcan, d’anciens tunnels de lave mènent à ces eaux cachées.',v:'Le sous-sol de l’île est une immense éponge de roches volcaniques : une grande partie de l’eau circule sous terre et ressort en sources. Les tunnels de lave du Piton de la Fournaise se visitent encore.',o:[{n:'Chercher les tunnels',d:'Savoir +1. Certaines cases près du volcan ouvrent l’action « tunnel de lave ».',fx:{savoir:1}}]},
e1780mc:{y:1780,si:()=>camps().length>=1,tag:'Mythe',an:'',nat:'Croyance populaire reprise dans le jeu.',t:'Le bichique qui devient macabit',b:'Les vieux pêcheurs disent que le bichique ne meurt jamais tout à fait : celui qui reste en mer devient macabit, et celui qui remonte la rivière devient mange-crabe, qui guette au fond des bassins. Il faut donc toujours en laisser passer.',v:'En réalité, le bichique est la larve du cabot, un petit poisson de rivière. Le macabit est un mérou de récif, sans lien avec lui. Mais la leçon du mythe est juste : trop pêcher en mer et à l’embouchure vide les rivières.',o:[{n:'Toujours en laisser passer',d:'Les bichiques se reconstituent plus vite. Mystique +1.',fx:{myst:1},f:()=>{S.bich=Math.min(100,(S.bich??100)+20)}}]},
 gouv:{y:1689,si:()=>S&&S.voieC&&!S.gouv&&(camps().length>=2||S.year>=1735),tag:'Conte',an:'',get t(){return S.year<1767?'La Compagnie cherche un gouverneur':'Le Roi cherche un gouverneur'},b:'Vos habitations tiennent, les quartiers vous écoutent. Un navire apporte une lettre scellée : on vous offre de gouverner l’île.',v:'Vous deviendriez gouverneur : un bras de plus chaque saison, un chemin royal à ordonner, mais la colonie entière à porter.',h:'Les vrais : Étienne Regnault, premier commandant en 1665 ; Henri Habert de Vauboulon, premier à porter le titre de gouverneur en 1689, déposé par les habitants l’année suivante ; Mahé de La Bourdonnais, gouverneur général des Mascareignes de 1735 à 1746.',o:[{n:'Accepter la charge',d:'Vous devenez gouverneur. Bras +1 par saison, colonie +10, cohésion −2',fx:{ami:10,coh:-2},f:()=>{S.gouv=S.year;log('Vous êtes nommé gouverneur de l’île.')}},{n:'Rester habitant',d:'Cohésion +4. La lettre repart avec le navire.',fx:{coh:4},hist:1}]},
 prefet:{y:1947,si:()=>S&&S.voieC&&S.gouv,tag:'Archive',an:'1947',t:'Le dernier gouverneur',b:'L’île devient un département. Le gouverneur laisse la place à un préfet, nommé par Paris.',v:'Votre titre change : vous êtes préfet.',h:'Loi de départementalisation du 19 mars 1946 ; le premier préfet, Paul Demange, arrive en 1947.',o:[{n:'Prendre la préfecture',d:'Colonie +4',fx:{ami:4}}]},
 debut94:{sys:1,tag:'Archive',an:'1794',get t(){return S&&S.voieC?'1794 : une lettre de Paris':'1794 : la rumeur monte aux Hauts'},get b(){return S&&S.voieC?'L’île s’appelle La Réunion depuis l’an dernier. Vos habitations font du café et des vivres, avec des esclaves venus de Madagascar et d’Afrique. Un navire annonce qu’à Paris, la Convention a aboli l’esclavage. L’Assemblée coloniale refuse de publier le décret.':'L’île s’appelle La Réunion depuis l’an dernier. Vos camps tiennent les Hauts depuis plusieurs générations. Par les esclaves qui fuient, une nouvelle monte : à Paris, on a aboli l’esclavage. Mais en bas, personne ne l’a annoncé.'},v:'Vous commencez en 1794. Le décret, l’arrivée des agents de Paris en 1796 et le retour de Napoléon en 1802 se jouent maintenant : vos choix peuvent changer l’histoire.',o:[{n:'Commencer',d:'',fx:{}}]},
 e1795d:{y:1795,hist:1,si:()=>S&&S.br&&S.br.abolT,tag:'Conte',an:'1795',t:'Le décret circule',get b(){return S&&S.voieC?'On parle du décret dans les boutiques de Saint-Denis. Certains colons pauvres le soutiennent ; les grands planteurs menacent.':'Dans les cases, on se répète la nouvelle à voix basse. Des ateliers entiers regardent vers les Hauts.'},v:'Pour que les agents de Paris restent en 1796, il faudra plus qu’une rumeur.',get o(){return S&&S.voieC?[{n:'Affranchir vos propres esclaves',d:'Vous donnez l’exemple. Bras −1 cette saison, cohésion +6, la colonie gronde (−8).',fx:{coh:6,ami:-8,bras:-1},f:()=>{S.br.abolT++;pencher({c:4,e:-6})}},{n:'Laisser faire',d:'Rien de plus.',fx:{}}]:[{n:'Soulever un atelier',d:'Des esclaves descendent avec vous. Personnes +3, traque +10, santé −4.',fx:{gens:3,traque:10,sante:-4},f:()=>{S.br.abolT++;pencher({m:3,e:-4})}},{n:'Attendre',d:'Rien de plus.',fx:{}}]}},
 grenierC:{y:1700,si:()=>S&&!S.voieC&&!S.chienM,tag:'Conte',an:'XVIIIᵉ siècle',t:'Le grenier aux chiens',b:'En bas, le grenier d’une habitation déborde de maïs. Mais des chiens le gardent nuit et jour : les mêmes que les chasseurs lâchent sur vos traces.',v:'Piller nourrit le camp ; un chien apprivoisé sent les détachements avant qu’ils arrivent.',o:[{n:'Piller le grenier de nuit',d:'Vivres +15, santé −3, traque +6. Un chien vous suivra peut-être.',fx:{vivres:15,sante:-3,traque:6},f:()=>{if(rnd()<.5){S.chienM=1;log('Un jeune chien du grenier suit vos gens jusqu’au camp.')}}},{n:'Attirer un chien avec de la viande',d:'Vivres −4, traque +2. Le chien reste au camp : il aboie avant les détachements.',fx:{vivres:-4,traque:2},f:()=>{S.chienM=1;log('Un chien du grenier vit désormais au camp.')}},{n:'Ne pas s’approcher',d:'Rien ne change.',fx:{}}]},
 royalB:{y:1960,tag:'Archive',an:'aujourd’hui',t:'Les royal bourbon',b:'Les chiens échappés des greniers et des habitations ont fait souche. À La Réunion, on appelle « royal bourbon » ces chiens errants de toutes les couleurs, croisés de tout. Ils sont encore des dizaines de milliers.',v:'Une mémoire à quatre pattes : ancêtres de chiens de garde, de chasse, de traque.',h:'L’errance animale reste un vrai problème sur l’île : les associations et les communes stérilisent et placent les chiens.',o:[{n:'Ouvrir un refuge',d:'Cohésion +3.',fx:{coh:3}},{n:'Laisser faire',d:'Rien ne change.',fx:{}}]},
 plageV:{y:1986,tag:'Conte',an:'XXᵉ siècle',t:'La plage verte',b:'Après une coulée qui a touché la mer, les vagues roulent les galets neufs. Pendant quelques mois, une anse se couvre de grains verts d’olivine, puis la houle emporte tout.',v:'Une plage éphémère : on y ramasse ce qu’on peut avant qu’elle disparaisse.',o:[{n:'Aller ramasser l’olivine',d:'Pierres : olivine +2, cohésion +2.',fx:{coh:2},f:()=>{S.pi=S.pi||{};S.pi.oli=(S.pi.oli||0)+2}},{n:'La laisser à la mer',d:'Mystique +1.',fx:{myst:1}}]},
 truite:{y:1950,tag:'Archive',an:'XXᵉ siècle',t:'Les truites des cirques',b:'Dans les mares et les rivières fraîches des cirques, on lâche des truites venues d’Europe pour la pêche. Avant, il n’y en avait pas : ces eaux étaient le domaine des cabots, des camarons et des anguilles montés de la mer.',v:'Une espèce de plus, introduite par l’homme.',o:[{n:'Pêcher la truite',d:'Vivres +4.',fx:{vivres:4}},{n:'Laisser les rivières aux cabots',d:'Cohésion +1.',fx:{coh:1}}]},
 espadon:{y:1992,tag:'Archive',an:'années 1990',t:'La pêche à l’espadon',b:'Des palangriers partent au large pour l’espadon et le thon. Le port de la Pointe des Galets devient un port de pêche hauturière.',v:'Du travail en mer, et du poisson pour l’export.',o:[{n:'Armer un palangrier',d:'Vivres +8, colonie +3, forêt intacte.',fx:{vivres:8,ami:3}},{n:'Rester à la pêche côtière',d:'Cohésion +2.',fx:{coh:2}}]},
 baleines:{y:2000,tag:'Archive',an:'hiver austral',t:'Le retour des baleines',b:'Chaque hiver austral, de juin à octobre, les baleines à bosse viennent mettre bas au large de l’île. Les dauphins, que beaucoup appellent ici « marsouins », longent la côte toute l’année.',v:'Un vrai marsouin n’existe pas dans l’océan Indien : le mot désigne ici de petits dauphins.',o:[{n:'Les regarder passer',d:'Mystique +2, cohésion +2.',fx:{myst:2,coh:2}}]},
 requins:{y:2011,tag:'Archive',an:'2011',t:'La crise requin',b:'Une série d’attaques de requins bouledogues et tigres frappe la côte ouest. La baignade et le surf sont interdits hors des zones protégées par des filets.',v:'La mer nourrit et elle tue : la même histoire depuis les premières pirogues.',o:[{n:'Poser des filets et des vigies',d:'Santé +2, colonie +2.',fx:{sante:2,ami:2}},{n:'Laisser la mer aux requins',d:'Mystique +1.',fx:{myst:1}}]},
 ep_maurice1:{sys:1,tag:'Archive',an:'',t:'Le Morne Brabant',get b(){return 'Au sud-ouest de l’île sœur, une montagne tombe à pic dans la mer. Les marrons de l’Île de France s’y cachaient. La tradition raconte qu’en 1835, voyant monter des soldats venus annoncer leur liberté, certains se jetèrent du haut de la falaise.'+(S?ouvreOutTxt('maurice'):'')},v:'Votre comptoir est une fiction du jeu ; ce qu’on y découvre est réel.',o:[{n:'Rapporter les nouvelles',d:'Cohésion +3, mystique +2',fx:{coh:3,myst:2}}]},
 ep_mada1:{sys:1,tag:'Archive',an:'',t:'Les traites de Foulpointe',get b(){return 'Sur la côte est de Madagascar, à Foulpointe et à Tamatave, les navires de Bourbon achètent du riz et des bœufs, et aussi des captifs. Vos gens y retrouvent des familles et des langues que les Hauts n’ont pas oubliées.'+(S?ouvreOutTxt('mada'):'')},v:'Votre comptoir est une fiction du jeu ; ce qu’on y découvre est réel.',o:[{n:'Rapporter les nouvelles',d:'Vivres +8, mystique +1',fx:{vivres:8,myst:1}}]},
 ep_mozamb1:{sys:1,tag:'Archive',an:'',t:'L’île de Mozambique',get b(){return 'Une petite île de corail tenue par les Portugais. De là partent des captifs vers les Mascareignes. Vos gens y croisent des marins, des marchands swahilis et des forgerons de l’intérieur.'+(S?ouvreOutTxt('mozamb'):'')},v:'Votre comptoir est une fiction du jeu ; ce qu’on y découvre est réel.',o:[{n:'Rapporter les nouvelles',d:'Savoir +2',fx:{savoir:2}}]},
 ep_cap1:{sys:1,tag:'Archive',an:'',t:'L’escale du Cap',get b(){return 'Depuis 1652, la Compagnie hollandaise tient l’escale du Cap : de l’eau, du vin, du bétail. Les navires qui vont aux Indes y passent presque tous. Vos gens y voient des troupeaux comme jamais l’île n’en a porté.'+(S?ouvreOutTxt('cap'):'')},v:'Votre comptoir est une fiction du jeu ; ce qu’on y découvre est réel.',o:[{n:'Rapporter les nouvelles',d:'Vivres +6, cohésion +1',fx:{vivres:6,coh:1}}]},
 ep_inde1:{sys:1,tag:'Archive',an:'',t:'Pondichéry',get b(){return 'Le comptoir français de la côte de Coromandel. Les temples, les tisserands, les marchés d’épices. C’est d’ici et de Karikal que partiront, au XIXᵉ siècle, des dizaines de milliers d’engagés pour La Réunion.'+(S?ouvreOutTxt('inde'):'')},v:'Votre comptoir est une fiction du jeu ; ce qu’on y découvre est réel.',o:[{n:'Rapporter les nouvelles',d:'Savoir +2, mystique +1',fx:{savoir:2,myst:1}}]},
 ep_indo1:{sys:1,tag:'Archive',an:'',t:'Les empereurs exilés',get b(){return 'Des Réunionnais partent servir en Indochine, soldats, douaniers, instituteurs. En sens inverse, deux empereurs d’Annam déposés, Thành Thái et Duy Tân, sont exilés à La Réunion en 1916. Duy Tân y vit trente ans.'+(S?ouvreOutTxt('indo'):'')},v:'Votre comptoir est une fiction du jeu ; ce qu’on y découvre est réel.',o:[{n:'Rapporter les nouvelles',d:'Savoir +1, cohésion +2',fx:{savoir:1,coh:2}}]},
 ep_birm1:{sys:1,tag:'Archive',an:'',t:'Les nomades de la mer',get b(){return 'Dans l’archipel de Mergui vivent les Moken, qui passent leur vie sur des bateaux de bois et plongent sans rien pour pêcher. Les marins de passage racontent aussi la boxe des villages birmans, à poings nus.'+(S?ouvreOutTxt('birm'):'')},v:'Votre comptoir est une fiction du jeu ; ce qu’on y découvre est réel.',o:[{n:'Rapporter les nouvelles',d:'Santé +3, mystique +1',fx:{sante:3,myst:1}}]},
 ep_insul1:{sys:1,tag:'Archive',an:'',t:'Les îles aux épices',get b(){return 'Batavia, les Moluques : la Compagnie hollandaise tient le clou de girofle et la muscade. Des marins malais, des Bugis, des esclaves de ces îles finissent jusqu’au Cap et aux Mascareignes, avec leur art du combat, le silat.'+(S?ouvreOutTxt('insul'):'')},v:'Votre comptoir est une fiction du jeu ; ce qu’on y découvre est réel.',o:[{n:'Rapporter les nouvelles',d:'Savoir +1, cohésion +2',fx:{savoir:1,coh:2}}]},
 metisSubi:{y:1705,si:()=>S&&!S.voieC&&S.pp&&S.year<1830&&S.pp.some(p=>p.g==='f'&&ageP(p)>=16&&ageP(p)<=40),tag:'Archive',an:'XVIIIᵉ siècle',t:'L’enfant de la plaine',b:'Une femme du camp, prise par des chasseurs près de la plaine des Cafres puis échappée, revient enceinte. L’enfant aura la peau plus claire que les autres. Sur ce versant, des familles métisses sont nées ainsi, de violences que les archives taisent.',v:'Un enfant ne choisit pas comment il vient au monde.',h:'Les métissages forcés entre chasseurs et femmes marronnes sont une mémoire orale des Hauts du Sud ; les sources écrites en parlent peu.',o:[{n:'L’élever comme les autres enfants du camp',d:'Cohésion +3. L’enfant grandit dans la famille de sa mère.',fx:{coh:3},f:()=>{const m=S.pp.filter(p=>p.g==='f'&&ageP(p)>=16&&ageP(p)<=40)[0];if(m){S.pp.push(enfantDe(m,null,{cu:{eu:1,mg:0,af:0,in:0}}));S.gens++;log('Un enfant naît au camp, dans la famille de '+m.n+'.')}},hist:1},{n:'Le confier aux anciens',d:'Mystique +2, cohésion +1.',fx:{myst:2,coh:1},f:()=>{const m=S.pp.filter(p=>p.g==='f'&&ageP(p)>=16)[0];if(m){S.pp.push(enfantDe(m,null,{cu:{eu:1,mg:0,af:0,in:0}}));S.gens++}}}]},
 premFam:{y:1675,si:()=>S&&S.voieC,tag:'Archive',an:'fin du XVIIᵉ siècle',t:'Les premières familles',b:'Les premiers colons sont presque tous des hommes. Beaucoup épousent des femmes venues de Madagascar ou de l’Inde portugaise. Les premières familles de Bourbon sont métisses dès le départ.',v:'Vos quartiers naissent mêlés.',o:[{n:'Bénir ces mariages à la chapelle',d:'Cohésion +4, colonie +2.',fx:{coh:4,ami:2},f:()=>{(S.pp||[]).filter(p=>p.or==='eu'&&adulte(p)).slice(0,2).forEach(p=>{const f=nouvellePersonne({or:'mg',g:p.g==='h'?'f':'h',age:20,st:'libre'});S.pp.push(f);S.gens++;unir(p,f,true)})},hist:1},{n:'Attendre des femmes de France',d:'Cohésion −2. Il en viendra peu.',fx:{coh:-2}}]},
 libresC:{y:1740,si:()=>S&&S.voieC&&S.year<1848,tag:'Archive',an:'XVIIIᵉ siècle',t:'Les enfants des habitations',b:'Sur les habitations, des maîtres ont des enfants avec des femmes qu’ils tiennent en esclavage. Certains les affranchissent et les installent sur un bout de terre dans les bas : ce sont les « libres de couleur ». Beaucoup d’autres restent esclaves de leur propre père.',v:'Une population nouvelle, libre mais tenue à l’écart.',h:'Les libres de couleur sont plusieurs milliers à Bourbon à la fin du XVIIIᵉ siècle.',o:[{n:'Les affranchir et leur donner une terre dans les bas',d:'Personnes +2 (libres, créoles), cohésion +3, colonie −3.',fx:{coh:3,ami:-3},f:()=>{for(let i=0;i<2;i++){const b=nouvellePersonne({or:'cr',age:16+Math.floor(rnd()*6),st:'libre'});b.cu={eu:.5,mg:.3,af:.2,in:0};S.pp.push(b);S.gens++}log('Deux enfants des habitations sont affranchis et installés dans les bas.')}},{n:'Les garder à l’habitation',d:'Comme le plus souvent dans l’histoire réelle. Bras gardés, cohésion −2.',fx:{coh:-2},hist:1}]},
 e1793n:{y:1793,si:()=>S&&(!S.nom||S.nom==='Bourbon'||S.nom==='La Réunion'),tag:'Archive',an:'19 mars 1793',t:'Le nom de l’île',b:'À Paris, la Convention efface le nom des rois : Bourbon devient La Réunion. On dit que le nom célèbre la « réunion » des fédérés de Marseille et des gardes nationaux de Paris, qui ont pris les Tuileries le 10 août 1792 et fait tomber la monarchie. Le décret, lui, n’explique rien.',v:'Sur l’île, chacun raconte le nom à sa façon.',h:'Deux versions populaires sont des mythes : la « réunion des peuples » de l’île est une lecture venue bien plus tard, et Napoléon n’a pas nommé l’île — il l’a au contraire appelée Île Bonaparte en 1806.',o:[{n:'Retenir la raison de la Convention',d:'Savoir +1.',fx:{savoir:1},hist:1},{n:'Raconter la réunion des peuples (mythe)',d:'Cohésion +2 : une belle histoire, même si elle n’est pas celle de 1793.',fx:{coh:2}},{n:'Croire que Napoléon l’a nommée en réunion (mythe)',d:'Mystique +1. Ce récit circule encore, mais il est faux.',fx:{myst:1}}]},
 noirsDet:{y:1735,si:()=>S&&S.voieC&&S.year<1848,tag:'Archive',an:'XVIIIᵉ siècle',t:'Les hommes du détachement',b:'Les détachements qui montent traquer les marrons emmènent des hommes esclaves : porteurs, pisteurs, parfois tireurs. Semaine après semaine, ils apprennent les sentiers des Hauts, les sources, les grottes.',v:'Ce qu’ils apprennent peut servir la traque… ou leur propre fuite.',h:'Les archives des détachements citent des esclaves et des libres de couleur parmi les chasseurs de marrons.',o:[{n:'Les récompenser, jusqu’à l’affranchissement',d:'Menace marronne −8, cohésion +2, colonie −2.',fx:{coh:2,ami:-2},f:()=>{S.ins=Math.max(0,(S.ins||0)-8)},hist:1},{n:'Les garder sous bonne garde',d:'Colonie +2, mais un pisteur pourrait s’enfuir : menace +6, une personne de moins.',fx:{ami:2},f:()=>{if(rnd()<.5){S.ins=Math.min(100,(S.ins||0)+6);fx({gens:-1});log('Un pisteur du détachement a disparu dans les Hauts, avec tout ce qu’il savait.')}}}]},
 changerAir:{y:1850,si:()=>S&&S.voieC&&(S.gouv||camps().length>=3),tag:'Archive',an:'XIXᵉ siècle',t:'Changer d’air',b:'Les grandes familles ont souvent plusieurs maisons : l’habitation au milieu des champs, une maison de ville à Saint-Denis pour la vie mondaine, et pendant l’été chaud, une villa dans les Hauts, à Hell-Bourg ou à la Plaine des Palmistes, pour « changer d’air ». Le maître, lui, reste souvent à l’habitation.',v:'La famille se disperse au fil des saisons.',o:[{n:'Envoyer la famille dans les Hauts pour l’été',d:'Santé +4, colonie +3, un bras de moins cette saison.',fx:{sante:4,ami:3,bras:-1},hist:1},{n:'Garder tout le monde à l’habitation',d:'Cohésion +3.',fx:{coh:3}}]},
 rueParis:{y:1850,si:()=>S&&S.voieC,tag:'Archive',an:'XIXᵉ siècle',t:'La rue de Paris',b:'À Saint-Denis, les grandes familles du sucre bâtissent leurs villas le long de la rue de Paris : varangues, lambrequins de bois découpé, jardins à bassin derrière les grilles de fer. On y reçoit le gouverneur, on y marie les enfants entre familles.',v:'Une noblesse du sucre, qui vit entre la ville et l’habitation.',o:[{n:'Bâtir votre villa rue de Paris',d:'Colonie +6, cohésion −2 : la famille vit en ville, loin des champs. Bois −3, pierre −3.',fx:{ami:6,coh:-2},f:()=>{S.res.bois=Math.max(0,S.res.bois-3);S.res.pierre=Math.max(0,S.res.pierre-3);const t=camps()[0];if(t&&BAT.maisonVille){const o=tl(t.i);o.vl=o.vl||[];const n=o.vl.length,a=n*1.9+.6,d=.55+(n%3)*.22;o.vl.push({k:'maisonVille',dx:Math.cos(a)*d,dz:Math.sin(a)*d})}log('Votre famille a sa villa rue de Paris.')},hist:1},{n:'Rester à l’habitation',d:'Cohésion +3.',fx:{coh:3}}]},
 grandesFam:{y:1760,si:()=>S&&S.voieC&&S.year<1848,tag:'Archive',an:'XVIIIᵉ siècle',t:'Les grandes familles',b:'Chaque région de l’île a ses grandes maisons : quelques familles qui possèdent les meilleures terres, se marient entre elles et ont l’oreille du gouverneur. Leurs commandeurs tiennent les esclaves, leurs chasseurs mènent les milices qui montent traquer les marrons. Ce sont elles qui font la loi, plus que les ordonnances.',v:'Entrer dans ce cercle fermé, ou rester à côté.',h:'Les grands propriétaires siègent aux assemblées et fournissent l’essentiel des chefs de détachement.',o:[{n:'Marier un de vos enfants dans une grande famille',d:'Colonie +8, cohésion −2. Vos milices deviennent plus fortes (menace marronne plus basse à chaque détachement).',fx:{ami:8,coh:-2},f:()=>{S.allFam=1;log('Votre famille entre dans le cercle des grandes maisons.')},hist:1},{n:'Rester un habitant à part',d:'Cohésion +3.',fx:{coh:3}},{n:'S’opposer à leur pouvoir',d:'Colonie −8, cohésion +5. Elles ne l’oublieront pas.',fx:{ami:-8,coh:5}}]},
 fA1:{y:1750,tag:'Conte',an:'1750',nat:'Fiction du jeu, inspirée des récits récents sur le marronnage ; personnages inventés.',t:'La fille qui court',get b(){return 'Sur une habitation de l’Ouest, une jeune fille s’enfuit une nuit vers les Hauts. Son père, coupeur de canne, l’apprend au matin. Le maître fait venir la chasseuse de marrons la plus redoutée de l’île, une femme qu’on dit sans pitié, avec ses chiens et ses pisteurs.'},get o(){return S&&S.voieC?[{n:'Lâcher la chasseuse sur sa trace',d:'Menace marronne −6, cohésion −2.',fx:{coh:-2},f:()=>{S.ins=Math.max(0,(S.ins||0)-6);S.fA='chasse'},hist:1},{n:'Laisser partir la fille',d:'Cohésion +2, colonie −2.',fx:{coh:2,ami:-2},f:()=>{S.fA='libre'}}]:[{n:'Recueillir la fille au camp',d:'Personnes +1, traque +6.',fx:{gens:1,traque:6},f:()=>{S.fA='camp'},hist:1},{n:'La guider plus haut, vers un autre camp',d:'Mystique +1.',fx:{myst:1},f:()=>{S.fA='loin'}}]}},
 fA2:{y:1752,si:()=>S&&S.done.fA1,tag:'Conte',an:'1752',nat:'Fiction du jeu ; personnages inventés.',t:'Le père dans la forêt',b:'Le père a fui à son tour. Sans armes, il remonte les ravines en suivant les signes laissés par sa fille, avec la chasseuse à quelques jours derrière lui.',get o(){return S&&S.voieC?[{n:'Doubler la prime',d:'Colonie +3, menace +3 : la fuite donne des idées aux autres.',fx:{ami:3},f:()=>{S.ins=Math.min(100,(S.ins||0)+3)},hist:1},{n:'Abandonner la poursuite',d:'Cohésion +2.',fx:{coh:2}}]:[{n:'Les réunir au camp',d:'Personnes +1, cohésion +4. Le père et la fille se retrouvent.',fx:{gens:1,coh:4},hist:1},{n:'Effacer leurs traces',d:'Traque −4, pistage +1.',fx:{traque:-4},f:()=>{S.pist=(S.pist||0)+1}}]}},
 fA3:{y:1754,si:()=>S&&S.done.fA2,tag:'Conte',an:'1754',nat:'Fiction du jeu ; personnages inventés.',t:'La chasseuse',b:'La chasseuse arrive au bord du rempart. Elle a perdu des chiens et des hommes, mais elle ne redescend pas.',get o(){return S&&S.voieC?[{n:'Elle ramène des captifs',d:'Colonie +4, menace −6, cohésion −3.',fx:{ami:4,coh:-3},f:()=>{S.ins=Math.max(0,(S.ins||0)-6)},hist:1},{n:'Elle revient seule',d:'Menace +4 : les Hauts ont gagné.',f:()=>{S.ins=Math.min(100,(S.ins||0)+4)},fx:{}}]:[{n:'Lui tendre une embuscade',d:'Traque −10, santé −4.',fx:{traque:-10,sante:-4}},{n:'Se taire et la laisser passer',d:'Cohésion +3. Elle repart sans rien.',fx:{coh:3},hist:1}]}},
 fB1:{y:1806,tag:'Conte',an:'1806',nat:'Fiction du jeu, inspirée des récits récents sur l’esclavage à Bourbon ; personnages inventés.',t:'Après le cyclone',b:'Un cyclone a tout couché : la canne, les cases, le moulin. Le maître de la plantation voisine est ruiné et doit vendre ses terres. Dans les cases, on sait ce que veut dire une vente : les familles seront séparées.',get o(){return S&&S.voieC?[{n:'Racheter les terres et les esclaves',d:'Colonie +5, cohésion −3, personnes +4.',fx:{ami:5,coh:-3,gens:4},hist:1},{n:'Racheter en gardant les familles ensemble',d:'Cohésion +4, colonie −3, personnes +4.',fx:{coh:4,ami:-3,gens:4}}]:[{n:'Accueillir ceux qui fuient avant la vente',d:'Personnes +2, traque +5.',fx:{gens:2,traque:5},hist:1},{n:'Rester cachés : la colonie cherche partout',d:'Traque −3.',fx:{traque:-3}}]}},
 fB2:{y:1807,si:()=>S&&S.done.fB1,tag:'Conte',an:'1807',nat:'Fiction du jeu ; personnages inventés.',t:'Le fils du maître',b:'Un jeune homme de la plantation apprend que le maître qui l’a fait fouetter est aussi son père. Il ne dit rien, mais quelque chose a changé dans ses yeux.',get o(){return S&&S.voieC?[{n:'Le reconnaître et l’affranchir',d:'Cohésion +3, colonie −2, une personne libre de plus.',fx:{coh:3,ami:-2,gens:1}},{n:'Faire comme si de rien n’était',d:'Menace marronne +5 : il finira par partir.',fx:{},f:()=>{S.ins=Math.min(100,(S.ins||0)+5)},hist:1}]:[{n:'Il rejoint les Hauts avec les siens',d:'Personnes +2, mystique +1.',fx:{gens:2,myst:1},hist:1},{n:'Il reste en bas pour protéger sa mère',d:'Cohésion +2.',fx:{coh:2}}]}},
 foretPrim:{y:1665,tag:'Archive',an:'1665',t:'L’île d’avant',b:'Quand arrivent les premiers habitants, les bas sont couverts de forêt : bois de couleurs, palmistes, lataniers sur la côte sous le Vent, fanjans géants dans les ravines humides de l’Est. Des tortues géantes paissent par centaines, l’ibis marche sans peur, la huppe et les perroquets crient dans les arbres.',v:'Presque tout cela va disparaître : les tortues, l’ibis, la huppe, une partie des forêts. Ce qui manque, l’imaginaire l’a souvent comblé avec les récits venus de Madagascar.',h:'La tortue terrestre de La Réunion, l’ibis (le « solitaire ») et la huppe de Bourbon ont disparu entre le XVIIIᵉ et le XIXᵉ siècle.',o:[{n:'Chasser ce qui ne fuit pas',d:'Vivres +8. Les tortues reculent.',fx:{vivres:8},hist:1},{n:'Prélever avec mesure',d:'Mystique +1, cohésion +1.',fx:{myst:1,coh:1}}]},
 filao:{y:1780,tag:'Archive',an:'fin du XVIIIᵉ siècle',t:'Les filaos',b:'Un arbre venu d’Océanie et d’Asie arrive dans l’île : le filao. On le plante sur les plages et les dunes pour tenir le sable, à l’Hermitage puis à l’Étang-Salé, et pour le bois de chauffe et la cuisine.',v:'Aujourd’hui, le bruit du vent dans les filaos est celui des plages de l’Ouest.',o:[{n:'Planter des filaos sur la côte',d:'Bois +4, forêt +2, plantes envahissantes +3.',fx:{foret:2},f:()=>{S.res.bois+=4;S.inv=Math.min(100,(S.inv||0)+3)},hist:1},{n:'Garder les arbres d’ici',d:'Cohésion +1.',fx:{coh:1}}]},
 vigneM:{y:1845,tag:'Archive',an:'XIXᵉ siècle',t:'La vigne marronne',b:'Une ronce venue d’Asie arrive dans l’île. Dans l’Est, très arrosé, elle couvre tout : bords de champs, forêts abattues, ravines. On l’appelle la vigne marronne.',v:'Avant elle, les bas n’étaient pas couverts de ronces : c’est une arrivée du XIXᵉ siècle.',o:[{n:'Arracher sans relâche',d:'Bras −1 cette saison, plantes envahissantes −6.',fx:{bras:-1},f:()=>{S.inv=Math.max(0,(S.inv||0)-6)}},{n:'Vivre avec',d:'Plantes envahissantes +5 ; on en mange les mûres.',fx:{vivres:2},f:()=>{S.inv=Math.min(100,(S.inv||0)+5)},hist:1}]},
 plUtiles:{y:1720,tag:'Archive',an:'XVIIIᵉ siècle',t:'Les plantes utiles qui s’échappent',b:'On plante le ricin pour son huile, qui éclaire les lampes et soigne ; plus tard le cassi, dont les cabris raffolent. Les graines voyagent avec les bêtes, le fourrage, les sacs des navires. Ces plantes utiles s’échappent des enclos et deviennent les mauvaises herbes des bords de chemin.',v:'Les cabris, eux, étaient là avant les colons : les marins en lâchaient sur les îles pour trouver de la viande à l’escale suivante.',o:[{n:'Planter ricin et fourrage',d:'Bétail +2, vivres +3, plantes envahissantes +4.',fx:{vivres:3},f:()=>{S.bet=(S.bet||0)+2;S.inv=Math.min(100,(S.inv||0)+4)},hist:1},{n:'Garder les bêtes au piquet',d:'Cohésion +1.',fx:{coh:1}}]},
 sensitiveG:{y:1950,tag:'Archive',an:'XXᵉ siècle',t:'La grande sensitive',b:'Dans les champs de canne pousse une cousine géante de la sensitive : une liane à petits crochets qui s’agrippe à la peau des coupeurs, avec des fleurs en pompons roses. Venue d’Amérique tropicale, elle couvre vite les bords de champs.',v:'La date de son arrivée dans l’île est mal connue ; elle s’est répandue avec les cultures.',o:[{n:'La couper avant la récolte',d:'Bras −1 cette saison, plantes envahissantes −4.',fx:{bras:-1},f:()=>{S.inv=Math.max(0,(S.inv||0)-4)}},{n:'Couper la canne avec des gants',d:'Santé −1, plantes envahissantes +3.',fx:{sante:-1},f:()=>{S.inv=Math.min(100,(S.inv||0)+3)},hist:1}]},
 deMada:{y:1700,tag:'Archive',an:'XVIIIᵉ siècle',t:'Ce qui vient de Madagascar',b:'Avec les navires de traite et de riz arrivent aussi des plantes et des bêtes de la Grande Île : le vacoa, dont on tresse les feuilles ; la ravenale, l’arbre du voyageur ; la pervenche de Madagascar, plante à tisane ; le tangue, petit hérisson que l’on chasse et que l’on mange ; l’endormi, le caméléon. Plus tard viendra le flamboyant, qui rougit l’île à Noël.',v:'Une part du paysage « créole » est malgache.',o:[{n:'Planter et élever ce qui vient de là-bas',d:'Vivres +3, mystique +1, plantes envahissantes +2.',fx:{vivres:3,myst:1},f:()=>{S.inv=Math.min(100,(S.inv||0)+2)},hist:1},{n:'S’en tenir à ce qui pousse déjà',d:'Cohésion +1.',fx:{coh:1}}]},
 villeConf:{sys:1,tag:'',an:'',get t(){const c=S&&S.vc;return c?(S.traque>70?'Des chasseurs avec les colons':(S.ami??20)<30?'Les colons veulent la place':'Une demande de partir'):'La colonie arrive'},get b(){const c=S&&S.vc;if(!c)return '';const nom=c.b==='camp'?'votre camp':(BAT[c.b]?BAT[c.b].n.toLowerCase():'votre terrain');return S.traque>70?'Les colons viennent fonder '+c.v+' sur '+nom+'. Ils ont amené des chasseurs : ceux qu’ils prendront finiront esclaves.':(S.ami??20)<30?'Des colons armés arrivent pour fonder '+c.v+' sur '+nom+'. Ils ne demandent rien : ils prennent.':'Des colons viennent fonder '+c.v+' et vous demandent de laisser '+nom+'. Ils proposent un dédommagement.'},
 get o(){const c=S&&S.vc;if(!c)return [{n:'Continuer',d:'',fx:{}}];const pars=(msg,f)=>({n:msg[0],d:msg[1],fx:f||{},f:()=>{const o=tl(c.i);delete o.b;o.c=1;o.clr=1;log('Vos gens quittent la place : '+c.v+' y est fondée.');S.vc=null}});const def=()=>({n:'Défendre la place',d:'Un combat : si vous tenez, la colonie s’installera plus loin.',fx:{traque:4},f:()=>{c.def=1;(S.bats=S.bats||[]).push(c.i);S.evq.push('bat')}});
  if(S.traque>70)return [pars(['Fuir avant qu’ils arrivent','Vous perdez la place, mais personne n’est pris.']),{...def(),n:'Se battre pour ne pas être pris'},{n:'Se cacher dans la forêt voisine',d:'Risqué : deux des vôtres peuvent être capturés.',fx:{},f:()=>{const o=tl(c.i);delete o.b;o.c=1;if(rnd()<.6){fx({gens:-2});log('Deux des vôtres ont été pris par les chasseurs.')}S.vc=null}}];
  if((S.ami??20)<30)return [def(),pars(['Partir sans combattre','Vivres +4 : on emporte ce qu’on peut.'],{vivres:4})];
  return [pars(['Partir avec le dédommagement','Vivres +8, colonie +3.'],{vivres:8,ami:3}),{n:'Négocier pour rester',d:'Colonie −5 : la ville se fonde autour de vous, vous gardez la place.',fx:{ami:-5},f:()=>{log(c.v+' se fonde à côté de vous : vous gardez votre place.');S.vc=null}},{...def(),n:'Refuser et défendre la place',fx:{ami:-6,traque:4}}]}},
 palu:{y:1868,tag:'Archive',an:'1868',t:'Le paludisme',b:'Une épidémie de paludisme frappe l’île : les moustiques qui le portent pullulent dans les bas, autour des marais et des canaux des sucreries. Des milliers de morts, surtout sur la côte. Ceux qui le peuvent montent dans les Hauts, plus frais, où le moustique se fait rare.',v:'Les Hauts, froids pour les cultures, deviennent un refuge pour la santé.',o:[{n:'Monter dans les Hauts',d:'Santé +4, bras −1 cette saison.',fx:{sante:4,bras:-1},hist:1},{n:'Assécher les mares et soigner sur place',d:'Santé −4, savoir +2.',fx:{sante:-4,savoir:2}}]},
 clandes:{sys:1,tag:'Archive',an:'',t:'Les passeurs entre les îles',get b(){return 'La nuit, une petite embarcation sans feu longe la côte. À bord, des fugitifs de l’île de France, quelques marchandises cachées, un passeur qui connaît les anses où l’on peut accoster sans être vu.'+(guerreAng()?' Avec la guerre contre l’Angleterre, les passages se multiplient.':'')},v:'Entre Bourbon et l’île de France, on passait en secret : esclaves en fuite, déserteurs, contrebande.',get o(){return S&&S.voieC?[{n:'Les dénoncer à la garnison',d:'Colonie +3.',fx:{ami:3},hist:1},{n:'Acheter la contrebande sans rien dire',d:'Vivres +5, colonie −2.',fx:{vivres:5,ami:-2}}]:[{n:'Accueillir les fugitifs',d:'Personnes +2, traque +3.',fx:{gens:2,traque:3},hist:1},{n:'Échanger avec le passeur',d:'Vivres +4, fusils +1.',fx:{vivres:4},f:()=>{S.fu=(S.fu||0)+1}}]}},
 galC:{sys:1,tag:'Mythe',an:'',nat:'Fiction du jeu ; les tunnels de lave et les sources chaudes de l’île sont réels.',get t(){return 'Sous '+(S.galLieu||'les Hauts')},get b(){return 'Au fond du tube de lave, un courant d’air frais monte d’une fente. On entend de l’eau, très bas. Sous chaque lieu-dit de l’île, les galeries forment un labyrinthe différent.'+(S.leg?' Le savoir du peuple d’Hanuman montrera le chemin et ouvrira les passages secrets.':'')},v:'Personne n’est jamais revenu raconter ce qu’il y a tout au fond.',o:[{n:'Descendre dans le labyrinthe',d:'Un donjon vu de dessus : salles, clés, portes scellées, et un gardien au fond.'+(S&&S.leg?' Avec le chemin d’Hanuman : les tunnels de lave et la salle des savoirs anciens.':''),fx:{},f:()=>{(S.galT=S.galT||{})[S.galTi]=1;setTimeout(()=>ouvrirAventure({mode:'lave',lieu:S.galLieu||'les Hauts',hanuman:!!S.leg,grisgris:S.grisgris||0},galRetour),300)}},{n:'Refermer la fente avec des pierres',d:'Rien ne change.',fx:{},hist:1}]},
 ilGuillaume:{y:1864,tag:'Mythe',an:'1864',nat:'Fiction du jeu sur un lieu réel ; les rites et les secrets sont inventés.',t:'L’îlet à Guillaume',b:'Au fond des gorges de la rivière Saint-Denis, sur un îlet perché, des ouvriers défrichent pour bâtir un établissement. Sous les fougères, ils trouvent des pierres dressées en cercle et des signes gravés que personne ne sait lire. L’ordre vient d’en haut : tout recouvrir et n’en rien dire.',v:'Ce que l’on cache, les gorges le gardent.',h:'Ce qui est réel : de 1864 à 1879, l’îlet à Guillaume abrite un pénitencier agricole pour jeunes détenus, tenu par des religieux. Des enfants y travaillent la terre, isolés au fond des gorges. Les pierres et les rites sont une fiction du jeu.',o:[{n:'Garder le secret, comme demandé',d:'Colonie +2.',fx:{ami:2},hist:1},{n:'Recopier les signes en cachette',d:'Mystique +3, savoir +1 : un fragment du mythe d’avant.',fx:{myst:3,savoir:1},f:()=>{S.mythSout=1}}]},
 e1747b:{y:1747,tag:'Archive',an:'16 octobre 1747',t:'Le combat du Bronchard',b:'Le détachement de François Mussard surprend une bande au Bronchard. Six marrons sont tués.',v:'La traque frappe fort les années suivantes.',o:[{n:'Pleurer les morts',d:'Anciens +3, traque +4',fx:{anciens:3,traque:4}}]},
 e1665s:{y:1665,tag:'Archive',an:'1665',t:'Six soldats dans la montagne',b:'Le commandant Regnault envoie six soldats armés chercher les Malgaches réfugiés dans les Hauts. Ils reviennent bredouilles. Alors on fait porter un message : descendez, et personne ne sera puni.',v:'Accepter, c’est la paix et la côte, mais plus de liberté. Refuser, c’est la montagne, et la colonie se souviendra.',h:'En 1665, six soldats envoyés par Étienne Regnault échouent à réduire les Malgaches. Pour obtenir leur reddition, on leur promet de ne pas les punir (A. Miranville, 2013). Dans la réalité, ils redescendent.',hist:1,o:[{n:'Rester libres dans les Hauts',d:'Gardiens +5, traque +6',fx:{gardiens:5,traque:6},vo:{m:6}},{n:'Accepter la promesse',d:'Une famille redescend : 2 personnes en moins, traque -10, colonial +6',fx:{gens:-2,traque:-10},vo:{c:6}}]},
 petrels:{sys:1,tag:'Archive',an:'',t:'La chasse aux pétrels',b:'Tout en haut, au-dessus de 2 000 mètres, les jeunes pétrels de Barau dorment dans leurs terriers au début de l’année. Le groupe en ramène des paniers entiers, cuits sur un petit feu à l’abri d’une paroi.',v:'En saison des pluies, chasser au-dessus de 1 800 m rapporte beaucoup plus et laisse peu de traces.',h:'À la Vallée secrète de Cilaos, à plus de 2 000 m, les archéologues (A.-L. Dijoux) ont fouillé deux abris de pierre sèche avec un foyer chacun. Les marrons y mangeaient surtout de jeunes pétrels de Barau, un peu de cochon et de cabri. Camp saisonnier, utilisé au début du XIXe siècle (1809-1835).',o:[{n:'Revenir chaque saison des pluies',d:'Vivres +6',fx:{vivres:6}}]},
 mVillele:{y:1788,tag:'Archive',an:'1788',t:'La maison des Panon-Desbassayns',b:'Dans les hauts de Saint-Paul, la famille Panon-Desbassayns achève sa grande maison de pierre. Autour : la sucrerie, les ateliers, un hôpital pour les esclaves. Des centaines de personnes y travaillent de force.',v:'Le domaine est l’une des plus grandes habitations de l’île. La part de l’esclavage pèse sur toute la région de l’Ouest.',h:'Le domaine de Villèle remonte au dernier quart du XVIIIe siècle. La maison est achevée en 1788. C’est aujourd’hui le musée historique de Villèle, lieu de mémoire de l’esclavage.',o:[{n:'Garder les yeux sur l’Ouest',d:'Gardiens +3',fx:{gardiens:3},vo:{e:3}},{n:'Aider les fugitifs de l’habitation',d:'Marronnage +3, traque +5',fx:{traque:5},vo:{m:3}}]},
 mDesb:{y:1800,tag:'Conte',an:'',si:()=>S.done.mVillele,t:'Madame Desbassayns',b:'Le soir, on raconte qu’une maîtresse terrible erre encore autour de la grande maison. Les anciens disent qu’elle brûle dans le volcan pour ce qu’elle a fait à ses esclaves.',v:'Le conte transforme la peur en mémoire.',h:'Ombline Desbassayns a dirigé le domaine après la mort de son mari. Elle est devenue, dans les contes créoles, la figure de la maîtresse cruelle. Le récit est populaire, les historiens le discutent.',o:[{n:'Transmettre le conte',d:'Anciens +3, mystique +2',fx:{anciens:3,myst:2}}]},
 mHazier:{y:1841,tag:'Archive',an:'XIXe siècle',t:'Le domaine du Grand Hazier',b:'À Sainte-Suzanne, une grande case créole au milieu de ses champs. On y cultive bientôt la vanille, fécondée à la main.',v:'Les grandes habitations de l’Est se tournent vers de nouvelles cultures.',h:'Le Grand Hazier est un domaine de vanille de Sainte-Suzanne. La fécondation manuelle de la vanille a été découverte en 1841 par Edmond Albius, un jeune esclave de Sainte-Suzanne. Date de construction de la maison non retrouvée.',o:[{n:'Retenir le nom d’Edmond Albius',d:'Savoir +1',fx:{savoir:1}}]},
 mMRouge:{y:1830,tag:'Archive',an:'XIXe siècle',t:'Le domaine de Maison Rouge',b:'À Saint-Louis, une plantation coloniale élève sa maison des maîtres en bois, avec son jardin et son escalier d’honneur. Autour, les champs s’étendent jusqu’aux ravines.',v:'Le Sud devient terre de grandes habitations.',h:'Le domaine de Maison Rouge, à Saint-Louis, est une ancienne plantation coloniale. Le domaine entier, maison des maîtres comprise, est classé monument historique depuis le 5 mai 2004. Il abrite le musée des arts décoratifs de l’océan Indien (MADOI). Date de construction non retrouvée.',o:[{n:'Observer le Sud',d:'Savoir +1',fx:{savoir:1}}]},
 mFolio:{y:1860,tag:'Archive',an:'XIXe siècle',t:'Les villas de Hell-Bourg',b:'Dans le cirque de Salazie, les familles aisées viennent prendre les eaux. Des villas à varangue et jardin, comme la maison Folio, s’installent là où vivaient les marrons.',v:'Le cirque refuge devient lieu de villégiature.',h:'La maison Folio de Hell-Bourg réunit les traits de la case créole : jardin, varangue, guétali. Date exacte non retrouvée, après la colonisation du cirque à partir de 1830.',o:[{n:'Se souvenir des premiers habitants',d:'Anciens +2',fx:{anciens:2}}]},
 e1738:{y:1738,tag:'Archive',an:'1738',t:'Saint-Denis devient la capitale',b:'Le gouvernement de l’île quitte Saint-Paul pour Saint-Denis. La Bourdonnais y fait bâtir magasins et routes. Les ordres vont plus vite vers les quartiers.',v:'La colonie s’organise : ses détachements partent de deux villes au lieu d’une.',o:[{n:'Surveiller la route du Nord',d:'Gardiens +3',fx:{gardiens:3}}]},
 trChoix:{sys:1,tag:'',an:'',t:'Une halte sur le sentier',get b(){const t=T[S.trC||0];return 'Le groupe tombe sur un coin riche : du gibier frais dans la boue, des plantes qu’on connaît. On peut s’arrêter ici, ou continuer à ouvrir le sentier.'},v:'Chasser ou cueillir arrête le sentier ici.',
  get o(){const t=T[S.trC||0];return [{n:'Chasser ici',d:'Vivres +'+Math.round(chasseV(t)*.8)+', le sentier s’arrête',f:()=>{fx({vivres:Math.round(chasseV(t)*.8)});traceE=null}},{n:'Cueillir ici',d:'Vivres +'+Math.round(cueilV(t)*1.5)+', santé +2, le sentier s’arrête',f:()=>{fx({vivres:Math.round(cueilV(t)*1.5),sante:2});traceE=null}},{n:'Continuer le sentier',d:'Encore '+((traceE&&traceE.n)||0)+' case(s)',fx:{}}]}},
 captifs:{sys:1,tag:'',an:'',get t(){return (S.capt||1)+' marron'+((S.capt||1)>1?'s ont été repris':' a été repris')},get b(){return 'Les traqueurs les emmènent vers la côte, attachés. On les jugera selon le Code noir, puis ils retourneront aux plantations. Leurs familles sont encore dans les Hauts.'},v:'Les délivrer fait monter la traque. Les laisser fait grandir la part de l’esclavage dans l’île et vous prive de bras pour longtemps.',h:'Les marrons repris étaient punis : fouet, oreilles coupées, marque au fer, et la mort en cas de récidive. Beaucoup ont pourtant fui de nouveau.',
  get o(){const n=S.capt||1;return [{n:'Aller les délivrer',d:'Les '+n+' reviennent, traque +'+Math.max(8,5*n)+', risque d’un mort',fx:{},f:()=>{fx({gens:n-(rnd()<.3?1:0),traque:Math.max(8,5*n),gardiens:3});pencher({m:2});S.capt=0}},{n:'Les laisser partir',d:'Esclavage +'+3*n+', cohésion -4, moins de bras à l’avenir',fx:{coh:-4},f:()=>{pencher({e:3*n});S.autP=(S.autP||0)+n;S.capt=0}}]}},
 dodoSauve:{sys:1,tag:'Mythe',nat:'Les dodos de La Réunion sont une fiction du jeu.',an:'',t:'Les derniers dodos sont chez vous',b:'Dans le Sud, plus un dodo sauvage. Votre parc garde les derniers.',v:'Tant que ce camp n’est jamais attaqué, ils survivent.',o:[{n:'Protéger le parc',d:'Anciens +4, mystique +2',fx:{anciens:4,myst:2}}]},
 droSauve:{sys:1,tag:'Mythe',nat:'Les drontes du Pic Adam sont une fiction du jeu.',an:'',t:'Les derniers drontes sont chez vous',b:'Au Nord, plus un dronte sauvage. Votre parc garde les derniers.',v:'Tant que ce camp n’est jamais attaqué, ils survivent.',o:[{n:'Protéger le parc',d:'Anciens +4, mystique +2',fx:{anciens:4,myst:2}}]},
 famineC:{sys:1,tag:'',an:'',t:'Famine à la colonie',b:'Les récoltes de la côte sont perdues et les navires ne viennent pas. Les colons partent en bandes dans les bois avec leurs fusils et leurs chiens. Ils tuent les oiseaux, même au nid, qu’il en reste peu ou beaucoup.',v:'Pendant 2 saisons, les grands oiseaux sont massacrés et la traque monte.',h:'Bourbon a connu des disettes, surtout après les cyclones qui détruisaient les cultures, comme celui de 1752. Les solitaires ont été chassés jusqu’à disparaître. Le lien entre famine et extermination est une règle du jeu.',o:[{n:'Cacher ce qu’on peut',d:'Traque -3',fx:{traque:-3}}]},
 dernierDodo:{sys:1,tag:'Mythe',nat:'Les dodos de La Réunion sont une fiction du jeu : le vrai dodo vivait à Maurice. Au XVIIe siècle, des voyageurs ont pourtant décrit un « dodo blanc » à Bourbon, et des peintres l’ont représenté : c’était le solitaire, un ibis, ou des dodos de Maurice passés par les navires.',an:'',t:'Le dernier dodo du Sud',b:'Dans les terrasses du Sud, plus aucun gros oiseau ne fouille entre les racines.',o:[{n:'Garder leur mémoire',d:'Anciens +3',fx:{anciens:3}}]},
 dernierDro:{sys:1,tag:'Mythe',nat:'Les drontes du Pic Adam sont une fiction du jeu : le dronte est un autre nom du dodo de Maurice.',an:'',t:'Le dernier dronte du Nord',b:'Sur les hauteurs du Pic Adam, les vieilles fosses de battue restent vides.',o:[{n:'Garder leur mémoire',d:'Anciens +3',fx:{anciens:3}}]},
 solSauve:{sys:1,tag:'',an:'',t:'Les derniers solitaires sont chez vous',b:'Dans la forêt, plus un seul grand oiseau blanc. Mais dans le parc de votre camp, l’éleveur garde un petit troupeau qui pond encore.',v:'Tant que ce camp n’est jamais attaqué, l’espèce survit grâce à vous. Si les colons y arrivent, elle disparaît pour toujours.',h:'Dans la réalité, personne ne les a gardés : le solitaire disparaît au début du XVIIIe siècle. Ici, c’est votre histoire.',o:[{n:'Protéger le parc',d:'Anciens +5, mystique +2',fx:{anciens:5,myst:2}}]},
 dernierSol:{sys:1,tag:'Archive',an:'',t:'Le dernier solitaire',b:'Plus personne ne voit les grands oiseaux blancs. On a trop chassé, et trop vite. Les cochons et les rats des navires mangent les œufs qui restaient.',v:'La chasse rapporte moins : il reste les cabris, les cochons marrons et les oiseaux plus petits.',h:'Le solitaire de La Réunion disparaît au début du XVIIIe siècle. Dans le jeu, une chasse trop forte le fait disparaître plus tôt.',o:[{n:'Garder leur mémoire',d:'Anciens +3, mystique +1',fx:{anciens:3,myst:1}}]},
 tangues:{y:1700,tag:'Archive',an:'XVIIIe siècle',t:'Le tangue venu de Madagascar',b:'Des Malgaches arrivés à Bourbon connaissent un petit animal à piquants qu’ils chassent au pays : le tangue. Il s’installe dans les forêts de l’île.',v:'Le tangue, un tenrec, a été introduit de Madagascar pour être mangé. Sa date d’arrivée exacte est mal connue : 1700 est un choix du jeu.',o:[{n:'Apprendre à le chasser',d:'La chasse en forêt rapporte un peu plus.',fx:{savoir:1}}]},
  dodoX:{y:99999,si:()=>false,tag:'Archive',an:'fin du XVIIe siècle',t:'Le dodo de Maurice n’est plus',b:'À l’île sœur, les marins ne trouvent plus le gros oiseau qu’ils mangeaient à chaque escale. Les cochons, les singes et les rats des navires ont fini les œufs.',v:'Le dodo, aussi appelé dronte, vivait seulement à Maurice. Il disparaît à la fin du XVIIe siècle.',o:[{n:'Le raconter aux enfants',d:'Anciens +2',fx:{anciens:2}}]},
 siege:{sys:1,tag:'',an:'',t:'Le camp est assiégé',b:'Votre camp n’a pas bougé depuis plus de dix ans. La colonie connaît maintenant ses sentiers. Des hommes armés tiennent les passages, les chiens gardent les sources.',v:'Dans deux saisons, ce sera l’assaut, avec une force bien plus grande qu’un détachement. Levez le camp et refondez-le plus loin.',h:'Les grandes battues de la fin des années 1740 et 1750, menées par des chefs de détachement comme Mussard, visaient les camps connus. Un camp qui restait au même endroit finissait repéré et pris.',o:[{n:'Compris',d:'Utilisez « Lever le camp » sur le camp encerclé.'}]},
 debut:{sys:1,tag:'Archive',an:'novembre 1663',t:'Dix personnes dans la montagne',b:'Le 10 novembre 1663, un navire a déposé dans la baie de Saint-Paul Louis Payen, un autre Français, sept hommes et trois femmes de Madagascar. Parmi elles, sans doute Marie Caze, Marguerite Caze et Anne Finna. La dispute a éclaté très vite. Les Malgaches ont pris la montagne.',h:'Selon l’historien Alexis Miranville (2013), c’est le Lansmeer qui mouille à Saint-Paul le 10 novembre 1663 ; on cite souvent le Saint-Charles. Les raisons de la fuite : trop peu de femmes, la méfiance envers les Français, et le départ de huit Français qui devaient rester.',v:'Ces dix personnes sont les premiers habitants durables de l’île. Le jeu commence avec elles.',o:[{n:'Monter plus haut',d:'Vous êtes dans les Hauts de Saint-Paul.'}]},
 e1665:{y:1665,tag:'Archive',an:'1665',t:'Vingt colons à Saint-Paul',b:'Étienne Regnault débarque avec vingt colons recrutés par la Compagnie. Depuis la crête, on voit la fumée de leurs cases. Faut-il rester loin d’eux ?',v:'Selon l’historien Miranville, les Malgaches de Payen ont rejoint le groupe de Regnault. Ici, le jeu suit celles et ceux qui auraient choisi de rester libres : c’est une uchronie.',o:[{n:'Rester dans les Hauts',d:'Anciens +6, Gardiens +6',fx:{anciens:6,gardiens:6}},{n:'Observer leurs cases de nuit',d:'8 vivres et Jardinières +4, traque +8',fx:{vivres:8,jardin:4,traque:8}}]},
 e1674:{y:1674,tag:'Archive',an:'1674',t:'Fort-Dauphin est tombé',b:'À Madagascar, la révolte chasse les Français de Fort-Dauphin. Des navires arrivent à Bourbon avec des survivants et de nouvelles personnes asservies. Deux d’entre elles trouvent votre sentier.',o:[{n:'Les accueillir',d:'+2 personnes, vivres -4, Anciens +3',fx:{gens:2,vivres:-4,anciens:3}},{n:'Les cacher plus bas, le temps de voir',d:'+1 personne, traque +3, Gardiens +3',fx:{gens:1,traque:3,gardiens:3}}]},
 e1696:{y:1696,tag:'Archive',an:'1696',t:'Les premières concessions',b:'La terre de la côte est désormais découpée et attribuée. Là où il y avait des bois, il y a des bornes. Les Jardinières veulent savoir jusqu’où elle montera.',o:[{n:'Marquer une limite dans les Hauts',d:'Gardiens +5, cohésion +4',fx:{gardiens:5,coh:4}},{n:'Partir explorer plus loin',d:'+2 bras cette saison, Anciens -2',f:()=>{S.bras+=2},fx:{anciens:-2}}]},
 e1704:{y:1704,tag:'Archive',an:'1704',t:'311 esclaves recensés',b:'Le recensement compte 311 esclaves dans l’île. Plus ils sont nombreux, plus la montagne attire. Un petit groupe arrive de nuit, épuisé, avec des chiens loin derrière.',o:[{n:'Accueillir tout le groupe',d:'+3 personnes, traque +10, cohésion +3',fx:{gens:3,traque:10,coh:3}},{n:'Les guider vers un refuge plus sûr',d:'+1 personne, vivres -3, Gardiens +3',fx:{gens:1,vivres:-3,gardiens:3}}]},
 e1715:{y:1715,tag:'Archive',an:'1715',t:'Le temps du café',b:'Les premiers plants de café de Moka arrivent. La colonie défriche et réclame des bras. La traite s’accélère. Sur la côte, la forêt recule d’une saison à l’autre.',v:'Nouvelle époque : la colonie avance plus vite. Avec l’esclavage, ceux qui ne sont pas en bons termes avec la colonie seront chassés.',o:[{n:'Compter ce qu’il nous reste',d:'Savoir +3, cohésion +2',fx:{savoir:3,coh:2}}]},
 e1721p:{y:1721,tag:'Archive',an:'1721',t:'La Vierge du Cap',b:'Des pirates, dont La Buse, prennent en rade de Bourbon un grand vaisseau portugais, la Vierge du Cap, avec une cargaison énorme. Leurs hommes descendent à terre pour échanger.',o:[{n:'Échanger avec les pirates',d:'10 vivres, +1 personne, Colonie -8',fx:{vivres:10,gens:1,ami:-8}},{n:'Prévenir les autorités',d:'Colonie +14, Gardiens -4',fx:{ami:14,gardiens:-4}},{n:'Rester à l’écart',d:'Cohésion +2',fx:{coh:2}}]},
 e1721m:{y:1722,tag:'Archive',an:'1721',t:'Cap sur Maurice',b:'La France occupe l’Île de France, l’actuelle Maurice, et des colons de Bourbon partent la peupler. Une place sur un bateau, c’est une autre vie.',o:[{n:'Faire embarquer des nôtres',d:'-3 personnes, traque -8. Débloque le passage vers Maurice.',f:()=>{S.maur=true},fx:{gens:-3,traque:-8},l:'Un lien est ouvert vers Maurice.'},{n:'Rester sur l’île',d:'Anciens +4',fx:{anciens:4}}]},
 e1746:{y:1746,tag:'Archive',an:'1746',t:'Les corsaires de La Bourdonnais',b:'La guerre reprend contre les Anglais. La Bourdonnais arme ses navires et cherche des hommes pour aller prendre Madras. Les corsaires promettent une part des prises et, parfois, l’oubli du passé.',o:[{n:'Embarquer comme corsaires',d:'14 vivres, -2 personnes, Colonie +16. Colonial +8.',fx:{vivres:14,gens:-2,ami:16},vo:{c:8}},{n:'Piller leurs arrières',d:'10 vivres, Colonie -12, Gardiens +6',fx:{vivres:10,ami:-12,gardiens:6}}]},
 e1690f:{y:1690,tag:'',an:'1690',t:'Pierres, sagaies et fusils',b:'Dans les Hauts, on se bat avec des pierres, des sagaies et des pièges. Les détachements ont des fusils. Chaque fusil pris dans une descente vaut plus que dix sagaies.',v:'Les fusils volés rendent vos guerriers plus précis en combat.',o:[{n:'Apprendre à s’en servir',d:'Gardiens +5',fx:{gardiens:5}}]},
 e1672:{y:1672,tag:'Archive',an:'1672',t:'Quinze Indiens à Bourbon',b:'Le navire Jules débarque quinze Indiens dans l’île. Beaucoup d’esclaves indiens de Bourbon porteront ensuite des noms tamouls. Certains entendent parler de la montagne.',v:'Date attestée par le portail de l’esclavage, qui précise que ce n’est pas forcément la toute première arrivée.',o:[{n:'Leur ouvrir le sentier',d:'+1 personne, savoir +2',fx:{gens:1,savoir:2}},{n:'Rester cachés',d:'Traque -3',fx:{traque:-3}}]},
 e1724:{y:1724,tag:'Archive',an:'années 1720',t:'Les pirates deviennent colons',b:'Le roi offre une amnistie aux anciens forbans qui acceptent de s’installer à Bourbon. Des pirates raccrochent, d’autres prendront la course pour le roi comme corsaires.',o:[{n:'Recruter d’anciens forbans',d:'+2 personnes, +1 fusil, Anciens -3',f:()=>{S.fu=(S.fu||0)+1},fx:{gens:2,anciens:-3}},{n:'Se méfier d’eux',d:'Cohésion +3',fx:{coh:3}}]},
 e1740y:{y:1740,tag:'',an:'1740',t:'Les premiers Yabs',b:'D’anciens corsaires et des colons sans terre montent vers les hauts de Salazie. Ils défrichent juste à côté des villages marrons, sans maître et sans fortune.',h:'Les Yabs, ou petits-blancs des Hauts, sont réels, mais plus tardifs. Une population blanche pauvre et semi-nomade apparaît à la fin du XVIIIe siècle, entre plantations et monde marron. Salazie devient commune dans les années 1830 et les Plaines se peuplent vers 1850. Le lien avec les corsaires et cette date de 1740 sont inventés pour le jeu.',o:[{n:'Partager les îlets',d:'+3 personnes, Jardinières +4, Colonial +4',fx:{gens:3,jardin:4},vo:{c:4}},{n:'Les repousser',d:'Gardiens +5, traque +4',fx:{gardiens:5,traque:4}}]},
 e1748:{y:1748,tag:'Archive',an:'1748',t:'Les Anglais devant l’île sœur',b:'La guerre coloniale contre les Anglais arrive jusqu’à l’Île de France, l’île sœur. Une flotte anglaise tente de la prendre, et Bourbon arme ses hommes.',o:[{n:'Aider l’île sœur',d:'-2 personnes, Colonie +14, Gardiens +4',fx:{gens:-2,ami:14,gardiens:4}},{n:'Piller pendant que la côte se vide',d:'14 vivres, Colonie -14, traque +6',fx:{vivres:14,ami:-14,traque:6}}]},
 e1723:{y:1723,tag:'Archive',an:'1723',t:'Le Code Noir à Bourbon',b:'Un texte règle maintenant le droit des maîtres sur les personnes. Le marronnage y est puni. Ceux qui arrivent portent les marques de ces peines.',o:[{n:'Soigner d’abord',d:'Santé -4, cohésion +8, Jardinières +4',fx:{sante:-4,coh:8,jardin:4}},{n:'Répondre par une descente',d:'8 vivres, traque +10, Gardiens +8',fx:{vivres:8,traque:10,gardiens:8}}]},
 e1735:{y:1735,tag:'Archive',an:'1735',t:'6 500 esclaves pour 1 700 libres',b:'Mahé de La Bourdonnais gouverne l’île et le café tourne à plein. Sur la côte, presque quatre personnes sur cinq sont asservies. Saint-Denis deviendra bientôt la capitale.',o:[{n:'Ouvrir les sentiers aux fugitifs',d:'+3 personnes, traque +8',fx:{gens:3,traque:8}},{n:'Fortifier ce qui existe',d:'Gardiens +6, Anciens +3',fx:{gardiens:6,anciens:3}}]},
 e1742:{y:1742,tag:'Archive',an:'1742',t:'François Mussard',b:'Les colons armés s’organisent pour capturer les marrons. François Mussard, grand chasseur de marrons, est promu chef de détachement.',v:'Les détachements seront plus nombreux à partir de maintenant.',o:[{n:'Doubler les guetteurs',d:'Gardiens +8, vivres -4',fx:{gardiens:8,vivres:-4}},{n:'Éteindre les feux une saison',d:'Traque -12, santé -5',fx:{traque:-12,sante:-5}}]},
 e1752:{sys:1,tag:'Archive',an:'1752',t:'Laverdure, roi de tous les marrons',b:'Mussard apprend l’existence de Laverdure, « roi de tous les marrons », marié à Sarlave, avec Sarcemate pour lieutenant. En décembre, les camps sont pris. Laverdure et Sarcemate sont tués.',v:'Ces noms sont attestés. Les marrons ont formé dans les Hauts ce qu’on appelle le royaume de l’intérieur.',o:[{n:'Les Hauts après Laverdure',d:'Le jeu continue jusqu’à aujourd’hui : les grandes chasses finissent, la colonie se couvre de grandes constructions.',fx:{coh:-5,traque:-10}}]},
 fievre:{tag:'',an:'',t:'La fièvre dans le camp',si:()=>!S.leg&&!S.voieC,b:'Un mal gagne les abris. Les plus âgés toussent et les enfants ne mangent plus.',o:[{n:'Isoler les malades',d:'Santé -6, Anciens -3',fx:{sante:-6,anciens:-3}},{n:'Tout le monde s’en occupe',d:'Santé -10, cohésion +6, -1 bras',fx:{sante:-10,coh:6,bras:-1}}]},
 tortues:{tag:'Archive',an:'',t:'Les tortues se font rares',b:'Les tortues de terre, si nombreuses autrefois, ont presque disparu des basses pentes. Les navires en emportent par centaines.',v:'La tortue terrestre de La Réunion a disparu, chassée en masse pour nourrir les équipages.',o:[{n:'Interdire la chasse près des camps',d:'Vivres -5, Anciens +5',fx:{vivres:-5,anciens:5}},{n:'Prendre tant qu’il en reste',d:'8 vivres, Anciens -5',fx:{vivres:8,anciens:-5}}]},
 anchain:{tag:'Mythe',an:'',t:'Le piton d’Anchaing',si:()=>S.year>1700,b:'On raconte qu’Anchaing vit avec Héva dans une caverne de Salazie, hors d’atteinte des chasseurs. Les jeunes veulent le rejoindre.',h:'Un esclave malgache nommé Anchengue apparaît au recensement de 1751 à Sainte-Suzanne, et le piton porte son nom. Aucune archive ne confirme Héva. Leur épopée vient surtout du récit d’Eugène Dayot, publié au XIXe siècle.',o:[{n:'Envoyer un messager',d:'Savoir +3, Gardiens +3',fx:{savoir:3,gardiens:3}},{n:'Garder chacun au camp',d:'Cohésion +4',fx:{coh:4}}]},
 kal:{tag:'Mythe',an:'',t:'Le cri de Grand-Mère Kal',si:()=>S.year>1680,b:'Un oiseau noir crie « tout tout » au-dessus du camp. Pour les Anciens, c’est Grand-Mère Kal : une maîtresse cruelle, changée en oiseau par le breuvage de l’esclave Mafate et condamnée à prévenir du danger.',h:'Aucune personne réelle n’est identifiée. La tradition orale garde plusieurs versions : maîtresse esclavagiste, mère esclave nommée Kalla, complice de bagnards près de Mahavel, ou sorcière du volcan.',o:[{n:'Écouter et déplacer les guetteurs',d:'Traque -8, Anciens +3',fx:{traque:-8,anciens:3}},{n:'Rire de la vieille histoire',d:'Cohésion +3, Anciens -4',fx:{coh:3,anciens:-4}}]},
 mafate:{tag:'Mythe',an:'',t:'Mafate le guérisseur',si:()=>S.year>1700,b:'Dans le grand cirque, on parle d’un chef guérisseur nommé Mafate, couvert de colliers d’os. Ceux qui reviennent de chez lui ne craignent plus les fièvres.',h:'Le nom du cirque apparaît sur la carte de 1878, et un plan de 1834 porte un « Bras de Mafaque ». Mussard passe pour l’avoir surpris vers 1751, sans certitude. Le portrait du chef vient de récits de chasseurs et d’Eugène Dayot.',o:[{n:'Lui demander ses remèdes',d:'Santé +10, Anciens +3',fx:{sante:10,anciens:3}},{n:'Refuser son autorité',d:'Gardiens +4, cohésion -3',fx:{gardiens:4,coh:-3}}]},
 cimendef:{tag:'Mythe',an:'',t:'Cimendef, chef de la Grande Terre',si:()=>S.year>1710,b:'Cimendef se dit chef de la Grande Terre et ne veut pas partager les pics. Ses envoyés réclament une part de vos vivres.',h:'Le nom figure sur la carte de Selhausen en 1812 et reste attaché à un piton de Mafate. Son caractère belliqueux vient des récits de Dayot, publiés bien après les faits.',o:[{n:'Partager et faire alliance',d:'8 vivres perdus, Gardiens +6, traque -4',fx:{vivres:-8,gardiens:6,traque:-4}},{n:'Refuser',d:'Gardiens +3, cohésion -4',fx:{gardiens:3,coh:-4}}]},
 mover:{tag:'Mythe',an:'',t:'Le mové lèr',b:'À midi, personne ne veut passer sous les grands arbres : c’est le mové lèr, l’heure où les esprits y sont. Le soir, on raconte comment Ti Jean a encore trompé Gran Diab.',h:'Ti Jean et Gran Diab sont des personnages centraux des contes réunionnais. Les croyances du mové lèr mêlent des traditions africaines, malgaches, indiennes et européennes, ce qui montre que ces récits sont nés du mélange des populations.',o:[{n:'Veiller et raconter',d:'Cohésion +7, -1 bras',fx:{coh:7,bras:-1}},{n:'Travailler quand même',d:'6 vivres, Anciens -4',fx:{vivres:6,anciens:-4}}]},
 labuse:{y:1730,tag:'Mythe',an:'1730',t:'Le trésor de La Buse',b:'Le pirate Olivier Levasseur, dit La Buse, vient d’être pendu à Bourbon. Sur la côte, on dit qu’il a lancé un message codé à la foule et qu’un trésor dort quelque part dans l’océan Indien.',h:'La pendaison du 7 juillet 1730 est attestée. Le collier jeté depuis l’échafaud n’apparaît dans aucune source d’époque. Le cryptogramme n’est mentionné qu’à partir de 1934, dans un livre de Charles de La Roncière, et sa solution n’a jamais été confirmée. Les historiens tiennent ce trésor pour une fiction du XXe siècle.',o:[{n:'Envoyer chercher le trésor',d:'-2 bras, savoir +2, rien de plus',fx:{bras:-2,savoir:2}},{n:'Laisser les colons creuser',d:'Traque -5',fx:{traque:-5}}]},
 dimitile:{y:1743,tag:'Mythe',an:'1743',t:'Le capitaine Dimitile',b:'Un capitaine nommé Dimitile mène 24 marrons, des hauts de Saint-Paul à ceux de Saint-Pierre. Il propose d’unir vos forces.',h:'Le portail de l’esclavage cite Dimitile à la tête de 24 marrons en 1743. Son nom est resté à un plateau du Sud, mais une grande partie du récit des chefs marrons repose sur Dayot.',o:[{n:'Unir les forces',d:'+3 personnes, Gardiens +6, traque +6',fx:{gens:3,gardiens:6,traque:6}},{n:'Rester indépendants',d:'Cohésion +3',fx:{coh:3}}]},
 bat:{sys:1,tag:'',an:'',t:'Un détachement attaque un camp',b:'Les chasseurs arrivent par le sentier. Vous pouvez laisser le camp se défendre seul, ou placer vous-même vos guerriers dans le décor.',o:[{n:'Résoudre automatiquement',d:'Le terrain, le guet et les Gardiens décident.',f:()=>combat(T[S.bats.shift()],null)},{n:'Placer mes guerriers',d:'Falaises, arbres, rivière et pièges.',f:()=>ouvrirBat(S.bats[0],'camp')},{n:'Combattre vous-même',d:'Vue à la première personne* : sagaie, bâton, couvert des arbres.',f:()=>{ouvrirBat(S.bats[0],'camp');$('bat').hidden=true;ouvrirFPS('colons')}}]},
 batE:{sys:1,tag:'',an:'',t:'Tendre l’embuscade',b:'Le détachement monte sans vous avoir vus. Comment voulez-vous l’attaquer ?',o:[{n:'Résoudre automatiquement',d:'Chance selon les pièges et les Gardiens.',f:()=>{const ok=rnd()<.55+(S.sv.pieges?.2:0)+(defFac('gardiens')?.1:0)+Math.min(.15,(S.fu||0)*.03);finEmb(ok,ok?0:1)}},{n:'Placer mes guerriers',d:'Falaises, arbres, rivière et pièges.',f:()=>ouvrirBat(S.embus,'emb')},{n:'Combattre vous-même',d:'Vue à la première personne* : surprendre le détachement sur le sentier.',f:()=>{ouvrirBat(S.embus,'emb');$('bat').hidden=true;ouvrirFPS('colons')}}]},
 beauGibier:{sys:1,tag:'',an:'',t:'Belle chasse',get b(){return 'Le groupe surprend '+(fa('sol')>0?'des cabris marrons et des solitaires, ces grands oiseaux blancs qui fuient à peine l’homme':'une harde de cabris marrons et des cochons sauvages')+', et rentre chargé.'},h:'Les cabris et les cochons ont été lâchés sur l’île par les navires de passage au XVIIe siècle, avant le peuplement. Le solitaire de La Réunion était un ibis, disparu au début du XVIIIe siècle, chassé par les hommes et les animaux introduits. Le dodo et le dronte vivaient à Maurice : à La Réunion, ils ne figurent que dans les cartes de fiction du jeu.',o:[{n:'Partager au camp',d:'8 vivres, cohésion +2',fx:{vivres:8,coh:2}}]},
 blesse:{sys:1,tag:'',an:'',t:'Un blessé en forêt',b:'Une chute dans un ravin. Il faut porter le blessé jusqu’au camp.',o:[{n:'Le ramener',d:'Santé -4, -1 bras',fx:{sante:-4,bras:-1}}]},
 colonsCh:{sys:1,tag:'',an:'',t:'Des colons chassent ici',b:'Vos chasseurs entendent des chiens : des colons battent la même forêt.',o:[{n:'Se cacher et attendre',d:'Vivres -3, traque +3',fx:{vivres:-3,traque:3}},{n:'Leur voler leur prise',d:'8 vivres, traque +9, Colonie -8',fx:{vivres:8,traque:9,ami:-8}}]},
 source:{sys:1,tag:'',an:'',t:'Une source cachée',b:'Le groupe trouve une eau claire que personne ne connaît.',o:[{n:'Marquer le lieu',d:'Santé +6',fx:{sante:6}}]},
 grotte:{sys:1,tag:'',an:'',t:'Une grotte sèche',b:'Une caverne assez grande pour cacher toute une famille.',o:[{n:'En faire un refuge',d:'Traque -6, Anciens +2',fx:{traque:-6,anciens:2}}]},
 marronSeul:{sys:1,tag:'',an:'',t:'Un marron isolé',b:'Un homme vit seul ici depuis des années. Il connaît tous les sentiers.',o:[{n:'L’inviter au camp',d:'+1 personne, savoir +1',fx:{gens:1,savoir:1}}]},
 simple:{sys:1,tag:'',an:'',t:'Une plante rare',b:'Les cueilleuses reconnaissent une feuille qui fait tomber la fièvre.',o:[{n:'La conserver',d:'Santé +7',fx:{sante:7}}]},
 miel:{sys:1,tag:'',an:'',t:'Du miel sauvage',b:'Un essaim dans un vieux tronc : du miel pour plusieurs jours.',o:[{n:'Le rapporter',d:'5 vivres',fx:{vivres:5}}]},
 epave:{sys:1,tag:'',an:'',t:'Une cargaison perdue en mer',b:'La houle a jeté sur la côte des caisses d’un navire disparu : toiles, outils, et peut-être une arme.',o:[{n:'Tout monter de nuit',d:'6 vivres, +1 fusil, 3 bois',f:()=>{S.fu=(S.fu||0)+1;S.res.bois+=3},fx:{vivres:6}}]},
 butin:{sys:1,tag:'',an:'',t:'Un magasin mal gardé',b:'Pendant la descente, un magasin reste ouvert.',o:[{n:'Le vider',d:'6 vivres, 2 pierre, traque +4',f:()=>{S.res.pierre+=2},fx:{vivres:6,traque:4}}]},
 colonsZone:{tag:'',an:'',si:()=>(S.nEx||0)>=6&&S.year>=1690,t:'Battue dans vos zones',b:'Des colons montent chasser dans les zones que vous exploitez. Vos terrains ne sont plus secrets.',o:[{n:'Abandonner le gibier un temps',d:'Vivres -6, traque -4',fx:{vivres:-6,traque:-4}},{n:'Les effrayer',d:'Traque +10, Gardiens +5, Colonie -6',fx:{traque:10,gardiens:5,ami:-6}}]},
 visiteRoi:{tag:'',an:'',si:()=>S.year>=1700,t:'Un envoyé du roi',b:'Un envoyé du roi inspecte l’île. Les colons veulent montrer des Hauts tranquilles : les battues redoublent le temps de sa visite.',o:[{n:'Faire le mort',d:'Traque -8, -1 bras',fx:{traque:-8,bras:-1}},{n:'Lui faire parvenir une supplique',d:'Colonie +10, Gardiens -4',fx:{ami:10,gardiens:-4}}]},
 corsaireV:{tag:'',an:'',si:()=>S.year>=1700,t:'Un corsaire à la côte',b:'Un corsaire cherche de l’eau et des vivres contre des armes, sans poser de question.',o:[{n:'Échanger',d:'Vivres -8, +1 fusil',f:()=>{S.fu=(S.fu||0)+1},fx:{vivres:-8}},{n:'Le dénoncer',d:'Colonie +10',fx:{ami:10}}]},
 marchand:{tag:'',an:'',si:()=>S.year>=1690,t:'Un marchand de passage',b:'Un marchand propose du sel et des outils à qui peut payer, sans passer par la Compagnie.',o:[{n:'Acheter',d:'Vivres -6, 4 bois, 3 pierre, Colonial +3',f:()=>{S.res.bois+=4;S.res.pierre+=3},fx:{vivres:-6},vo:{c:3}},{n:'Refuser',d:'Anciens +2',fx:{anciens:2}}]},
 marronsMaurice:{tag:'',an:'',si:()=>S.year>=1722&&!S.voieC,t:'Des marrons de Maurice',b:'Une pirogue arrive de l’Île de France avec des marrons qui fuient les chasseurs de là-bas.',o:[{n:'Les accueillir',d:'+3 personnes, vivres -5',fx:{gens:3,vivres:-5}},{n:'Les aider à repartir',d:'Savoir +2, vivres -2',fx:{savoir:2,vivres:-2}}]},
 passeurs:{tag:'',an:'',si:()=>S.year>=1680&&!S.voieC,t:'Les passeurs de Madagascar',b:'Des passeurs de Madagascar débarquent de nuit des esclaves évadés et des colons en fuite, cachés ensemble dans la même cale.',o:[{n:'Prendre les évadés',d:'+2 personnes, traque +4',fx:{gens:2,traque:4}},{n:'Prendre aussi les colons en fuite',d:'+3 personnes, Colonial +4, Anciens -3',fx:{gens:3,anciens:-3},vo:{c:4}}]},
 rafles:{tag:'',an:'',si:()=>S.year>=1700,t:'Les enfants des rafles',b:'Après une rafle coloniale, des enfants métis, rejetés par leurs pères comme par la plantation, arrivent aux villages marrons. Personne ne les a inscrits nulle part.',o:[{n:'Les élever au village',d:'+2 personnes, vivres -5, cohésion +5',fx:{gens:2,vivres:-5,coh:5}}]},
 soeur:{tag:'',an:'',si:()=>S.maur,t:'Nouvelles de l’île sœur',b:'Une pirogue de Maurice apporte des nouvelles et des graines. Vos passeurs font vivre le lien entre les deux îles.',o:[{n:'Échanger',d:'Savoir +2, 4 vivres',fx:{savoir:2,vivres:4}}]},
 morne:{tag:'Mythe',an:'',si:()=>S.out&&S.out.maurice&&!S.voieC,t:'Les marrons du Morne',b:'À Maurice, des marrons se cachent sur le rocher du Morne. Ils font passer un message à vos gens : ici aussi, on tient la montagne.',h:'Le Morne Brabant a bien servi de refuge aux esclaves marrons et il est classé par l’UNESCO. La légende de ceux qui se seraient jetés de la falaise à l’annonce de l’abolition, au XIXe siècle, est une tradition orale.',o:[{n:'Échanger des guides',d:'Savoir +2, Gardiens +3',fx:{savoir:2,gardiens:3}}]},
 dodoM:{tag:'Mythe',an:'',si:()=>S.out&&S.out.maurice,t:'Le dernier dodo',b:'Les vieux de Maurice parlent d’un gros oiseau qui ne volait pas, disparu en quelques années à cause des marins et des animaux qu’ils ont amenés.',h:'Le dodo vivait à Maurice et il a disparu à la fin du XVIIe siècle, à la suite de l’arrivée des Hollandais.',o:[{n:'Protéger le gibier de vos zones',d:'Vivres -4, Anciens +5',fx:{vivres:-4,anciens:5}}]},
 anglais:{tag:'',an:'',si:()=>S.out&&Object.keys(S.out).length&&S.year>=1744,t:'Une frégate anglaise',b:'Les Anglais sont maintenant l’ennemi de tous les secteurs français. Une frégate capture votre bateau de liaison.',o:[{n:'Armer une riposte',d:'-2 personnes, 8 vivres perdus, Gardiens +6',fx:{gens:-2,vivres:-8,gardiens:6}},{n:'Couper la liaison un temps',d:'Cohésion -4',fx:{coh:-4}}]},
 capLib:{tag:'',an:'',si:()=>S.out&&S.out.cap&&!S.voieC,t:'Libérer les esclaves du Cap',b:'Vos gens du Cap veulent attaquer une ferme de colons boers et libérer les esclaves qui y travaillent.',o:[{n:'Mener la libération',d:'+3 personnes, traque +6, Marronnage +6',fx:{gens:3,traque:6},vo:{m:6}},{n:'Rester discrets',d:'Anciens +2',fx:{anciens:2}}]},
 mozLib:{tag:'',an:'',si:()=>S.out&&S.out.mozamb,t:'Un navire de traite au Mozambique',b:'Un navire charge des captifs pour les Mascareignes. Vos alliés peuvent l’attaquer avant le départ.',o:[{n:'Attaquer le navire',d:'+3 personnes, Colonie -10',fx:{gens:3,ami:-10}},{n:'Laisser passer',d:'Cohésion -5',fx:{coh:-5}}]},
 epices:{tag:'',an:'',si:()=>S.out&&S.out.indo,t:'Les épices d’Indochine',b:'Une route lointaine ramène des plants inconnus et des récits de royaumes puissants.',o:[{n:'Planter dans les Hauts',d:'6 vivres, savoir +3',fx:{vivres:6,savoir:3}}]},
 conquete:{tag:'',an:'',si:()=>S.year>=1744,t:'Les Anglais viennent conquérir',b:'Des voiles anglaises croisent devant la côte. Ils ne cherchent pas seulement des prises : ils veulent les îles. La colonie tremble et cherche des bras partout.',h:'Dans la réalité, la conquête anglaise vient plus tard : les Anglais prennent Bourbon et Maurice en 1810. Bourbon est rendue à la France en 1815, Maurice reste anglaise. Dans ce jeu, leur menace arrive plus tôt.',o:[{n:'Défendre l’île avec la colonie',d:'-2 personnes, Colonie +16, Colonial +6',fx:{gens:-2,ami:16},vo:{c:6}},{n:'Profiter du désordre',d:'+2 personnes, 8 vivres, Colonie -12',fx:{gens:2,vivres:8,ami:-12}}]},
 kabare:{tag:'Mémoire',an:'',si:()=>S.year>1680,t:'Le service kabaré',b:'La nuit, on frappe le rouleur et on secoue le kayamb pour nourrir les ancêtres. Les chants viennent de Madagascar et d’Afrique. Les maîtres l’interdisent, les Hauts le gardent.',h:'Les personnes esclavagisées malgaches et africaines ont gardé des rites sacrés et des musiques, devenus créoles. Le service kabaré honore les ancêtres. Le mot maloya remplace séga à partir de 1921. Un arrêté préfectoral tente de l’interdire en 1956, et l’UNESCO l’inscrit au patrimoine immatériel en 2009.',o:[{n:'Tenir le service',d:'Mystique +3, cohésion +4, traque +3',fx:{myst:3,coh:4,traque:3}},{n:'Chanter à voix basse',d:'Mystique +1, Anciens +2',fx:{myst:1,anciens:2}}]},
 ritesT:{tag:'Mythe',an:'',si:()=>S.dec&&S.dec.inde,t:'Les dieux des villages tamouls',b:'Des Indiens arrivés de la côte tamoule apportent leurs dieux de village, leurs marches sur le feu et leurs offrandes, que les prêtres de leur pays refusent souvent de reconnaître.',h:'Des sacrifices d’animaux et des marches sur le feu existent aujourd’hui dans l’hindouisme réunionnais. L’arrivée massive des engagés indiens date surtout d’après 1848. L’origine de caste de ces rites reste à vérifier, et je n’ai pas de source solide pour l’affirmer ici.',o:[{n:'Leur faire place au camp',d:'Mystique +3, +1 personne',fx:{myst:3,gens:1}},{n:'Laisser chacun à ses dieux',d:'Cohésion +2',fx:{coh:2}}]},
 zimba:{tag:'Mythe',an:'',si:()=>S.out&&(S.out.mozamb||S.out.cap),t:'La cité de pierre du Zimbabwe',b:'Des captifs venus de l’intérieur du Mozambique parlent d’une immense cité de pierre, de rois disparus et d’esprits qui parlent par la bouche des vivants.',h:'Le Grand Zimbabwe est un site réel, bâti au Moyen Âge par des populations africaines. Les esprits et les pouvoirs de cette carte relèvent du jeu.',o:[{n:'Apprendre leurs chants',d:'Mystique +3, savoir +2',fx:{myst:3,savoir:2}}]},
 pyramM:{tag:'Mythe',an:'',si:()=>S.out&&S.out.maurice,t:'Les pyramides de Maurice',b:'Vos passeurs ont vu à Plaine Magnien des pyramides de pierre noire, à gradins, sans mortier. Certains y sentent une force venue de la montagne. Les anciens disent que leurs bâtisseurs ont montré la route de Dina Morgabin aux marins arabes, bien avant les Portugais.',h:'Ces structures existent, hautes d’environ dix mètres. L’explication la plus répandue en fait des amas de pierres montés par les travailleurs de la canne. SOS Patrimoine parle des années 1940, sans document pour le prouver. Aucune recherche scientifique approfondie n’a été menée, et le lien avec Kumari Kandam vient de récits mystiques modernes.',o:[{n:'Suivre la piste',d:'Mystique +4. Ouvre le mythe de Kumari Kandam.',f:()=>{S.pyr=1},fx:{myst:4}},{n:'N’y voir que des pierres',d:'Savoir +1',fx:{savoir:1}}]},
 kumari:{tag:'Mythe',nat:'Mythe de pure fiction, créé pour le jeu. Les dates sont imaginaires.',an:'',si:()=>S.pyr&&S.dec&&S.dec.inde,t:'Kumari Kandam, le continent englouti',b:'Le récit se complète. Un continent, Kumari Kandam, aurait dormi sous l’océan Indien. Quand la danse de Shiva dressa l’Himalaya, ses secousses le brisèrent, et leurs frissons allèrent jusqu’en Europe ouvrir la Manche. Les volcans pustulèrent sur toute la Terre : La Réunion, l’Islande et Hawaï en sortirent, et l’Amérique se construisit à son tour. Vos camps dorment sur cette mémoire.',h:'Des textes tamouls parlent de terres englouties. Le nom Kumari Kandam se popularise dans les années 1930, en s’appuyant sur la Lémurie, une hypothèse de 1864 abandonnée depuis la dérive des continents. Les géologues excluent toute civilisation sur ce continent. L’Himalaya naît de la collision de l’Inde avec l’Asie il y a des dizaines de millions d’années, et la Manche n’a pas été ouverte il y a 8 000 ans par ces secousses.',o:[{n:'Faire de ce récit le vôtre',d:'Mystique +6, Anciens +6, cohésion +4',fx:{myst:6,anciens:6,coh:4}}]},
 corsEnrol:{y:1722,si:()=>S.chute,tag:'Mythe',an:'1722',t:'Les pirates enrôlés en corsaires',b:'Les vieux de l’île racontent la suite : après la chute de Libertalia, les pirates libérateurs de Madagascar furent enrôlés comme corsaires pour peupler l’île. Certains montent vers les Hauts avec leurs familles.',h:'Ce lien est de la pure fiction, gardée comme une histoire de vieux. Libertalia n’est connue que par un récit littéraire. L’amnistie offerte aux forbans dans les années 1720 pour s’installer à Bourbon, elle, est rapportée.',o:[{n:'Les accueillir dans les Hauts',d:'+3 personnes, +1 fusil, Anciens -3',f:()=>{S.fu=(S.fu||0)+1},fx:{gens:3,anciens:-3}},{n:'Les laisser à la colonie',d:'Colonie +6, Colonial +4',fx:{ami:6},vo:{c:4}}]},
 apoca:{tag:'Mythe',nat:'Mythe de pure fiction, créé pour le jeu. Les dates sont imaginaires.',an:'',si:()=>S.done.kumari,t:'Le peuple métis de l’apocalypse',b:'Les derniers récits disent qu’un peuple métis fuit les continents brisés. Remontant vers le nord, il aurait posé les bases de l’Égypte ancienne. Plusieurs faits de plusieurs âges semblent réunis ici en une seule époque.',h:'Pure fiction. Ce récit rassemble en une époque des faits très éloignés. La Réunion a environ 2 à 3 millions d’années, l’Islande et Hawaï se sont formées sur des millions d’années, et l’Égypte ancienne n’a pas été fondée par des réfugiés d’un continent englouti.',o:[{n:'Garder ce récit au village',d:'Mystique +4, Anciens +4',fx:{myst:4,anciens:4}},{n:'N’y voir qu’une histoire de veillée',d:'Cohésion +3',fx:{coh:3}}]},
 drav:{tag:'Mythe',nat:'Mythe de pure fiction, créé pour le jeu. Les dates sont imaginaires.',an:'',si:()=>S.done.kumari&&(S.leg||S.tr.length>0),t:'Les temples sous la mer',b:'Le peuple d’Hanuman aurait gardé le souvenir d’un monde dravidien, de l’Inde à l’Indonésie. Un cataclysme aurait enfoui ses temples et dessiné l’Océanie, ne laissant que des îles et des sommets.',h:'Pure fiction pour le lien et le cataclysme. Des royaumes indianisés et des temples hindous et bouddhiques ont bien existé en Indonésie, et de grandes éruptions y ont marqué l’histoire.',o:[{n:'Graver ce récit',d:'Mystique +3, Anciens +3',fx:{myst:3,anciens:3}}]},
 sirene:{tag:'Mythe',an:'',si:()=>S.done.drav,t:'Hanuman et la sirène',b:'On raconte qu’Hanuman, gêné dans la construction d’un pont sur la mer, rencontra une sirène. Plus loin à l’est, un roi singe garde un moine bouddhiste sur la route de l’Inde.',h:'Dans le Ramayana d’Asie du Sud-Est, Hanuman rencontre la sirène Suvannamaccha. Le Roi singe Sun Wukong vient du roman chinois La Pérégrination vers l’Ouest, du XVIe siècle. Il y protège le moine inspiré de Xuanzang, personnage réel du VIIe siècle parti de Chine vers l’Inde. Son lien avec Hanuman est contesté.',o:[{n:'Raconter les deux histoires',d:'Mystique +2, cohésion +3',fx:{myst:2,coh:3}}]},
 tectite:{tag:'Mythe',an:'',si:()=>S.done.drav,t:'Les pierres du ciel',b:'Un voyageur montre des pierres noires et vitreuses, tombées du ciel selon lui. Au Tibet, on les dirait envoyées par les gardiens de Shambhala, et certains y voient le Cintamani, le joyau qui exauce les vœux.',h:'Les tectites sont de vrais verres naturels, formés par l’impact d’une météorite qui fait fondre la roche terrestre, et non un alliage de pierre volcanique et de météorite. Celles d’Asie viennent d’un impact d’il y a environ 800 000 ans. Shambhala et le Cintamani sont de vraies traditions, mais le lien entre ces pierres et le Tibet vient surtout de sites de vente et de lithothérapie. L’obsidienne, elle, est un verre volcanique.',o:[{n:'Les garder au camp',d:'Mystique +3, Gardiens +2',fx:{myst:3,gardiens:2}}]},
 niche:{tag:'Mythe',nat:'Mythe de pure fiction, créé pour le jeu. Les dates sont imaginaires.',an:'',si:()=>S.er>0||S.year>=1700,t:'La niche du volcan',b:'Colons et marrons partagent cette peur : le volcan garderait sa lave dans une niche souterraine, et il respire avant de la rendre. Vos anciens en font un être à honorer.',h:'Le Piton de la Fournaise est bien alimenté par du magma stocké en profondeur. La niche mystique et le mythe des colons sont inventés pour le jeu.',o:[{n:'Faire une offrande',d:'Mystique +3, vivres -3',fx:{myst:3,vivres:-3}},{n:'Observer ses signes',d:'Savoir +2',fx:{savoir:2}}]},
 lanka:{tag:'Mythe',an:'',si:()=>S.done.sirene,t:'La route de Lanka',b:'Des maîtres partis du sud de l’Inde passent par Lanka, l’île d’Hanuman dans le Ramayana, avant de gagner la Chine. Un moine tamoul y aurait porté son enseignement.',h:'Le Bouddha lui-même n’est pas allé en Chine. Ce sont ses disciples, dont Vajrabodhi, de famille tamoule, passé par Sri Lanka vers la Chine. La tradition tamoule fait aussi naître Bodhidharma à Kanchipuram, mais les sources anciennes parlent seulement de l’Inde du Sud ou des régions de l’Ouest.',o:[{n:'Écouter cet enseignement',d:'Mystique +2, savoir +3',fx:{myst:2,savoir:3}}]},
 zeoC:{sys:1,tag:'Mythe',nat:'Mythe créé pour le jeu, à partir d’un minéral réel.',an:'',t:'La pierre qui clarifie',b:'Dans la roche du volcan, de petits cristaux blancs. Là où ils affleurent, l’eau coule claire. Les anciens disent qu’ils tracent le chemin des rivières et réveillent la terre.',h:'Les zéolites sont de vrais minéraux, présents dans les basaltes réunionnais, et elles peuvent filtrer l’eau et améliorer les sols. Dans le jeu, elles agissent seules, sans extraction : aucune exploitation n’a existé à La Réunion à ma connaissance. Le tracé des rivières et la force mystique sont inventés pour le jeu.',o:[{n:'En faire une pierre sacrée',d:'Mystique +2, Anciens +3',fx:{myst:2,anciens:3}},{n:'S’en servir pour les cultures',d:'Jardinières +5',fx:{jardin:5}}]},
 vazimba:{tag:'Mythe',an:'',si:()=>S.out&&S.out.mada,t:'Les Vazimba de Madagascar',b:'Vos gens de la Grande Île parlent des Vazimba, premiers habitants des hautes terres, et des kalanoro, petits êtres des forêts qui guérissent ou égarent.',h:'Les Vazimba et les kalanoro appartiennent aux traditions malgaches. Les Vazimba sont présentés comme les premiers habitants de l’île, et les historiens discutent encore de ce que ce nom recouvre.',o:[{n:'Honorer ces premiers habitants',d:'Mystique +3, Anciens +3',fx:{myst:3,anciens:3}}]},
 monomotapa:{tag:'Mythe',an:'',si:()=>S.out&&S.out.mozamb,t:'L’or du Monomotapa',b:'Au Mozambique, on parle d’un royaume de l’intérieur riche en or, que les Portugais cherchent depuis deux siècles.',h:'Le royaume du Mutapa, dit Monomotapa, a réellement existé dans la région du Zimbabwe et du Mozambique, et les Portugais y ont cherché l’or. Sa richesse fabuleuse tient surtout de la légende.',o:[{n:'Envoyer des éclaireurs',d:'Savoir +2, Mystique +2',fx:{savoir:2,myst:2}}]},
 adamastor:{tag:'Mythe',an:'',si:()=>S.out&&S.out.cap,t:'Adamastor et le Hollandais volant',b:'Au Cap, les marins craignent le géant Adamastor, gardien de la tempête, et un navire fantôme qui ne peut jamais rentrer au port.',h:'Adamastor est un géant inventé par le poète portugais Camões au XVIe siècle. Le Hollandais volant est une légende de marins liée au cap de Bonne-Espérance.',o:[{n:'Faire une offrande à la mer',d:'Mystique +3, vivres -3',fx:{myst:3,vivres:-3}}]},
 cavadee:{tag:'Mythe',an:'',si:()=>S.out&&S.out.inde,t:'Le cavadee de Mourouga',b:'Des dévots portent un arc de fleurs et de plumes de paon en l’honneur de Mourouga, et traversent la douleur par la foi. Draupadi, elle, appelle la marche sur le feu.',h:'Le cavadee et la marche sur le feu viennent des traditions tamoules et se pratiquent aujourd’hui à La Réunion. Leur présence avant 1752 est une liberté du jeu.',o:[{n:'Suivre la procession',d:'Mystique +4, cohésion +3',fx:{myst:4,coh:3}}]},
 naga:{tag:'Mythe',an:'',si:()=>S.out&&S.out.indo,t:'Le dragon et l’immortelle',b:'Sur la route d’Indochine, on raconte qu’un roi dragon et une immortelle des montagnes ont donné naissance à un peuple, et que les nagas gardent les eaux.',h:'Le récit de Lạc Long Quân et d’Âu Cơ est un mythe d’origine vietnamien. Les nagas appartiennent aux traditions de l’Inde et de l’Asie du Sud-Est.',o:[{n:'Rapporter le récit',d:'Mystique +3, savoir +1',fx:{myst:3,savoir:1}}]},
 feu:{tag:'',an:'',t:'La querelle du feu',b:'Les Gardiens veulent éteindre tous les feux la nuit. Les Jardinières répondent que les enfants ont froid.',o:[{n:'Éteindre les feux',d:'Traque -7, santé -5, Gardiens +4, Jardinières -4',fx:{traque:-7,sante:-5,gardiens:4,jardin:-4}},{n:'Garder un feu couvert',d:'Traque +4, Jardinières +5',fx:{traque:4,jardin:5}}]},
 naissance:{tag:'',an:'',si:()=>!S.voieC,t:'Un enfant né libre',b:'Une petite fille naît au camp. Elle n’a jamais été inscrite dans aucun registre.',o:[{n:'Lui donner le nom d’une ancêtre',d:'+1 personne, Anciens +4, cohésion +4',fx:{gens:1,anciens:4,coh:4}}]},
 famille:{tag:'',an:'',t:'Celle qui veut redescendre',si:()=>S.year>1690,b:'Une femme arrivée au dernier cyclone veut retourner chercher son fils resté à la plantation. Le chemin est gardé.',o:[{n:'Monter une expédition',d:'+2 personnes, traque +10, Gardiens +3',fx:{gens:2,traque:10,gardiens:3}},{n:'La retenir',d:'Cohésion -6, Anciens +2',fx:{coh:-6,anciens:2}}]},
 trace0:{sys:1,tag:'Découverte',an:'',t:'Les pierres de Tapcal',b:'Sous les fougères, des pierres portent des signes que personne ici ne sait lire. Elles parlent du peuple d’Hanuman, venu d’Andaman avant tout le monde, qui vivait dans le Sud.',o:[{n:'Chercher plus loin',d:'Première trace'}]},
 trace1:{sys:1,tag:'Découverte',an:'',t:'Les terrasses du Bras de la Plaine',get b(){return 'La forêt n’a pas été brûlée, mais elle pousse en étages trop réguliers. Sous les grands arbres, des plantes utiles sont mêlées aux autres. '+(fa('dodo')>0||nBat('parcDodo')?'Des dodos fouillent encore le sol entre les racines.':'Des os de dodos gisent entre les racines : il n’en reste plus.')+' Quelqu’un a nourri sa famille ici sans abattre un seul tronc.'},o:[{n:'Chercher plus loin',d:'Deuxième trace'}]},
 trace2:{sys:1,tag:'Découverte',an:'',t:'Le vieux jardin de la Langevin',b:'Dans un creux humide, des feuilles et des écorces sont rangées par usage. À côté poussent des racines proches des patates, que personne ne cultive plus ailleurs. Les Jardinières comprennent comment planter sans briser la forêt.',o:[{n:'Garder ces racines',d:'Le Sud a livré son savoir'}]},
 trace3:{sys:1,tag:'Découverte',an:'',t:'Le Beau Pays du Pic Adam',get b(){return 'Au nord, sur les hauteurs du Pic Adam, le peuple d’Hanuman chassait le dronte'+(fa('dro')>0||nBat('parcDro')?'':', disparu aujourd’hui')+'. Les vieilles fosses et les sentiers de battue sont encore lisibles. Le gibier du Nord se prend sans brûler une seule pente.'},o:[{n:'Apprendre cette chasse',d:'Chaque terrain de chasse donne plus de vivres'}]},
 pirates:{sys:1,tag:'Découverte',an:'',t:'Les pirates du nord de Madagascar',b:'Le savoir du Sud circule jusqu’à la côte. Une chaloupe accoste de nuit : ce sont des pirates du nord de Madagascar, qui attaquent les navires négriers et libèrent ceux qu’ils y trouvent. Ils cherchent une terre amie.',o:[{n:'Sceller l’alliance',d:'Tous les 10 ans, 2 personnes libérées et 4 vivres. Chaque descente libère 1 personne de plus. Marronnage +10.',f:()=>{S.pir=true},fx:{gardiens:6,traque:5},vo:{m:10},l:'Alliance avec les pirates libérateurs du nord de Madagascar.'},{n:'Rester seuls dans les Hauts',d:'Anciens +6',fx:{anciens:6}}]},
 libA:{y:1720,si:()=>S.pir,tag:'',an:'1720',t:'Libertalia est attaquée',b:'Des navires de guerre remontent vers le nord de Madagascar. Si Libertalia tombe, plus rien n’arrêtera la colonisation de la Grande Île, et votre île deviendra une simple conquête de plus.',o:[{n:'Envoyer des gens la défendre',d:'-3 personnes, 8 vivres perdus. Libertalia tient. Marronnage +12.',fx:{gens:-3,vivres:-8,gardiens:5},f:()=>{S.lib=(S.lib||30)+25},vo:{m:12},l:'Libertalia tient. La colonisation de Madagascar est arrêtée.'},{n:'La laisser tomber',d:'La colonie avancera plus vite. Colonial +12.',f:()=>{S.chute=1;S.pir=false},vo:{c:12},l:'Libertalia a disparu. La colonisation de Madagascar commence.'}]},
 libB:{y:1720,si:()=>!S.pir,tag:'',an:'1720',t:'Libertalia a disparu',b:'La république des pirates du nord de Madagascar n’existe plus. La colonisation de la Grande Île commence, et Santa Apolonia, devenue Bourbon, n’est plus qu’une découverte de plus sur la carte du colonialisme.',o:[{n:'Tenir les Hauts',d:'La colonie avancera plus vite. Colonial +10.',f:()=>{S.chute=1},vo:{c:10},l:'Libertalia a disparu. La colonisation de Madagascar commence.'}]},
 revolte:{tag:'',an:'',t:'La révolte dans vos propres camps',si:()=>voie().e>=25,b:'Ceux que vous faites travailler de force refusent. Ils ont fui une plantation pour en retrouver une autre, et ils le disent. Des cases brûlent.',o:[{n:'Les libérer',d:'Esclavage -15, marronnage +10, 6 vivres perdus, cohésion +8',fx:{vivres:-6,coh:8},vo:{e:-15,m:10}},{n:'Réprimer',d:'-3 personnes, cohésion -14, esclavage +6',fx:{gens:-3,coh:-14},vo:{e:6}}]},
 comboH:{sys:1,tag:'Découverte',an:'',t:'Le savoir du peuple d’Hanuman',b:'Vous gagnez trois choses. Le Jardin-forêt nourrit sans brûler. La pharmacopée donne +1 santé par saison et la forêt se défend mieux. Le Silence (touche E) fait disparaître tous les camps pendant 2 saisons, et les chasseurs perdent votre piste.',apres:()=>{S.leg=true;log('Le savoir du peuple d’Hanuman est retrouvé.')},o:[{n:'Garder ce savoir',d:'Savoir acquis, car vos gens ont relevé toutes les traces des anciens.'}]}
};
