ARMES.forEach(a=>{if(a.t)EV['arm'+a.y]={y:a.y,tag:'Archive',an:a.an,t:a.t,b:a.b,v:a.v+' Les chasseurs de la colonie deviennent plus forts.',o:[{n:'Se préparer',d:'Gardiens +3',fx:{gardiens:3}}]}});
