function vousHtml(){syncPP();const F={};S.pp.forEach(p=>{(F[p.fa]=F[p.fa]||[]).push(p)});const ad=S.pp.filter(adulte).length;
 let h='<h3>Demoun</h3><p class="note">'+S.pp.length+' personnes, '+ad+' adultes et '+(S.pp.length-ad)+' enfant'+(S.pp.length-ad>1?'s':'')+', en '+Object.keys(F).length+' familles. Chacun a son origine, son âge et ses savoir-faire ; les rôles évoluent avec ce que vous leur faites faire.</p>'+(()=>{const R=ppRoles();return '<p class="note" style="font-size:14px">Guerriers '+R.guer+' (un guetteur de plus au combat par 3) · archers '+R.arch+' (un piège de plus par 2) · éclaireurs '+R.ecl+' · tisaneurs '+R.soin+' (santé chaque saison) · artisans '+R.art+' · gardiens de la mémoire '+R.mem+' (mystique chaque saison). Les enfants apprennent le métier d’un adulte de leur famille.</p><p class="note" style="font-size:14px">Les familles d’un secteur fermé, sans route (Mafate pour toujours, Cilaos jusqu’en 1932, Salazie et les hauts au-dessus de 1 100 m jusque vers 1860), font tout elles-mêmes et deviennent artisanes. Elles gardent un savoir de famille, qui se répand dans toute l’île le jour où la route s’ouvre.</p>'})();
 const tri=Object.values(F).sort((a,b)=>b.length-a.length);
 for(const f of tri){const chef=f.slice().sort((a,b)=>a.na-b.na)[0];{const ct=famCamp(f[0].fa),sf=(S.savF||{})[f[0].fa];h+='<div class="fam"><b>Famille de '+chef.n+'</b><small> · '+f.length+' personne'+(f.length>1?'s':'')+(ct?' · '+(ct.cirq?'cirque de '+ct.cirq:'camp à '+Math.round(ct.alt)+' m')+(ferme(ct)?' · <b style="color:var(--vacoa)">secteur fermé, sans route</b>':''):'')+'</small>'+(sf?'<div style="font-size:13px;color:var(--vacoa)">Savoir de famille : '+ART[sf.k].n+' ('+(S.savFo&&S.savFo[f[0].fa]?'répandu dans l’île depuis '+S.savFo[f[0].fa]:'gardé au secteur depuis '+sf.y)+'). '+ART[sf.k].d+'</div>':'')}
  for(const p of f.slice().sort((a,b)=>a.na-b.na)){const sk=Object.keys(SK).filter(k=>p.sk[k]>0).sort((a,b)=>p.sk[b]-p.sk[a]).slice(0,3);const cu=Object.keys(p.cu).filter(k=>p.cu[k]>.05).map(k=>ORIG[k].slice(0,4)+' '+Math.round(p.cu[k]*100)+'%').join(', ');
   const cj=p.cj&&ppId(p.cj),me=p.mere&&ppId(p.mere);h+='<div class="pers" data-pid="'+p.id+'"><span class="pn">'+(p.g==='f'?'♀':'♂')+' '+p.n+(cj?' <small style="opacity:.7">· uni'+(p.g==='f'?'e':'')+' à '+cj.n+'</small>':'')+(me&&!adulte(p)?' <small style="opacity:.7">· enfant de '+me.n+'</small>':'')+'</span><span class="pa">'+ageP(p)+' ans</span><span class="pr">'+rolePP(p)+'</span><small>'+ORIG[p.or]+' · '+p.st+' · '+(sk.length?sk.map(k=>SK[k]+' '+p.sk[k]).join(', '):'pas encore de savoir-faire')+'<br>Culture : '+cu+'</small></div>'}
  h+='</div>'}
 if(S.morts&&S.morts.length)h+='<h3 style="font-size:16px">Mémoire</h3><p class="note">'+S.morts.slice(-8).reverse().map(m=>m.n+' ('+m.age+' ans, '+m.a+')').join(' · ')+'</p>';return h}

