// ===== Grands personnages : ils apparaissent et évoluent au fil de l'histoire =====
const GP=[
 ['regnault',1665,'Étienne Regnault','Archive','Premier commandant de l’île',[[1665,'Il débarque avec une vingtaine de colons et fonde l’établissement de Saint-Paul.'],[1671,'Il quitte l’île ; la petite colonie compte quelques dizaines d’habitants.']]],
 ['payen',1663,'Louis Payen et Pierre Pau','Archive','Les premiers habitants',[[1663,'Deux Français et dix Malgaches débarquent pour s’installer à Saint-Paul. Les Malgaches fuient bientôt dans les Hauts.']],'c'],
 ['panon',1690,'Augustin Panon','Archive','Colon des premiers temps',[[1690,'Parmi les premiers habitants, il prend des terres dans l’Est de l’île.'],[1720,'Sa descendance s’installe ; la rivière où il avait ses terres garde son nom.']],'c','La commune de Bras-Panon porte son nom.'],
 ['hpanon',1760,'Henri-Paulin Panon Desbassayns','Archive','Planteur, descendant des Panon',[[1760,'Héritier d’une des premières familles de l’île, il épouse Ombline Gonneau : leur domaine de Saint-Paul compte des centaines d’esclaves.'],[1800,'Il meurt ; sa veuve, Madame Desbassayns, reprend tout en main.']],'c','Le nom Desbassayns reste attaché au domaine de Villèle, à Saint-Gilles-les-Hauts.'],
 ['hubert',1770,'Joseph Hubert','Archive','Planteur et botaniste de Saint-Benoît',[[1770,'Sur ses terres de l’Est, travaillées par ses esclaves, il acclimate le giroflier et d’autres plantes venues d’Asie.'],[1825,'Il meurt ; ses jardins ont changé les cultures de l’île.']],'c',''],
 ['parny',1775,'Évariste de Parny','Archive','Poète né à Saint-Paul, fils de planteurs',[[1775,'Fils d’une famille de planteurs propriétaires d’esclaves, il part en France et devient poète.'],[1787,'Ses Chansons madécasses font entendre, à travers des chants malgaches, la violence des colons.']],'',''],
 ['cdesb',1815,'Charles Desbassayns','Archive','Industriel du sucre',[[1815,'Fils de Madame Desbassayns, il fait venir des machines à vapeur pour ses sucreries, cultivées par des esclaves.'],[1848,'À l’abolition, la famille réclame des indemnités et des engagés.']],'c',''],
 ['vauboulon',1689,'Henri Habert de Vauboulon','Archive','Premier à porter le titre de gouverneur',[[1689,'Il arrive et gouverne en maître dur, confisque, punit.'],[1690,'Les habitants se révoltent, le déposent et l’emprisonnent : il meurt en prison.']],'c'],
 ['dumas',1727,'Pierre-Benoît Dumas','Archive','Gouverneur de Bourbon',[[1727,'Il développe les caféières et organise les quartiers.'],[1735,'Il part gouverner Pondichéry, en Inde.']],'c'],
 ['anchaing',1680,'Anchaing et Héva','Conte','Couple marron de la légende',[[1680,'On raconte qu’ils fuient ensemble vers le piton qui porte aujourd’hui le nom d’Anchaing, à Salazie.'],[1700,'Leur histoire devient un récit des veillées : celle d’un amour qui choisit la liberté.']],'m','Le piton d’Anchaing, à Salazie, porte son nom.'],
 ['mussard',1730,'François Mussard','Archive','Chasseur de marrons',[[1730,'Il mène des détachements dans les Hauts.'],[1751,'On raconte qu’il tue Mafate, le chef marron.'],[1760,'Son nom reste attaché aux grandes battues.']]],
 ['labourdonnais',1735,'Mahé de La Bourdonnais','Archive','Gouverneur des Mascareignes',[[1735,'Il arrive : routes, magasins, chantiers navals, il fait de l’Île de France le port des Mascareignes.'],[1746,'Il prend Madras aux Anglais, avec des hommes levés dans les îles.'],[1748,'Accusé à Paris, il est enfermé à la Bastille.'],[1753,'Il meurt peu après sa libération.']],'','Sa statue regarde la mer au Barachois, à Saint-Denis.'],
 ['lislet',1755,'Jean-Baptiste Lislet Geoffroy','Archive','Savant, fils d’une femme esclave',[[1755,'Il naît à Saint-Pierre, d’un ingénieur et d’une femme esclave.'],[1786,'Ses cartes et ses relevés le font entrer comme correspondant à l’Académie des sciences.'],[1836,'Il meurt à l’Île de France, savant reconnu.']],'','Des écoles et des rues portent son nom.'],
 ['desbassayns',1770,'Madame Desbassayns','Archive','Grande propriétaire',[[1770,'Avec son mari, elle bâtit l’un des plus grands domaines de l’île, à Saint-Paul.'],[1800,'Veuve, elle dirige le domaine et des centaines d’esclaves ; elle pousse vers le sucre.'],[1846,'Elle meurt. La légende populaire en fait une figure de cruauté, « Madame Desbassayns » des contes.']],'','Le domaine de Saint-Gilles-les-Hauts est aujourd’hui le musée de Villèle.'],
 ['poivre',1767,'Pierre Poivre','Archive','Intendant des Mascareignes',[[1767,'Il arrive pour le Roi et veut briser le monopole hollandais des épices.'],[1770,'Girofliers et muscadiers arrivent en secret : ils prendront aussi à Bourbon.']]],
 ['albius',1841,'Edmond Albius','Archive','Le garçon de la vanille',[[1841,'À douze ans, esclave à Sainte-Suzanne, il trouve le geste qui féconde la fleur de vanille à la main.'],[1848,'Libéré à l’abolition ; son geste fait la fortune de la vanille, pas la sienne.'],[1880,'Il meurt pauvre.']],'','Sa statue se dresse à Sainte-Suzanne.'],
 ['hell',1838,'Amiral de Hell','Archive','Gouverneur de Bourbon',[[1838,'Il gouverne l’île et s’intéresse aux eaux thermales du cirque de Salazie.'],[1841,'Il quitte l’île ; le village thermal prend son nom.']],'c','Le village de Hell-Bourg, à Salazie, porte son nom.'],
 ['decaen',1803,'Charles Decaen','Archive','Capitaine général des Mascareignes',[[1803,'Envoyé par Bonaparte, il gouverne les îles en militaire et maintient l’esclavage.'],[1806,'Bourbon devient l’Île Bonaparte.'],[1810,'Il rend l’Île de France aux Anglais après la chute de Bourbon.']],'c'],
 ['villele',1799,'Joseph de Villèle','Archive','Gendre des Desbassayns',[[1799,'Venu de Toulouse, il épouse une fille Desbassayns et siège à l’Assemblée coloniale.'],[1807,'Il rentre en France.'],[1822,'Il devient chef du gouvernement du roi Louis XVIII : un homme de Bourbon à la tête de la France.']],'c','Le musée historique de Villèle garde son nom.'],
 ['kerveguen',1840,'Gabriel de Kerveguen','Archive','Grand planteur sucrier',[[1840,'Ses sucreries du Sud font de lui l’un des hommes les plus riches de l’île.'],[1860,'Il meurt ; son domaine et ses villas restent dans la mémoire du Sud.']],'c'],
 ['sarda',1848,'Sarda Garriga','Archive','Commissaire de la République, figure discutée',[[1848,'Arrivé en octobre avec le décret d’abolition, il attend la fin de la coupe de la canne pour l’appliquer.'],[1849,'Le 20 décembre 1848, il proclame la liberté de plus de 60 000 esclaves. Mais il oblige les affranchis à signer des contrats de travail. Pour les uns, c’est le libérateur ; pour d’autres, il a d’abord protégé les planteurs.'],[1850,'Il est rappelé en France ; les engagés arrivent en nombre.']],'','Son nom est resté sur des rues et des places, et le 20 décembre est la fête de l’abolition.'],
 ['lisle',1840,'Leconte de Lisle','Archive','Poète né à Saint-Paul',[[1840,'Jeune homme de Saint-Paul, il part étudier en France.'],[1852,'Ses Poèmes antiques le font connaître ; il deviendra le maître des poètes parnassiens.']],'','Des lycées portent son nom.'],
 ['garros',1913,'Roland Garros','Archive','Aviateur né à Saint-Denis',[[1913,'Il traverse le premier la Méditerranée en avion.'],[1918,'Pilote de guerre, il meurt au combat.']],'','L’aéroport de l’île porte son nom.'],
 ['verges',1946,'Raymond Vergès','Archive','Député',[[1946,'Avec Léon de Lépervanche, il porte la loi qui fait de l’île un département.'],[1957,'Il meurt ; son fils Paul fondera le Parti communiste réunionnais.']]]];
function gpSaison(){if(!S||S.bac)return;S.gp=S.gp||{};for(const g of GP){const [k,y0,n,tag,r,steps,v]=g;if(S.year<y0)continue;if(v==='c'&&!S.voieC&&k!=='payen')continue;if(v==='m'&&S.voieC)continue;const vu=S.gp[k]||0;const atteints=steps.filter(st=>st[0]<=S.year).length;if(!vu){S.gp[k]=Math.max(1,atteints);gpMontre(g,0,atteints);log('Grand personnage : '+n+', '+r.toLowerCase()+'.')}else if(atteints>vu){S.gp[k]=atteints;log(n+' : '+steps[atteints-1][1])}}}
function gpMontre(g,i,at){const [k,y0,n,tag,r,steps,v,tr]=g;let el=$('gpC');if(!el){el=document.createElement('div');el.id='gpC';document.body.appendChild(el)}el.innerHTML='<small>Grand personnage · '+tag+'</small><b>'+n+'</b><i>'+r+'</i><p>'+(steps[Math.max(0,(at||1)-1)]||steps[0])[1]+'</p>'+(tr?'<p style="font-size:12px;opacity:.75;margin-top:4px">Aujourd’hui : '+tr+'</p>':'');el.className='on';clearTimeout(gpMontre.t);gpMontre.t=setTimeout(()=>el.className='',7000)}
function gpHtml(){const L=GP.filter(g=>S.gp&&S.gp[g[0]]);let h='<h3 style="font-size:17px">Grands personnages</h3>';if(!L.length)h+='<p class="note" style="font-size:14px">Ils apparaîtront au fil de l’histoire.</p>';
 L.forEach(([k,y0,n,tag,r,steps,v,tr])=>{h+='<div class="sv ok" style="display:block"><b>'+n+'</b> <small style="opacity:.75">· '+r+' · '+tag+'</small><small>'+steps.slice(0,S.gp[k]).map(st=>'<b>'+st[0]+'</b> '+st[1]).join('<br>')+(tr?'<br><i>Aujourd’hui : '+tr+'</i>':'')+'</small></div>'});
 const F=(S.pp||[]).filter(p=>adulte(p)&&Math.max(...Object.values(p.sk))>=9).sort((a,b)=>Math.max(...Object.values(b.sk))-Math.max(...Object.values(a.sk))).slice(0,6);
 h+='<h3 style="font-size:17px">Vos grandes figures</h3><p class="note" style="font-size:13px">Les vôtres, devenus légendes dans votre histoire : une fiction qui naît de vos choix.</p>'+(S.roi==='vous'||S.gouv?'<div class="sv ok" style="display:block"><b>Vous</b> <small>· '+titre()+'</small></div>':'')+(F.length?F.map(p=>'<div class="sv" style="display:block"><b>'+p.n+'</b> <small>· '+rolePP(p)+', '+ageP(p)+' ans · '+ORIG[p.or]+'</small></div>').join(''):'<p class="note" style="font-size:13px">Aucune encore : il faut des années de métier.</p>');return h}

// après le film, la carte ne répète pas le récit
Object.keys(EV).filter(k=>/^ep_[a-z]+1$/.test(k)).forEach(k=>{const e=EV[k],d=Object.getOwnPropertyDescriptor(e,'b');const lire=()=>d.get?d.get.call(e):d.value;Object.defineProperty(e,'b',{get(){if(S&&S.filmVu&&S.filmVu[k])return 'Le voyage est fait. Que rapportent vos gens de là-bas ?';return lire()},configurable:true})});

