Object.defineProperty(EV,'vote',{configurable:true,get(){const V=VOTES[(S.ns||0)%VOTES.length],C=courants(),lieux=[...camps().map((t,i)=>'village '+(lieuDe(t)||lieuProche(t)||i+1)),...(S.voieC?VILLES.filter(v=>S.towns.includes(v[3])).map(v=>'ville de '+v[3]):[])];const res=V.o.map(o=>C[o[1]].p+Math.round((rnd()-.5)*12));const tot=res.reduce((s,x)=>s+Math.max(1,x),0);const pc=res.map(x=>Math.round(Math.max(1,x)*100/tot));const gagne=pc[0]>=pc[1]?0:1;
 return {sys:1,tag:'Vote',an:String(S.year),t:'Vote : '+V.t,b:'Votent : '+lieux.slice(0,6).join(', ')+'. Résultat : '+V.o.map((o,i)=>o[0]+' '+pc[i]+' %').join(' · ')+'. Le camp suit la majorité ; vous pouvez peser de tout votre poids, mais cela coûte.',o:[{n:'Suivre la majorité : '+V.o[gagne][0],d:'Cohésion +2.',fx:Object.assign({},V.o[gagne][2],{coh:(V.o[gagne][2].coh||0)+2})},{n:'Imposer l’autre choix : '+V.o[1-gagne][0],d:'Cohésion −8 : la minorité gouverne.',fx:Object.assign({},V.o[1-gagne][2],{coh:(V.o[1-gagne][2].coh||0)-8})}]}}});

