{const a0=actions;actions=function(t){const A=a0(t);if(S&&S.sv&&(S.sv.sirenes||S.sv.suvanna)&&cotier(t)&&!A.find(a=>a.id==='plonge'))A.push({id:'plonge',n:'Plonger avec le chant des sirènes',c:1,d:'Pêche sous-marine : coraux, langoustes, tortues. Les sirènes demandent une vérité sur ce que vous prenez à la mer.'});return A}}
