function regHtml(k){const R=REG[k]||[['Le port','Le mouillage et ses marchands.','col',[50,50],'duel'],['L’intérieur','Les gens du pays.','for',[30,30],'bat'],['La côte','Pêcheurs et marins.','pec',[70,70],'cmd:morne']],c=cpInit(k);c.as=c.as||{};const n=Object.keys(c.as).length;
 return '<h4>La région</h4><p class="note" style="font-size:13px">Ici, on ne fonde pas de village : on s’associe aux communautés. À deux associations, le comptoir devient actif : des Réunionnais y vivent et y font leur vie. Chaque communauté a son épreuve, un petit jeu.</p><svg viewBox="0 0 100 100" width="100%" style="max-width:340px;background:#163038;display:block;margin:6px 0"><path d="M10,50 C10,20 40,6 60,10 C85,15 95,40 90,62 C85,88 55,96 35,92 C15,86 10,70 10,50Z" fill="#4a6342" stroke="#e2bd74" stroke-opacity=".3"/>'+R.map(([nm,,ty,[px,py]],i)=>'<g data-rg="'+i+'" style="cursor:pointer"><circle cx="'+px+'" cy="'+py+'" r="4.5" fill="'+(c.as[i]?'#e2bd74':'#8a9a90')+'" stroke="#111"/><text x="'+px+'" y="'+(py-6)+'" font-size="5" fill="#f3efe2" text-anchor="middle">'+nm+'</text></g>').join('')+'</svg>'
 +'<p style="font-size:14px">'+(c.actif?'<b style="color:var(--vacoa)">Comptoir actif</b> : '+(c.reu||0)+' Réunionnais y vivent. ':'Associations : '+n+' / 2. ')+'</p><div id="rgI" class="sv" style="display:block"><small>Touchez une communauté sur la carte.</small></div>'}
