{const o0=cpOuvrir;cpOuvrir=function(k){o0(k);const d=$('drawer');if(!d||typeof REG==='undefined')return;const div=document.createElement('div');div.innerHTML=regHtml(k);d.appendChild(div);const R=REG[k]||[['Le port','Le mouillage et ses marchands.','col',[50,50],'duel'],['L’intérieur','Les gens du pays.','for',[30,30],'bat'],['La côte','Pêcheurs et marins.','pec',[70,70],'cmd:morne']];
 div.querySelectorAll('[data-rg]').forEach(z=>z.onclick=()=>{const i=+z.dataset.rg,g=R[i],c=cpInit(k),box=div.querySelector('#rgI');const J={cmd:'une infiltration',ech:'une bataille aux échecs',bat:'une bataille rangée',lab:'une descente au labyrinthe',duel:'un duel'}[g[4].split(':')[0]];box.innerHTML='<b>'+g[0]+'</b><br><small>'+g[1]+'</small><br>'+(c.as[i]?'<small>Associés depuis '+c.as[i]+'.</small>':'<button class="bt" id="rgA">S’associer : '+J+'</button>');const b=box.querySelector('#rgA');if(b)b.onclick=()=>regAssoc(k,i)})}}
