{const s0=cpSaison;cpSaison=function(){s0();if(!S||!S.cp)return;for(const k in S.cp){const c=S.cp[k];if(!c.actif)continue;if(rnd()<.25&&c.reu<c.gens)c.reu++;fx({vivres:1+Math.floor((c.reu||0)/3)});if(rnd()<.04)log(['À '+OUT[k].n+', un enfant réunionnais naît dans la communauté associée.','À '+OUT[k].n+', une fête mêle les chants de l’île et ceux du pays.','À '+OUT[k].n+', un mariage unit une famille réunionnaise à une famille du pays.'][Math.floor(rnd()*3)])}}}

