{const cc0=choixConte;choixConte=function(e,id){if(!S||S.conteVers!=='uto')return cc0(e,id);const O=id?optsDe(id,e):e.o;const L=O.map((o,k)=>[k,(o.hist||k===(e.hist||0))?0:1+rnd()]);L.sort((a,b)=>b[1]-a[1]);return L[0][0]}}
