const SKN={cha:'chasseurs',cue:'cueilleurs',exp:'éclaireurs',gue:'guerriers',art:'artisans',mys:'mystiques'};
function grpCarac(g){const M=grpMembres(g),c={cha:0,cue:0,exp:0,gue:0,art:0,mys:0};M.forEach(p=>{for(const k in c)c[k]+=(p.sk&&p.sk[k])||0});for(const k in c)c[k]=M.length?c[k]/M.length:0;const best=Object.keys(c).sort((a,b)=>c[b]-c[a])[0];return {c,best,type:SKN[best]}}
function grpEff(g,id){const k=SKACT[id];if(!k)return 1;const C=grpCarac(g).c;return Math.max(.5,Math.min(1.6,.6+C[k]/8))}
// le choix du groupe montre son talent et son efficacité ; l'action rapporte selon ce talent, et le groupe fait aussi ce qu'il sait faire en passant
{const gc=grpChoisir;grpChoisir=function(t,a,go){gc(t,a,()=>{const g=S.grp.find(q=>q.pos===t.i&&q.fait&&q.dern!==S.ns);if(g){g.dern=S.ns;const e=grpEff(g,a.id),K=grpCarac(g);
  if(['chasse','cueil','peche','pecheM','recolte','jardin'].includes(a.id)){const d=Math.round((e-1)*4);if(d)fx({vivres:d});if(d<0)log(g.n+' ('+K.type+') s’y prend moins bien : vivres '+d+'.');else if(d>0)log(g.n+' ('+K.type+') excelle : vivres +'+d+'.')}
  // ce qu'ils savent faire en passant
  if(K.best==='cha'&&t.riv&&!['peche','pecheM'].includes(a.id)){fx({vivres:2});log(g.n+' pêche aussi dans la rivière en passant : vivres +2.')}
  else if(K.best==='cha'&&t.forest&&a.id!=='chasse'){fx({vivres:2});log(g.n+' tend quelques collets en passant : vivres +2.')}
  else if(K.best==='cue'&&t.forest&&a.id!=='cueil'){fx({vivres:1,sante:1});log(g.n+' ramasse des plantes en passant.')}
  else if(K.best==='exp'){const c=T[g.pos];const R=T.filter(u=>hd(u,c)<=2&&!(S.t[u.i]||{}).s);R.forEach(u=>{const o=tl(u.i);o.s=1;o.p=1});const sp=T.filter(u=>hd(u,c)<=2&&resIcone(u)).map(u=>(lieuDe(u)||lieuProche(u)||'')+' : '+ressource(u)).slice(0,2);if(R.length)log(g.n+' reconnaît les lieux autour'+(sp.length?' — '+sp.join(' ; '):'')+'.')}
  // se battre ou partir loin rend mystique
  if(['embuscade','descente','course','lever','detache'].includes(a.id)){grpMembres(g).forEach(p=>{p.sk.mys=(p.sk.mys||0)+1;if(!p.mag&&rnd()<.12){p.mag=1;log(p.n+' revient du combat changé : il voit ce que les autres ne voient pas.')}})}
  grpMembres(g).forEach(p=>{const k=SKACT[a.id];if(k)p.sk[k]=(p.sk[k]||0)+.5})}
  go()});const box=document.getElementById('grpC');if(box)box.querySelectorAll('[data-g]').forEach((b,i)=>{const g=S.grp[i];if(!g)return;const K=grpCarac(g),e=grpEff(g,a.id);const s=b.querySelector('small');if(s)s.textContent+=' · '+K.type+' · efficacité '+Math.round(e*100)+' %'})}}
// les qualités d'un lieu pour s'y installer
function qualites(t){const L=[];const eau=t.riv||t.nb.some(i=>T[i].riv);if(eau)L.push(['eau','Près de l’eau : santé +1 par saison pour un camp']);if(actions(t).some(a=>a.id==='tunnel'||a.id==='cristal')||volc(t))L.push(['sous','Ressource sous terre : tunnels, cristaux']);
 const est=t.nb.map(i=>T[i]).filter(u=>u.x>t.x);const abri=t.forest&&t.slope>8||est.some(u=>u.alt>t.alt+60);if(abri)L.push(['abri','À l’abri du vent : les cyclones y font moins de dégâts']);
 const crete=!t.nb.some(i=>T[i].alt>t.alt+20)&&t.alt>300;if(crete)L.push(['expo','Exposé, sur une crête : on y voit loin. Bon pour se protéger au début, idéal pour une tour de guet'])
 return L}
