function resIcone(t){const o=S.t[t.i]||{};if(o.c||o.b)return null;if(t.riv&&t.alt<400)return '🐟';if(cotier(t))return '🐚';if(volc(t))return '🌿';if(actions(t).some(a=>a.id==='cristal'))return '💎';{const h=typeof trpIci==='function'&&trpIci(t);if(h)return h.k==='cochon'?'🐗':h.k==='boeuf'?'🐂':'🐐'}if(t.riv)return '💧';return null}
let RESI=[],RESMAT={};function resMat(ic){if(RESMAT[ic])return RESMAT[ic];const c=document.createElement('canvas');c.width=c.height=64;const x=c.getContext('2d');x.font='46px serif';x.textAlign='center';x.textBaseline='middle';x.fillText(ic,32,36);const m=new THREE.SpriteMaterial({map:new THREE.CanvasTexture(c),transparent:true,depthTest:false});return RESMAT[ic]=m}
