EV.ameriq={sys:1,tag:'Monde',an:'',nat:'Les cigares de Cuba et le kinnikinnick, mélange à fumer des peuples d’Amérique du Nord, ont bien voyagé avec les marins ; leur effet ici est inventé.',t:'La fumée des Amériques',b:'Un capitaine venu des Antilles laisse à votre table des cigares de Cuba et un sac d’écorces et de feuilles mêlées, que les peuples du nord de l’Amérique fument pour parler aux esprits. Il dit qu’un chaman le lui a donné.',
 o:[{n:'Essayer, en secret',d:'Un savoir des chamans : mystique +1 par saison. On le range dans un coffre de la maison.',fx:{},f:()=>{S.sv.chamane=1;S.coffre=1}},{n:'Le vendre',d:'Vivres +4.',fx:{vivres:4}}]};
{const B0=EV.butinC;if(B0&&B0.o)B0.o.push({n:'Le coffre de la grande maison',d:'On dit qu’un planteur garde dans un coffre des feuilles venues des Amériques. Gardé : risque d’y laisser quelqu’un.',fx:{traque:5},f:()=>{if(rnd()<.45){S.sv.chamane=1;log('Dans le coffre : des cigares et un sac de feuilles des Amériques. Un savoir des chamans passe aux marrons.')}else log('Le coffre était vide, ou bien gardé.');if(rnd()<.2){fx({gens:-1});log('Le gardien du coffre a pris l’un des vôtres.')}}})}
