const abriT=t=>{const o=S.t[t.i]||{};return o.b==='camp'||o.b==='tunnel'||o.b==='guet'||tunnelL(t)||(S.grotteI||[]).includes(t.i)};
const refuges=()=>(S.grotte||0)*6+T.filter(t=>S.t[t.i]&&S.t[t.i].b==='tunnel').length*6;
const abriCap=()=>cap()+refuges();
function abriMort(p,pourquoi){const i=S.pp?S.pp.indexOf(p):-1;if(i>=0)S.pp.splice(i,1);S.gens=Math.max(0,S.gens-1);(S.morts=S.morts||[]).push({n:p?p.n:'?',a:S.year,age:p?ageP(p):0});if(S.morts.length>40)S.morts.shift();if(S.grp)S.grp.forEach(g=>{g.m=g.m.filter(id=>!p||id!==p.id)});log((p?p.n:'Une personne')+' meurt '+pourquoi+'.')}
function abriSaison(){if(!S||S.fin||S.bac||!camps().length)return;const pl=pluie(),C=S.voieC;
 // 1. les gens sans toit
 const dehors=Math.max(0,S.gens-abriCap());
 if(dehors>0){const mal=Math.min(8,(1+dehors*.35)*(pl?2:1));fx({sante:-mal,coh:-(pl?1.5:.5)});
  const qui=C?(S.year<abolY()?'serviteurs et engagés':'travailleurs'):'personnes';
  log(dehors+' '+qui+' dorment dehors, faute de '+(C?'cases':'cases ou de grotte')+(pl?' : la pluie les rend malades':' : on tousse, on a froid la nuit')+'. Bâtissez des cases.');
  const pm=pl?.07:.015;let n=0;const cand=(S.pp||[]).filter(p=>!(S.grp||[]).some(g=>g.m.includes(p.id)));for(let k=0;k<dehors&&n<3;k++)if(rnd()<pm*(S.sante<40?1.6:1)){const p=cand.length?cand.splice(Math.floor(rnd()*cand.length),1)[0]:null;abriMort(p,pl?'de fièvre, après des nuits sous la pluie sans abri':'de froid, sans abri');n++}
  if(pl&&!S.done.abriTuto){S.done.abriTuto=1;if(typeof toast==='function')toast('Il pleut et des gens dorment dehors : bâtissez des cases, ou trouvez une grotte.')}}
 // 2. les groupes dehors sous la pluie
 if(S.grp&&grpOn())S.grp.forEach(g=>{if(g.pos==null)return;const t=T[g.pos];if(!t)return;const loin=Math.min(...camps().map(c=>hd(c,t)));
  if(!pl||loin<=1||abriT(t)){g.mo=0;return}
  g.mo=(g.mo||0)+1;const M=grpMembres(g);fx({sante:-(g.mo>1?2:1)});
  const pm=(g.mo>1?.12:.04)*(M.some(p=>p.role==='mys')?.4:1);if(M.length&&rnd()<pm*(t.cold?1.5:1)){const p=M[Math.floor(rnd()*M.length)];abriMort(p,'sous la pluie, loin '+(C?'de l’habitation':'du camp')+', avec '+g.n)}
  else log(g.n+' passe la saison des pluies dehors, à '+loin+' cases '+(C?'de l’habitation':'du camp')+(g.mo>1?' : la fièvre gagne le groupe':'')+'. Ramenez-le sous un abri : '+(C?'l’habitation, un poste ou une grotte':'le camp, une grotte, un tunnel ou un poste de guet')+'.')})}
