{const g=EV.grotte;if(g&&g.o&&g.o[0]){g.o[0].d='Traque -6, Anciens +2, 6 places à l’abri';const f0=g.o[0].f;g.o[0].f=function(){if(f0)f0.apply(this,arguments);S.grotte=(S.grotte||0)+1;if(sel){(S.grotteI=S.grotteI||[]).push(sel.i)}}}}

// ===== Mode Normal : les rôles du camp. Au départ le camp n'est qu'un camp ; on forme ses gens, l'un reste, les autres sortent =====
const ROLES={cha:{n:'Chasseur',nc:'Chasseur de l’habitation',ic:'🗡️',d:'Chasse, et se bat au sabre.',dc:'Chasse, et se bat au sabre et au fusil.',sk:'cha',f:3},
 cue:{n:'Cueilleur',nc:'Planteur',ic:'🎯',d:'Cueille et ramasse ; se bat aussi, et lance la sagaie de loin.',dc:'Fait pousser et ramasse ; se bat aussi, et tire de loin.',sk:'cue',f:2},
 mys:{n:'Mystique guérisseur',nc:'Cuisinière soignante',ic:'🍲',d:'Guérit les malades et fait la cuisine : la vie du camp s’améliore.',dc:'Soigne et fait la cuisine : la vie de la maison s’améliore.',sk:'mys',f:0}};
const roleN=k=>S.voieC?ROLES[k].nc:ROLES[k].n;
const enGrp=p=>(S.grp||[]).some(g=>g.m.includes(p.id));
const roleL=k=>(S.pp||[]).filter(p=>adulte(p)&&p.role===k);
function grpForce(g){return grpMembres(g).reduce((s,p)=>s+((ROLES[p.role]||{}).f||0),0)}
function former(k){const L=(S.pp||[]).filter(p=>adulte(p)&&!p.role&&p.id!==S.garde).sort((a,b)=>((b.sk||{})[ROLES[k].sk]||0)-((a.sk||{})[ROLES[k].sk]||0));if(!L.length){toast('Plus personne de libre à former.');return}if(S.bras<1){toast(raisonBras(1));return}if(k==='cha'&&!peut({bois:1})){toast('Il manque 1 bois pour la lame.');return}
 snap();S.bras--;if(k==='cha')paye({bois:1});const p=L[0];p.role=k;p.sk=p.sk||{};p.sk[ROLES[k].sk]=(p.sk[ROLES[k].sk]||0)+2;if(k!=='mys')p.sk.gue=(p.sk.gue||0)+1;
 log(p.n+' devient '+roleN(k).toLowerCase()+'. '+(S.voieC?ROLES[k].dc:ROLES[k].d));sauve();panneau();rafraichir()}
const GCOL=[0x5a8ad0,0xd07a9a,0x7ac07a,0xd0a040];
function composer(){const c=camps()[0];if(!c)return;if(S.grp.length>=3){toast('Trois groupes au plus.');return}
 const L=(S.pp||[]).filter(p=>adulte(p)&&p.role&&!enGrp(p)&&p.id!==S.garde);if(L.length<1){toast('Formez d’abord des gens : un groupe ne part qu’avec des gens formés, et l’un reste au camp.');return}
 const box=document.createElement('div');box.id='grpC';box.innerHTML='<div class="pjb"><small>'+(S.voieC?'L’habitation':'Le camp')+'</small><h2>Composer un groupe de sortie</h2><p class="note">'+(S.garde&&ppId(S.garde)?ppId(S.garde).n+' reste '+(S.voieC?'à l’habitation':'au camp')+'.':'<b style="color:#ff8a7a">Personne ne reste : choisissez d’abord un garde.</b>')+' Les autres peuvent sortir.</p>'+L.map(p=>'<label style="display:block;margin:4px 0"><input type="checkbox" data-c="'+p.id+'"> '+ROLES[p.role].ic+' '+p.n+' · '+roleN(p.role)+'</label>').join('')+'<div style="display:flex;gap:10px;justify-content:flex-end;margin-top:10px"><button class="bt sec" id="grpN">Annuler</button><button class="bt" id="grpOk">Former le groupe</button></div></div>';document.body.appendChild(box);
 box.querySelector('#grpN').onclick=()=>box.remove();box.querySelector('#grpOk').onclick=()=>{const ids=[...box.querySelectorAll('[data-c]:checked')].map(x=>+x.dataset.c);if(!ids.length){toast('Cochez au moins une personne.');return}box.remove();const p0=ppId(ids[0]);const g={n:'Le groupe de '+(p0?p0.n.split(' ')[0]:'?'),m:ids,col:GCOL[S.grp.length%4],id:S.grp.length,pos:c.i,fait:0,xp:0,tour:0,mv:0};g.mv=grpPortee(g);S.grp.push(g);log(g.n+' est formé : '+ids.map(i=>{const q=ppId(i);return q?ROLES[q.role].ic+' '+q.n.split(' ')[0]:''}).join(', ')+'.');sauve();grpDessin();panneau()}}
function dissoudre(i){const g=S.grp[i];if(!g)return;const c=camps()[0];if(c&&g.pos!=null&&hd(T[g.pos],c)>1){toast('Le groupe doit d’abord rentrer.');return}S.grp.splice(i,1);S.grp.forEach((q,j)=>q.id=j);log(g.n+' rentre et se défait.');sauve();grpDessin();panneau()}
function choisirGarde(){const L=(S.pp||[]).filter(p=>adulte(p)&&!enGrp(p));if(!L.length)return;const box=document.createElement('div');box.id='grpC';box.innerHTML='<div class="pjb"><h2>Qui reste ?</h2>'+L.map(p=>'<button class="act" data-gd="'+p.id+'"><b>'+(p.role?ROLES[p.role].ic+' ':'')+p.n+'</b><small>'+(p.role?roleN(p.role):'sans rôle')+'</small></button>').join('')+'<button class="bt sec" id="grpN">Annuler</button></div>';document.body.appendChild(box);box.querySelector('#grpN').onclick=()=>box.remove();box.querySelectorAll('[data-gd]').forEach(b=>b.onclick=()=>{S.garde=+b.dataset.gd;box.remove();log(ppId(S.garde).n+' reste '+(S.voieC?'à l’habitation.':'au camp.'));sauve();panneau()})}
// le panneau du camp : les rôles, le garde, les groupes
{const p1=panneau;panneau=function(){p1();if(!S||!grpOn()||!sel||!S.grp||true)return;const o=S.t[sel.i]||{};if(o.b!=='camp'||sel.i!==(camps()[0]||{}).i)return;const p=$('side');const div=document.createElement('div');div.className='sub';div.style.marginTop='8px';
 const libres=(S.pp||[]).filter(p=>adulte(p)&&!p.role&&p.id!==S.garde).length,gd=S.garde&&ppId(S.garde);
 div.innerHTML='<b>'+(S.voieC?'Les gens de l’habitation':'Les gens du camp')+'</b><br><small>Reste '+(S.voieC?'à l’habitation':'au camp')+' : '+(gd?gd.n:'<b style="color:#ff8a7a">personne !</b>')+' · '+libres+' sans rôle</small><br>'+Object.keys(ROLES).map(k=>'<small>'+ROLES[k].ic+' '+roleN(k)+' : '+roleL(k).length+'</small>').join(' · ')+
  '<div class="acts" style="margin-top:6px">'+Object.keys(ROLES).map(k=>'<button class="bt sec" data-fo="'+k+'" title="'+(S.voieC?ROLES[k].dc:ROLES[k].d)+'"'+(libres&&S.bras>=1?'':' disabled')+'>Former : '+roleN(k)+'</button>').join('')+'<button class="bt sec" id="gdCh">Qui reste ?</button><button class="bt" id="grpNew"'+(S.grp.length>=3?' disabled':'')+'>Composer un groupe</button></div>'+
  (S.grp.length?S.grp.map((g,i)=>'<small>'+g.n+' · force '+grpForce(g)+' · '+grpMembres(g).map(q=>(ROLES[q.role]||{}).ic||'').join('')+'</small> <button class="bt sec" data-ds="'+i+'">Rentrer et défaire</button>').join('<br>'):'');
 p.insertBefore(div,p.children[1]||null);div.querySelectorAll('[data-fo]').forEach(b=>b.onclick=()=>former(b.dataset.fo));div.querySelector('#grpNew').onclick=composer;div.querySelector('#gdCh').onclick=choisirGarde;div.querySelectorAll('[data-ds]').forEach(b=>b.onclick=()=>dissoudre(+b.dataset.ds))}}
// cuisine et soins : un mystique resté au camp améliore la vie ; le foyer double l'effet
BAT.foyer={n:'Foyer de cuisine',c:{bois:2,pierre:1},d:'Un foyer couvert : la cuisine du mystique nourrit mieux et soigne plus.',col:0x6a4a3a,h:.12};
Object.defineProperty(BAT.foyer,'n',{get:()=>S&&S.voieC?'Cuisine de l’habitation':'Foyer de cuisine'});
{const gs4=grpSaison;grpSaison=function(){gs4();if(!grpOn()||!S.grp)return;const c=camps()[0];if(!c)return;const M=roleL('mys').filter(p=>{const g=(S.grp||[]).find(g=>g.m.includes(p.id));return !g||g.pos==null||hd(T[g.pos],c)<=1});if(M.length){const k=nBat('foyer')?1.5:1;fx({sante:Math.min(3,M.length)*k,coh:.5*k,vivres:Math.round(M.length*k)});if(!S.done.cuis1){S.done.cuis1=1;log(M[0].n+(S.voieC?' tient la cuisine : on mange mieux, on soigne les fièvres.':' fait la cuisine et soigne : on mange mieux au camp, les fièvres reculent.'))}}
 // les combattants restés au camp aident le garde contre une attaque
 if(S.detG&&hd(T[S.detG.i],c)<=2){const f=(S.pp||[]).filter(p=>adulte(p)&&(p.role==='cha'||p.role==='cue')&&!enGrp(p)).length;if(f>=2){fx({traque:-4});log(f+' combattants attendent au camp, '+(S.voieC?'sabres et fusils':'sabres et sagaies')+' prêts : '+(S.voieC?'la bande':'le détachement')+' hésite.');S.detG=null}}}}
