{const gc5=grpChoisir;grpChoisir=function(t,a,go){gc5(t,a,go);if(a.k!=='dan')return;const box=document.getElementById('grpC');if(box)box.querySelectorAll('[data-g]').forEach((b,i)=>{const g=S.grp[i];if(g&&!grpForce(g)){b.disabled=true;const s=b.querySelector('small');if(s)s.textContent+=' · aucun combattant'}})}}
