// ===== Mode Normal, côté colonie : la maison vit seule. Les gens de maison font la cuisine, le linge, et colportent les nouvelles =====
const SERVN=['Marie-Rose','Fanchon','Zabeth','Célestine','Lindor','Pierrot','Coco','Jean-Louis','Rosette','Bastien'];
const VOIS=['Ferrand','Morel du Bois','Lantier','Vauclin','Desrives','Castaing'];
const SERVF=['Marie-Rose','Fanchon','Zabeth','Célestine','Rosette'],SERVH=['Lindor','Pierrot','Coco','Jean-Louis','Bastien'];
function maisonInit(){if(S.serv&&!S.serv.some(s=>s.r!=='cocher'&&SERVH.includes(s.n)))return;const F=SERVF.slice().sort(()=>rnd()-.5),H=SERVH.slice().sort(()=>rnd()-.5);S.serv=[{n:F[0],r:'cuisinière'},{n:F[1],r:'blanchisseuse'},{n:H[0],r:'cocher'},{n:F[2],r:'nénène des enfants'}]}
const GOSS=[
 (s,v)=>({m:s.n+', '+s.r+', revient du lavoir : chez les '+v+', la maîtresse ne parle plus au maître depuis la Noël. On dit qu’une lettre est arrivée de France.',fx:{coh:.5}}),
 (s,v)=>({m:'Au marché, '+s.n+' a entendu que les '+v+' ont perdu trois serviteurs partis dans les Hauts en une seule nuit.',fx:{traque:2}}),
 (s,v)=>({m:s.n+' raconte à l’office que les '+v+' doivent de l’argent à tout le quartier, et qu’ils vendent leur argenterie en cachette.',fx:{ami:1}}),
 (s,v)=>({m:'Le cocher des '+v+' et '+s.n+' se sont parlé au carrefour : un navire chargé de vin et de toiles est annoncé.',fx:{vivres:2}}),
 (s)=>({m:s.n+' a une cousine qui travaille dans un de vos quartiers : les cases y prennent l’eau, et on y murmure contre le commandeur.',fx:{coh:-1}}),
 (s)=>({m:'Un colporteur s’arrête à la cuisine. '+s.n+' lui donne à manger, et il raconte tout ce qu’il a vu sur la route des quartiers.',fx:{savoir:.5}}),
 (s)=>{const l=T.filter(u=>u.alt>700&&!(S.t[u.i]||{}).s).sort(()=>rnd()-.5)[0];if(l){const o=tl(l.i);o.s=1;o.p=1}return {m:s.n+' tient de quelqu’un qui tient de quelqu’un qu’un camp de marrons fume, la nuit, '+(l?'du côté de '+(lieuDe(l)||lieuProche(l)||'la montagne'):'dans la montagne')+'.',fx:{}}},
 (s)=>({m:'La nuit, '+s.n+' monte porter du riz à quelqu’un, au bord de la ravine. Le lendemain, les chiens aboient vers les Hauts. Personne n’a rien vu.',fx:{vivres:-2,traque:-1}}),
 (s)=>({m:'Les marrons, dit '+s.n+', ont leurs chants à eux, et leurs tambours répondent à ceux des cases. On les entend quand le vent tourne.',fx:{myst:1}}),
 (s)=>({m:s.n+' a vu le fils de la maison parler longtemps, à la lisière, avec une jeune femme des cases. Tout l’office le sait déjà.',fx:{coh:-.5}}),
 (s,v)=>({m:'On marie la fille des '+v+'. '+s.n+' et les autres gens de maison préparent le repas : trois jours de cuisine, et des histoires pour un an.',fx:{ami:1,coh:.5}}),
 (s)=>({m:'Chez vous, '+s.n+' raconte aux enfants l’histoire du loup et du lièvre, comme on la dit là-bas, de l’autre côté de la mer.',fx:{coh:.5}})];
function maisonSaison(){if(!S||!S.voieC||modeHist()||S.bac||!camps().length)return;maisonInit();
 // la vie de la maison : la cuisine, le ménage, le linge, sans qu'on donne d'ordre
 fx({vivres:1,coh:.3});
 const n=rnd()<.5?2:1;for(let k=0;k<n;k++){const s=S.serv[Math.floor(rnd()*S.serv.length)],v=VOIS[Math.floor(rnd()*VOIS.length)];const g=GOSS[Math.floor(rnd()*GOSS.length)](s,v);log('Commérage · '+g.m);if(g.fx){const f={...g.fx};if(f.myst){S.myst=(S.myst||0)+f.myst;delete f.myst}if(f.savoir){S.savoir=(S.savoir||0)+f.savoir;delete f.savoir}fx(f)}}
 // parfois, l'un d'eux part rejoindre les marrons
 if(S.year<abolY()&&rnd()<.03){const i=Math.floor(rnd()*S.serv.length),s=S.serv[i],h=s.r==='cocher';log(s.n+' n’est pas revenu'+(h?'':'e')+' '+(h?'de la route':'du lavoir')+'. On dit qu’'+(h?'il':'elle')+' a pris le sentier des Hauts.');const L=(h?SERVH:SERVF).filter(x=>!S.serv.some(q=>q.n===x));S.serv[i]={n:L[0]||(h?'Lindor':'Rosette'),r:s.r};fx({traque:3})}}
{const gs6=grpSaison;grpSaison=function(){gs6();maisonSaison()}}
// la maison et ses gens dans le panneau de l'habitation
{const p6=panneau;panneau=function(){p6();if(!S||!S.voieC||modeHist()||!sel||!S.serv)return;const o=S.t[sel.i]||{};if(o.b!=='camp'||sel.i!==(camps()[0]||{}).i)return;const d=document.createElement('div');d.className='sub';d.style.marginTop='8px';const last=(S.log||[]).find(l=>/^Commérage/.test(l.m));d.innerHTML='<b>Les gens de maison</b><br><small>'+S.serv.map(s=>s.n+' ('+s.r+')').join(', ')+'</small>'+(last?'<br><small><i>'+last.m.replace('Commérage · ','')+'</i></small>':'');$('side').appendChild(d)}}

// ===== Mode Normal : au départ, un camp et ses gens, aucun groupe formé =====
grpInit=function(){if(!grpOn()||S.grp)return;S.grp=[];S.roleP={};const ad=(S.pp||[]).filter(adulte).sort((a,b)=>ageP(b)-ageP(a));if(ad[0])S.garde=ad[0].id;log(S.voieC?'L’habitation n’est encore qu’une habitation. Ouvrez « La vie de l’habitation » : formez vos gens, faites-les monter en grade, puis envoyez-les dehors.':'Le camp n’est encore qu’un camp. Ouvrez « La vie du camp » : formez vos gens, faites-les monter en grade, puis envoyez-les dehors.')};

// ===== Statuts et expérience =====
const STATN={cha:[['Chasseur','Guerrier au sabre','Chef de guerre'],['Chasseur','Milicien','Capitaine de milice']],cue:[['Cueilleur','Lanceur de sagaie','Maître lanceur'],['Planteur','Commandeur','Géreur']],mys:[['Mystique guérisseur','Tisaneur des esprits','Gardien des rites'],['Cuisinière soignante','Cuisinière en chef','Matrone de l’habitation']]};
const XPN=[4,10];
let statut=p=>p.role?STATN[p.role][S.voieC?1:0][p.niv||0]:'Sans rôle';
function monter(p){const n=p.niv||0;if(n>=2||(p.xp||0)<XPN[n])return;snap();p.niv=n+1;p.sk[ROLES[p.role].sk]=(p.sk[ROLES[p.role].sk]||0)+2;log(p.n+' devient '+statut(p).toLowerCase()+'.');sauve();cvListe();if(sel)panneau()}
{const gf=grpForce;grpForce=function(g){return grpMembres(g).reduce((s,p)=>s+(p.role&&p.role!=='mys'?((ROLES[p.role].f)+(p.niv||0)*2):0),0)}}
function campDe(p){const cs=camps();if(!cs.length)return null;if(p.camp==null||!cs.some(c=>c.i===p.camp))p.camp=cs[0].i;return p.camp}
{const gs7=grpSaison;grpSaison=function(){gs7();if(!grpOn())return;S.saisonN=(S.saisonN||0)+1;(S.pp||[]).filter(adulte).forEach(p=>{if(!p.role)return;p.xp=(p.xp||0)+(enGrp(p)?2:1)});
 // un mystique monté en grade cuisine mieux
 const bonus=roleL('mys').reduce((s,p)=>s+(p.niv||0)*.5,0);if(bonus)fx({sante:bonus})}}
// un groupe qui fonde un camp y reste : ses gens deviennent les gens de ce camp
{const ag8=agir;agir=function(t,id,l){const r=ag8(t,id,l);if(r&&id==='camp'&&grpOn()&&S.grp){const i=S.grp.findIndex(g=>g.pos===t.i);if(i>=0){const g=S.grp[i];grpMembres(g).forEach(p=>p.camp=t.i);S.grp.splice(i,1);S.grp.forEach((q,j)=>q.id=j);log(g.n+' s’installe : '+(S.voieC?'une nouvelle habitation':'un nouveau camp')+' vit désormais à '+(lieuDe(t)||lieuProche(t)||'cet endroit')+'.');grpDessin()}}return r}}
function envoyer(p){const c=campDe(p);if(c==null)return;if(p.id===S.garde){toast(p.n+' reste : choisissez d’abord quelqu’un d’autre pour garder.');return}if(!p.role){toast('Formez d’abord '+p.n.split(' ')[0]+'.');return}if(enGrp(p))return;
 let g=S.grp.find(g=>g.pos===c&&g.m.length<4);if(!g){if(S.grp.length>=4){toast('Quatre groupes dehors au plus.');return}g={n:'Le groupe de '+p.n.split(' ')[0],m:[],col:GCOL[S.grp.length%4],id:S.grp.length,pos:c,fait:0,xp:0,tour:0,mv:0};S.grp.push(g)}
 g.m.push(p.id);g.mv=grpPortee(g);log(p.n+' rejoint '+g.n.replace(/^Le /,'le ')+'.');sauve();grpDessin();cvListe()}

