const CVCOL={cha:'#b5523a',cue:'#5a9a4a',mys:'#8a5ac0',x:'#c9b48a',g:'#4a74b8'};
const DITS={cha:['La lame est bien affûtée.','Des traces de cochon, vers la ravine.','Je sors au lever du jour.'],cue:['Les brèdes ont poussé.','Trois sagaies neuves.','Il faudra de l’eau pour le jardin.'],mys:['Qui a de la fièvre ?','Le cari est presque prêt.','Les ancêtres sont tranquilles ce soir.'],x:['Encore du bois à porter…','Il va pleuvoir, sens le vent.','On raconte des choses, en bas.'],g:['Rien sur le sentier.','J’ai vu une fumée au loin.','Personne ne passe sans que je le voie.']};
