// ===== Chaque personne a ses statistiques : force, agilité, endurance, ferveur. Elles montent par le travail et par le mystique =====
const STK={for:'Force',agi:'Agilité',end:'Endurance',fer:'Ferveur'};
const apres89=()=>S&&S.year>=1789;
