function stP(p){if(!p.stx){const v=k=>2+((p.id*[7,13,17,23][k]+k*5+(p.fa||0))%6);p.stx={for:v(0),agi:v(1),end:v(2),fer:v(3)};if(p.g==='h')p.stx.for+=1;else p.stx.end+=1}return p.stx}
const stM=(L,k)=>L.length?L.reduce((s,p)=>s+stP(p)[k],0)/L.length:0;
const chanceP=L=>(stM(L,'fer')-5)*.04;// fervent : plus de chance ; peu fervent : moins
function stGagne(p,k,v){const s=stP(p);s[k]=Math.min(10,Math.round((s[k]+v)*100)/100)}
// travail et mystique, chaque saison
{const gs13=grpSaison;grpSaison=function(){gs13();if(!grpOn())return;const myst=(S.myst||0)>20;(S.pp||[]).filter(adulte).forEach(p=>{stP(p);if(p.role==='cha')stGagne(p,'for',.2);if(p.role==='cue')stGagne(p,'agi',.2);if(p.role==='mys')stGagne(p,'fer',.25);if(enGrp(p)){stGagne(p,'end',.15);stGagne(p,'agi',.1)}if(myst)stGagne(p,'fer',.05);if(roleL('mys').some(q=>!enGrp(q)&&campDe(q)===campDe(p))&&!enGrp(p))stGagne(p,'fer',.05);
  // les blessures guérissent, plus vite auprès d'un guérisseur
  if(p.bl){p.blT=(p.blT||2)-(roleL('mys').some(q=>!enGrp(q))&&!enGrp(p)?2:1);if(p.blT<=0){log(p.n+' est guéri'+(p.g==='f'?'e':'')+'.');p.bl=0}}});
 // après 1789, la ferveur devient aussi conviction : une île fervente se tient mieux
 if(apres89()){const f=stM((S.pp||[]).filter(adulte),'fer');if(f>=6)fx({coh:.5})}}}
