// ===== Les âges : les enfants aident tôt, on vieillit vite =====
const ageT=p=>ageP(p);
function noble(p){if(!S.voieC)return false;if(S.nobleFa==null){const o=(S.pp||[]).filter(adulte).sort((a,b)=>ageP(b)-ageP(a))[0];S.nobleFa=o?o.fa:-1}return p.fa===S.nobleFa}
function vigueur(p){const a=ageT(p),s=noble(p)?60:40;return a<=s?1:Math.max(.35,1-(a-s)*.03)}
function tachesPossibles(p){const a=ageT(p);if(a<8)return [];if(a<12)return ['bois','eau','repos'];if(a<14)return ['bois','eau','cueil','paille','repos'];return Object.keys(TACHES)}
const gensCamp=()=>(S.pp||[]).filter(p=>ageT(p)>=8&&!enGrp(p));
