function lieuOK(p,k,t){const c=T[campDe(p)];if(!c||!t||hd(c,t)>2||t.bare)return false;const o=S.t[t.i]||{};if(!o.s||o.c)return false;if(['chasse','cueil','bois'].includes(k)&&hd(c,t)<1)return false;if(k==='chasse'&&volc(t))return false;if(k==='pierre'&&!(t.riv||t.slope>20||volc(t)))return false;if(k==='bois'&&!t.forest&&hd(c,t)>0)return false;return true}
function autoLieu(p,k){const c=T[campDe(p)];if(!c)return null;const L=T.filter(t=>hd(c,t)<=2&&lieuOK(p,k,t));if(!L.length)return null;const sc=t=>k==='chasse'?trpF(t)*10-hd(c,t):k==='cueil'?cueilV(t)-hd(c,t)*.3:-hd(c,t)+(t.forest?1:0);return L.sort((a,b)=>sc(b)-sc(a))[0].i}
