function nuitVeille(){const c=camps()[0];if(!c)return;const gd=S.garde&&ppId(S.garde);const L=gensCamp().filter(p=>adulte(p)&&p!==gd);
 let rel=L.filter(p=>(p.fat||0)<60).sort((a,b)=>(a.fat||0)-(b.fat||0))[0];const q=[];
 if(gd&&(gd.fat||0)<80){gd.fat=(gd.fat||0)+18;q.push(gd.n.split(' ')[0]+' veille la première moitié de la nuit')}else if(gd)q.push(gd.n.split(' ')[0]+' est trop épuisé pour veiller');
 if(rel){rel.fat=(rel.fat||0)+15;rel.veille=1;q.push(rel.n.split(' ')[0]+' prend la relève à mi-nuit')}
 const trou=!(gd&&(gd.fat||0)<98)||!rel;if(trou){q.push('une partie de la nuit, personne ne veille');if(rnd()<.35){const r=rnd();if(r<.5){S.vivres=Math.max(0,S.vivres-3);q.push('au matin, des '+(S.voieC?'rats':'cochons marrons')+' ont fouillé la réserve : vivres −3')}else{fx({traque:2});q.push('des traces autour du camp, que personne n’a vu passer')}}}
 journal(q.join(' ; ')+'.')}
